    ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}：咄，{PLAYER}！猶落吾後乎？吾則日進矣！多獲勁黠之獸。來，且䀩子所獲，{PLAYER}！", -- CeruleanCity
