    ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}：咄，知我適往何處乎？吾往正輝所，請其示珍獸。吾㬺獸記機所錄遂大增！正輝以怪獸癡名聞天下；算器藏取㬺獸之法，亦其所創也。子既用其法，便往謝之！吾當伆矣！", -- CeruleanCity
    ["_CeruleanCityRocketText"] = "咄！毋入！此非子庭也！何？我乎？吾乃無辜過客耳！子其不信我乎？", -- CeruleanCity
    ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER}復得技機廾八！", -- CeruleanCity
