    ["_CeruleanCityRocketIllReturnTheTMText"] = "然！吾還所竊技機！", -- CeruleanCity
    ["_CeruleanCityCooltrainerMText"] = "子亦㬺獸士乎？或獲或鬥，此業良苦。", -- CeruleanCity
    ["_CeruleanCitySuperNerd1Text"] = "肆前灌木當道，或有路可繞。", -- CeruleanCity
