    ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "隱檮杌，入甲！不！又誤矣！㬺獸難馭甚矣！獸之聽命，繫乎㬺獸士之能。", -- CeruleanCity
    ["_CeruleanCitySlowbroTookASnoozeText"] = "隱檮杌小寐矣……", -- CeruleanCity
    ["_CeruleanCitySlowbroIsLoafingAroundText"] = "隱檮杌方游惰……", -- CeruleanCity
    ["_CeruleanCitySlowbroTurnedAwayText"] = "隱檮杌掉首他顧……", -- CeruleanCity
    ["_CeruleanCitySlowbroIgnoredOrdersText"] = "隱檮杌不從令……", -- CeruleanCity
    ["_CeruleanCityCooltrainerF2Text"] = "吾欲一鮮朱自轉車！藏於家中，毋使沾塵。", -- CeruleanCity
    ["_CeruleanCitySuperNerd3Text"] = "此縹邑洞也！中居強悍㬺獸，可怖甚矣！惟㬺獸聯會之魁得入。", -- CeruleanCity
    ["_CeruleanCitySignText"] = "縹邑\n縹，水色也；神祕之色也。", -- CeruleanCity
    ["_CeruleanCityTrainerTipsText"] = "㬺獸士須知\n㬺獸方易時按乙鍵，可止其易。", -- CeruleanCity
    ["_CeruleanCityBikeShopSign"] = "草野洞穴，往來自如！自轉車肆", -- CeruleanCity
    ["_CeruleanCityGymSign"] = "縹邑㬺獸書院\n山長：霞海花 英爽人魚！", -- CeruleanCity
    ["_VermilionCityBeautyText"] = "吾邑慎防污濁。聞汶汶濁多孳息於毒泥中！", -- VermilionCity
    ["_VermilionCityGambler1DidYouSeeText"] = "見聖亞納號泊於港乎？", -- VermilionCity
    ["_VermilionCityGambler1SSAnneDepartedText"] = "聖亞納號已發矣！明歲當復來。", -- VermilionCity
    ["_VermilionCitySailor1WelcomeToSSAnneText"] = "請登聖亞納號！", -- VermilionCity
    ["_VermilionCitySailor1DoYouHaveATicketText"] = "請登聖亞納號！\f敢問有船票乎？", -- VermilionCity
    ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER}出示船票！\f善！請登聖亞納號！", -- VermilionCity
    ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER}無所需船票。\f恕之！無票不得登船。", -- VermilionCity
    ["_VermilionCitySailor1ShipSetSailText"] = "船已解纜。", -- VermilionCity
    ["_VermilionCityGambler2Text"] = "吾將於此築屋。吾獸方蹋土使平。", -- VermilionCity
    ["_VermilionCityMachopText"] = "空手徒：嗬！嗬嗬嗬！", -- VermilionCity
    ["_VermilionCityMachopStompingTheLandFlatText"] = "空手徒正蹋地使平。", -- VermilionCity
    ["_VermilionCitySailor2Text"] = "聖亞納號，名遊舶也；歲一至朱邑。", -- VermilionCity
    ["_VermilionCitySignText"] = "朱邑\n朱，夕霞之色也。", -- VermilionCity
    ["_VermilionCityNoticeSignText"] = "告示\n第十二道或有㬺獸酣眠塞路。往紫村者，請繞岩山隧。朱邑巡捕", -- VermilionCity
    ["_VermilionCityPokemonFanClubSignText"] = "㬺獸好者會\n好㬺獸者皆可入！", -- VermilionCity
    ["_VermilionCityGymSignText"] = "朱邑㬺獸書院\n山長：馬志士 霆電美利堅人！", -- VermilionCity
    ["_VermilionCityHarborSignText"] = "朱邑港", -- VermilionCity
    ["_CeladonCityLittleGirlText"] = "吾於丹州得瘴球。其性頗馴，怒則吐毒氣！", -- CeladonCity
    ["_CeladonCityGramps1Text"] = "嘿嘿！此書院妙甚，滿院皆女也！", -- CeladonCity
    ["_CeladonCityGirlText"] = "博場有損吾邑之名！", -- CeladonCity
    ["_CeladonCityGramps2Text"] = "嗟乎！籌盡輸於博機矣！早知當以籌易賞。", -- CeladonCity
    ["_CeladonCityGramps3Text"] = "幸會！屢見子而未得與言。子既過此，贈子一物！", -- CeladonCity
    ["_CeladonCityGramps3ReceivedTM41Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CeladonCity
    ["_CeladonCityGramps3TM41ExplanationText"] = "技機卌一載生卵。惟一獸能習之，卵生保也！", -- CeladonCity
    ["_CeladonCityGramps3TM41NoRoomText"] = "行囊已滿。", -- CeladonCity
    ["_CeladonCityFisherText"] = "此吾信友蚊香泳士也！吾以水石施於蚊香君，遂易為此。", -- CeladonCity
    ["_CeladonCityPoliwrathText"] = "蚊香泳士：哩嗶！哩嗶！", -- CeladonCity
    ["_CeladonCityRocket1Text"] = "視我何為？", -- CeladonCity
    ["_CeladonCityRocket2Text"] = "莫當火箭賊之道！", -- CeladonCity
    ["_CeladonCityTrainerTips1Text"] = "㬺獸士須知\n必中丸使所施之技必中！中要害丸增擊中要害之機！皆售於青邑百貨肆！", -- CeladonCity
    ["_CeladonCitySignText"] = "青邑\n虹色，夢之色也。", -- CeladonCity
    ["_CeladonCityGymSignText"] = "青邑㬺獸書院\n山長：麥恵梨香 好自然之姬！", -- CeladonCity
    ["_CeladonCityMansionSignText"] = "青邑館", -- CeladonCity
    ["_CeladonCityDeptStoreSignText"] = "所需皆備於青邑百貨肆！", -- CeladonCity
    ["_CeladonCityTrainerTips2Text"] = "㬺獸士須知\n守常可護㬺獸，使其諸能不為敵技所減。售於青邑百貨肆！", -- CeladonCity
    ["_CeladonCityPrizeExchangeSignText"] = "籌可易賞！易賞所", -- CeladonCity
    ["_CeladonCityGameCornerSignText"] = "火箭博場\n大人遊戲之所！", -- CeladonCity
    ["_FuchsiaCityYoungster1Text"] = "試過獲獸戲乎？有些㬺獸惟彼處可獲。", -- FuchsiaCity
    ["_FuchsiaCityGamblerText"] = "獲獸帶入口前有獸苑，後方乃獲獸戲之場。", -- FuchsiaCity
    ["_FuchsiaCityErikText"] = "弘二：怪哉！敦子約吾乘鳥獸相會……鳥獸竟尋不得！", -- FuchsiaCity
    ["_FuchsiaCityYoungster2Text"] = "其中似物毬者，實㬺獸也。", -- FuchsiaCity
    ["_FuchsiaCityPokemonText"] = "！", -- FuchsiaCity
    ["_FuchsiaCitySignText"] = "縓邑\n縓，花之色也。", -- FuchsiaCity
    ["_FuchsiaCitySafariGameSignText"] = "獲獸戲 任子獲獸！", -- FuchsiaCity
    ["_FuchsiaCityWardensHomeSignText"] = "獲獸帶守人之宅", -- FuchsiaCity
    ["_FuchsiaCitySafariZoneSignText"] = "㬺獸樂土\n獲獸帶", -- FuchsiaCity
    ["_FuchsiaCityGymSignText"] = "縓邑㬺獸書院\n山長：桔杏 毒術忍師！", -- FuchsiaCity
    ["_FuchsiaCityChanseySignText"] = "名：卵生保\n得之惟幸。", -- FuchsiaCity
    ["_FuchsiaCityVoltorbSignText"] = "名：霆毬\n其形宛如獸毬。", -- FuchsiaCity
    ["_FuchsiaCityKangaskhanSignText"] = "名：汗袋獸\n母獸也，腹有囊以育其子。", -- FuchsiaCity
    ["_FuchsiaCitySlowpokeSignText"] = "名：鈍饕餮\n性親人，行甚遲。", -- FuchsiaCity
    ["_FuchsiaCityLaprasSignText"] = "名：海贔屭\n又號海中之王。", -- FuchsiaCity
    ["_FuchsiaCityFossilSignOmanyteText"] = "名：菊石獸\n自僵石復生之獸。", -- FuchsiaCity
    ["_FuchsiaCityFossilSignKabutoText"] = "名：讙兜鱟\n自僵石復生之獸。", -- FuchsiaCity
    ["_FuchsiaCityFossilSignUndeterminedText"] = "……", -- FuchsiaCity
    ["_BluesHouseDaisyRivalAtLabText"] = "{PLAYER}，安！{RIVAL}在大父驗室。", -- BluesHouse
    ["_BluesHouseDaisyOfferMapText"] = "大父使子辦事乎？此物可助子。", -- BluesHouse
    ["_GotMapText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- BluesHouse
    ["_BluesHouseDaisyBagFullText"] = "行囊已滿。", -- BluesHouse
    ["_BluesHouseDaisyUseMapText"] = "用縣圖可知所在。", -- BluesHouse
    ["_BluesHouseDaisyWalkingText"] = "㬺獸亦生物也！疲則使之休息。", -- BluesHouse
    ["_BluesHouseTownMapText"] = "大圖也！甚有用。", -- BluesHouse
    ["_IndigoPlateauLobbyGymGuideText"] = "咄！將為魁者！入㬺獸聯會，須連戰四天王。若一敗，則自初更戰。此其時也！勉之！", -- IndigoPlateauLobby
    ["_IndigoPlateauLobbyCooltrainerFText"] = "自此四天王次第相待。勝一人，則次門乃開。善自為之！", -- IndigoPlateauLobby
    ["_SilphCo4FSilphWorkerMImHidingText"] = "噓！不見吾匿此乎？", -- SilphCo4F
    ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "何？火箭賊已去乎？", -- SilphCo4F
    ["_SilphCo4FRocket1BattleText"] = "火箭賊已據氣仙公司！", -- SilphCo4F
    ["_SilphCo4FRocket1EndBattleText"] = "嗚呼！", -- SilphCo4F
    ["_SilphCo4FRocket1AfterBattleText"] = "哈哈哈！吾首領久欲取此地！", -- SilphCo4F
    ["_SilphCo4FScientistBattleText"] = "吾㬺獸皆忠卒也！", -- SilphCo4F
    ["_SilphCo4FScientistEndBattleText"] = "可惱！弱獸無用！", -- SilphCo4F
    ["_SilphCo4FScientistAfterBattleText"] = "諸門皆以電機鎖之，惟管鑰票可啟！", -- SilphCo4F
    ["_SilphCo4FRocket2BattleText"] = "見有闖入者！", -- SilphCo4F
    ["_SilphCo4FRocket2EndBattleText"] = "子何人也？", -- SilphCo4F
    ["_SilphCo4FRocket2AfterBattleText"] = "吾當告十一層之首領！", -- SilphCo4F
    ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "火箭賊因一闖入者大亂。即子乎？", -- SilphCo5F
    ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "火箭賊為子所逐！子乃吾等恩人，多謝！", -- SilphCo5F
    ["_SilphCo5FRocket1BattleText"] = "聞有童子在此徘徊。", -- SilphCo5F
    ["_SilphCo5FRocket1EndBattleText"] = "轟！", -- SilphCo5F
    ["_SilphCo5FRocket1AfterBattleText"] = "與火箭賊啟釁，非智也！", -- SilphCo5F
    ["_SilphCo5FScientistBattleText"] = "此層專究獸毬之術！", -- SilphCo5F
    ["_SilphCo5FScientistEndBattleText"] = "咄！可惱！", -- SilphCo5F
    ["_SilphCo5FScientistAfterBattleText"] = "吾等嘗製至極獸毬，欲使萬獸無不可獲。", -- SilphCo5F
    ["_SilphCo5FRockerBattleText"] = "何？此地不應有童子！", -- SilphCo5F
    ["_SilphCo5FRockerEndBattleText"] = "嗚呼！", -- SilphCo5F
    ["_SilphCo5FRockerAfterBattleText"] = "才至第五層耳；距吾首領尚遠！", -- SilphCo5F
    ["_SilphCo5FRocket2BattleText"] = "對火箭賊當知敬畏！", -- SilphCo5F
    ["_SilphCo5FRocket2EndBattleText"] = "咳……咳……", -- SilphCo5F
    ["_SilphCo5FRocket2AfterBattleText"] = "說來，瘴球可易為氛氳瘴！", -- SilphCo5F
    ["_SilphCo5FPokemonReport1Text"] = "㬺獸報告 丹驗室造三樊獸，為首創虛境㬺獸。", -- SilphCo5F
    ["_SilphCo5FPokemonReport2Text"] = "㬺獸報告 已驗㬺獸技逾百六十種。", -- SilphCo5F
    ["_SilphCo5FPokemonReport3Text"] = "㬺獸報告 有四種㬺獸，惟以線相聯而互易，乃能易形。", -- SilphCo5F
    ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "火箭賊來據此樓！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "善，吾當復業矣！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "嗚呼，救我！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "吾與彼已定婚矣！嘿嘿！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "觀彼！怯夫也！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "憫之甚，吾只得嫁之矣！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "火箭賊欲藉㬺獸霸天下！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "火箭賊因子而遁！", -- SilphCo6F
    ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "彼必為吾公司㬺獸製品而來。", -- SilphCo6F
    ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "子長成後，來氣仙公司供職！", -- SilphCo6F
    ["_SilphCo6FRocket1BattleText"] = "吾乃火箭四兄弟之一！", -- SilphCo6F
    ["_SilphCo6FRocket1EndBattleText"] = "熄矣！", -- SilphCo6F
    ["_SilphCo6FRocket1AfterBattleText"] = "無妨！吾兄弟當為我報仇！", -- SilphCo6F
    ["_SilphCo6FScientistBattleText"] = "那可惡總辦！不當遣我赴石泉通古斯河分號！", -- SilphCo6F
    ["_SilphCo6FScientistEndBattleText"] = "咄！", -- SilphCo6F
    ["_SilphCo6FScientistAfterBattleText"] = "石泉通古斯河分號乎？在俄羅斯深處！", -- SilphCo6F
    ["_SilphCo6FRocket2BattleText"] = "子敢叛火箭賊乎？", -- SilphCo6F
    ["_SilphCo6FRocket2EndBattleText"] = "叛徒！", -- SilphCo6F
    ["_SilphCo6FRocket2AfterBattleText"] = "既為義而立，自叛邪矣！", -- SilphCo6F
    ["_CinnabarIslandDoorIsLockedText"] = "門鎖矣……", -- CinnabarIsland
    ["_CinnabarIslandGirlText"] = "丹州書院山長桂夏，奇士也，居此數十年矣。", -- CinnabarIsland
    ["_CinnabarIslandGamblerText"] = "諸格致家於焚圮之屋中作驗。", -- CinnabarIsland
    ["_CinnabarIslandSignText"] = "丹州\n丹，熱情之色也。", -- CinnabarIsland
    ["_CinnabarIslandPokemonLabSignText"] = "丹驗室", -- CinnabarIsland
    ["_CinnabarIslandGymSignText"] = "丹州㬺獸書院\n山長：桂夏 熱血問答翁！", -- CinnabarIsland
    ["_Route1Youngster1MartSampleText"] = "安！吾在雜貨肆供職。其肆便於市物，在碧邑，幸來顧。且贈子一試用品。奉上！", -- Route1
    ["_Route1Youngster1GotPotionText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- Route1
    ["_Route1Youngster1AlsoGotPokeballsText"] = "本肆亦售獸毬，可獲㬺獸！", -- Route1
    ["_Route1Youngster1NoRoomText"] = "行囊已滿！", -- Route1
    ["_Route1Youngster2Text"] = "見路旁高坎乎？稍可怖，然可躍下。由此返素村尤捷。", -- Route1
    ["_Route1SignText"] = "第一道\n自素村至碧邑", -- Route1
    ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}：咄，{PLAYER}！大父不在。", -- OaksLab
    ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}：哼！吾豈若子貪乎？{PLAYER}，子先擇之！", -- OaksLab
    ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}：䀩吾獸，似強多矣。", -- OaksLab
    ["_OaksLabThoseArePokeBallsText"] = "彼皆獸毬，內有㬺獸。", -- OaksLab
    ["_OaksLabYouWantCharmanderText"] = "然！子欲取火獸熛螭乎？", -- OaksLab
    ["_OaksLabYouWantSquirtleText"] = "然！子欲取水獸朋龜乎？", -- OaksLab
    ["_OaksLabYouWantBulbasaurText"] = "然！子欲取草獸奇種蛙乎？", -- OaksLab
    ["_OaksLabMonEnergeticText"] = "此獸甚健！", -- OaksLab
    ["_OaksLabReceivedMonText"] = "{PLAYER}得{RAM:wNameBuffer}！", -- OaksLab
    ["_OaksLabLastMonText"] = "此乃大木博士所餘最後一獸。", -- OaksLab
    ["_OaksLabOak1WhichPokemonDoYouWantText"] = "大木：{PLAYER}，今欲何獸？", -- OaksLab
    ["_OaksLabOak1YourPokemonCanFightText"] = "大木：若野獸出，子之㬺獸可與之鬭！", -- OaksLab
    ["_OaksLabOak1RaiseYourYoungPokemonText"] = "大木：{PLAYER}，令幼獸多戰以長之！", -- OaksLab
    ["_OaksLabOak1DeliverParcelText"] = "大木：哦，{PLAYER}！吾所與之獸如何？觀其甚親子。子必善為㬺獸士！何？有物與我乎？ {PLAYER}以大木所寄之物奉還。", -- OaksLab
    ["_OaksLabOak1ParcelThanksText"] = "啊！此乃吾所訂特製獸毬！多謝。", -- OaksLab
    ["_OaksLabOak1PokemonAroundTheWorldText"] = "天下㬺獸待子矣，{PLAYER}！", -- OaksLab
    ["_OaksLabOak1ReceivedPokeballsText"] = "大木：徒見之不能詳錄㬺獸，必獲之。以此獲野獸。{PLAYER}得獸毬五枚！", -- OaksLab
    ["_OaksLabGivePokeballsExplanationText"] = "野獸既出，即可獲之。投獸毬而試取之！然未必得。健獸或逸，亦須有幸。", -- OaksLab
    ["_OaksLabOak1ComeSeeMeSometimesText"] = "大木：時來見我。我欲知子㬺獸記機所錄如何。", -- OaksLab
    ["_OaksLabOak1HowIsYourPokedexComingText"] = "大木：善來！所錄如何？來，容我一觀！", -- OaksLab
    ["_OaksLabPokedexText"] = "形似圖譜，頁皆空白！", -- OaksLab
    ["_OaksLabOak2Text"] = "？", -- OaksLab
    ["_OaksLabGirlText"] = "大木博士精㬺獸之學，㬺獸士多推重之！", -- OaksLab
    ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}：大父！久候可厭矣！", -- OaksLab
    ["_OaksLabOakChooseMonText"] = "大木：{RIVAL}？容我思之……哦，是矣，吾召子來。且待！來，{PLAYER}！此有㬺獸三。哈哈！皆在獸毬中。吾少時篤為㬺獸士，今老矣，所餘惟三；可與子一。擇之！", -- OaksLab
    ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}：大父！吾亦何如？", -- OaksLab
    ["_OaksLabOakBePatientText"] = "大木：毋躁！{RIVAL}，亦與子一。", -- OaksLab
    ["_OaksLabOakDontGoAwayYetText"] = "大木：且住！勿遽去！", -- OaksLab
    ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}：然則吾取此。", -- OaksLab
    ["_OaksLabRivalReceivedMonText"] = "{RIVAL}得{RAM:wNameBuffer}！", -- OaksLab
    ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}：且住，{PLAYER}！試吾與子之獸。來，與我展！", -- OaksLab
    ["_OaksLabRivalIPickedTheWrongPokemonText"] = "何！難信也！吾擇錯獸矣！", -- OaksLab
    ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}：哈哈！吾濯乎？", -- OaksLab
    ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}：善！吾使獸多戰，使之益鑙。{PLAYER}！大父！吾伆矣！", -- OaksLab
    ["_OaksLabRivalGrampsText"] = "{RIVAL}：大父！", -- OaksLab
    ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}：召我何事？", -- OaksLab
    ["_OaksLabOakIHaveARequestText"] = "大木：哦，是矣！有一事欲託汝二人。", -- OaksLab
    ["_OaksLabOakMyInventionPokedexText"] = "案上者，吾所製㬺獸記機也！凡所見所獲之㬺獸，其詳自錄。此新式圖譜也！", -- OaksLab
    ["_OaksLabOakGotPokedexText"] = "大木：{PLAYER}、{RIVAL}！各攜此去！{PLAYER}自大木得㬺獸記機！", -- OaksLab
    ["_OaksLabOakThatWasMyDreamText"] = "盡錄天下㬺獸，成一完備圖譜……此吾夢也！然吾老矣，力不能及。故欲汝二人代成吾志！速行！此乃㬺獸史上一大業也！", -- OaksLab
    ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}：大父，盡委於我！{PLAYER}，雖難言，然吾無須子。吾向姊借縣圖，且囑其毋借與子，{PLAYER}！哈哈！", -- OaksLab
    ["_OaksLabScientistText"] = "吾佐大木博士研究㬺獸。", -- OaksLab
    ["_ViridianMartClerkSayHiToOakText"] = "好！代我問大木博士安。", -- ViridianMart
    ["_ViridianMartClerkYouCameFromPalletTownText"] = "喂！子自素村來乎？", -- ViridianMart
    ["_ViridianMartClerkParcelQuestText"] = "識大木博士乎？其所訂之物已至。可為我送之乎？{PLAYER}得大木所寄之物！", -- ViridianMart
    ["_ViridianMartYoungsterText"] = "此肆多售解毒丸。", -- ViridianMart
    ["_ViridianMartCooltrainerMText"] = "不巧！體補皆售罄矣。", -- ViridianMart
    ["_ViridianSchoolHouseBrunetteGirlText"] = "呼！吾正強記諸筆記。", -- ViridianSchoolHouse
    ["_ViridianSchoolHouseCooltrainerFText"] = "好！黑板所書，須細讀之。", -- ViridianSchoolHouse
    ["_ViridianNicknameHouseBaldingGuyText"] = "命別名可喜而甚難。名簡者最易記。", -- ViridianNicknameHouse
    ["_ViridianNicknameHouseLittleGirlText"] = "吾父亦嗜㬺獸。", -- ViridianNicknameHouse
    ["_ViridianNicknameHouseSpearowText"] = "鶪兒：啾啾！", -- ViridianNicknameHouse
    ["_ViridianNicknameHouseSpearySignText"] = "鬼鶪 名曰鶪兒", -- ViridianNicknameHouse
    ["_PewterNidoranHouseNidoranText"] = "雄鍼兔：汪汪！", -- PewterNidoranHouse
    ["_PewterNidoranHouseLittleBoyText"] = "雄鍼兔，坐！", -- PewterNidoranHouse
    ["_PewterNidoranHouseMiddleAgedManText"] = "吾家此獸得自外人，故難馴。所謂外來獸，乃與他人易得之㬺獸也。其長甚速，然士術未精，戰時或不受命。若有徽章便好了……", -- PewterNidoranHouse
    ["_PewterSpeechHouseGamblerText"] = "㬺獸隨長而習新技；然亦有技，須士授之。", -- PewterSpeechHouse
    ["_PewterSpeechHouseYoungsterText"] = "獸傷或寐，則較易獲。然亦未必。", -- PewterSpeechHouse
    ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "可恨火箭賊！且觀所為！竊我技機，內載掘穴之法。此物費我多金！", -- CeruleanTrashedHouse
    ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "失者已失，吾亦釋然。今教小潛鼴自習掘穴，不復藉技機！", -- CeruleanTrashedHouse
    ["_CeruleanTrashedHouseGirlText"] = "火箭賊必欲掘穴作惡！", -- CeruleanTrashedHouse
    ["_CeruleanTrashedHouseWallHoleText"] = "火箭賊鑿壁，適遺一出路。", -- CeruleanTrashedHouse
    ["_CeruleanTradeHouseGrannyText"] = "吾夫好與人互易㬺獸。子若好藏獸，可與之易乎？", -- CeruleanTradeHouse
    ["_BikeShopClerkWelcomeText"] = "客來自轉車肆！適有一車甚宜子！", -- BikeShop
    ["_BikeShopClerkDoYouLikeItText"] = "此車甚佳！欲之乎？", -- BikeShop
    ["_BikeShopCantAffordText"] = "恕之！子資不足。", -- BikeShop
    ["_BikeShopClerkOhThatsAVoucherText"] = "哦，此乃……自轉車票！善，奉車一乘！", -- BikeShop
    ["_BikeShopExchangedVoucherText"] = "{PLAYER}以自轉車票換得自轉車。", -- BikeShop
    ["_BikeShopComeAgainText"] = "他日復來！", -- BikeShop
    ["_BikeShopClerkHowDoYouLikeYourBicycleText"] = "新車如何？自轉車道與洞中皆可騎之！", -- BikeShop
    ["_BikeShopBagFullText"] = "須先空行囊一隙！", -- BikeShop
    ["_BikeShopMiddleAgedWomanText"] = "吾用尋常市中自轉車足矣！山地車又不能置買物籃。", -- BikeShop
    ["_BikeShopYoungsterTheseBikesAreExpensiveText"] = "此諸車甚佳，惜價太昂！", -- BikeShop
    ["_BikeShopYoungsterCoolBikeText"] = "嘖嘖！子之車真佳！", -- BikeShop
    ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "怪哉，富士老人不在。往何處矣？", -- MrFujisHouse
    ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "富士老人嘗獨為髑髏螭之母祈禱。", -- MrFujisHouse
    ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "此真富士老人之宅。老人仁厚，收養見棄及無親之㬺獸。", -- MrFujisHouse
    ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "暖甚！㬺獸抱之可愛！", -- MrFujisHouse
    ["_MrFujisHousePsyduckText"] = "八卦鴨：呱啪！", -- MrFujisHouse
    ["_MrFujisHouseNidorinoText"] = "桂兔君：嗷！", -- MrFujisHouse
    ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "富士老人：{PLAYER}。子欲成㬺獸記機之事，若不愛其獸，恐終不成。老身以為此物可助子。", -- MrFujisHouse
    ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- MrFujisHouse
    ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "凡眠獸聞㬺獸籥，皆霍然而寤。無論何獸，眠者皆然。", -- MrFujisHouse
    ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "須先空行囊一隙！", -- MrFujisHouse
    ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "富士老人：老身之籥可曾助子？", -- MrFujisHouse
    ["_MrFujisHouseMrFujiPokedexText"] = "《㬺獸月刊》大賞抽籤！申請紙……無矣！已有人剪去！", -- MrFujisHouse
    ["_LavenderCuboneHouseCuboneText"] = "髑髏螭：嘎嚕嗚！", -- LavenderCuboneHouse
    ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "吾恨火箭賊！可憐髑髏螭之母……欲逃彼賊，竟為所殺！", -- LavenderCuboneHouse
    ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "㬺獸塔之鬼已去！必有人安其不寧之魂。", -- LavenderCuboneHouse
    ["_NameRatersHouseNameRaterWantMeToRateText"] = "幸會！吾乃名師。欲使吾評子獸之別名乎？", -- NameRatersHouse
    ["_NameRatersHouseNameRaterWhichPokemonText"] = "欲評何獸？", -- NameRatersHouse
    ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}乎？此別名尚可。然欲令吾更其名，使之尤佳乎？如何？", -- NameRatersHouse
    ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "善！當名之何？", -- NameRatersHouse
    ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "善！此獸今改名{RAM:wBuffer}！勝於舊名矣！", -- NameRatersHouse
    ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "善！子欲來時皆可來。", -- NameRatersHouse
    ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}乎？此名至善，無可議！善養{RAM:wNameBuffer}！", -- NameRatersHouse
    ["_VermilionPidgeyHouseYoungsterText"] = "吾使蒙雀飛書北至黃邑！", -- VermilionPidgeyHouse
    ["_VermilionPidgeyHousePidgeyText"] = "蒙雀：咕嚕咕！", -- VermilionPidgeyHouse
    ["_VermilionPidgeyHouseLetterText"] = "花魄足下：盼早相見。聞黃邑苦火箭賊，朱邑則安。", -- VermilionPidgeyHouse
    ["_CeladonMansionRoofHouseHikerText"] = "子遊戲機中㬺獸之事，吾無不知！與友相聚，以連接線互易㬺獸！", -- CeladonMansionRoofHouse
    ["_FuchsiaMartMiddleAgedManText"] = "有獲獸帶之旗乎？牌與曆又如何？", -- FuchsiaMart
    ["_FuchsiaMartCooltrainerFText"] = "試過增速丸乎？戰中可增獸速！", -- FuchsiaMart
    ["_SaffronPidgeyHouseBrunetteGirlText"] = "謝子來書，盼早相見！咄！勿窺吾書！", -- SaffronPidgeyHouse
    ["_SaffronPidgeyHousePidgeyText"] = "蒙雀：咕嚕咕！", -- SaffronPidgeyHouse
    ["_SaffronPidgeyHouseYoungsterText"] = "仿娘甚可愛！吾正欲贈她明魄偶。", -- SaffronPidgeyHouse
    ["_SaffronPidgeyHousePaperText"] = "人贈我技力增一枚。此物可增一技之技力上限！", -- SaffronPidgeyHouse
    ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "止！毋言。兆曰：子欲此。", -- MrPsychicsHouse
    ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- MrPsychicsHouse
    ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "卜辭爺：技機廾九載念動。中之，異能或衰。", -- MrPsychicsHouse
    ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "此將置何所？", -- MrPsychicsHouse
    ["_DiglettsCaveRoute2FishingGuruText"] = "吾嘗往岩山隧，幽暗可怖。若有獸能以閃光照之……", -- DiglettsCaveRoute2
    ["_Route2TradeHouseScientistText"] = "獸既仆，不能戰；然切等技猶可用。", -- Route2TradeHouse
    ["_SaffronGateGuardGeeImThirstyText"] = "吾方守關，然渴甚！且住，道閉矣。", -- SaffronGates
    ["_SaffronGateGuardImParchedText"] = "嗚呼，渴甚矣！……何？此飲可與我乎？多謝！", -- SaffronGates
    ["_SaffronGateGuardYouCanGoOnThroughText"] = "……咕嚕咕嚕……嚥！欲往黃邑乎？……可通矣。此飲吾亦分與諸守者！", -- SaffronGates
    ["_SaffronGateGuardThanksForTheDrinkText"] = "多謝子之佳飲！", -- SaffronGates
    ["_UndergroundPathRoute8GirlText"] = "青邑百貨肆，百物備具！", -- UndergroundPathRoute8
    ["_PowerPlantVoltorbBattleText"] = "滋滋！", -- PowerPlant
    ["_DiglettsCaveRoute11GamblerText"] = "奇哉！小潛鼴鑿此長隧，直通碧邑！", -- DiglettsCaveRoute11
    ["_Route16FlyHouseBrunetteGirlText"] = "啊，子竟尋得吾祕居！幸勿告人。以此酬子守祕之惠！", -- Route16FlyHouse
    ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER}得祕傳機二！", -- Route16FlyHouse
    ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "祕傳機二載飛。可飛返諸邑，善用之！", -- Route16FlyHouse
    ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "行囊無隙可納。", -- Route16FlyHouse
    ["_Route16FlyHouseFearowText"] = "鑽鷲：啾咿！", -- Route16FlyHouse
    ["_Route22GateGuardNoBoulderbadgeText"] = "惟技藝真精之士得過。子尚無灰徽！", -- Route22Gate
    ["_Route22GateGuardICantLetYouPassText"] = "法既如此，吾不能縱子過。", -- Route22Gate
    ["_Route22GateGuardGoRightAheadText"] = "哦，此乃灰徽！請過！", -- Route22Gate
    ["_BillsHouseBillImNotAPokemonText"] = "正輝：喂！吾是㬺獸……不，非也！呼我正輝，真怪獸癡也！何故睇我狐疑若此？吾非誑子，作驗失手，乃與一獸合體。子其助我乎？", -- BillsHouse
    ["_BillsHouseBillUseSeparationSystemText"] = "吾入瞬移機後，子往算器，啟其細胞分離器！", -- BillsHouse
    ["_BillsHouseBillNoYouGottaHelpText"] = "不乎？咄！吾困甚，總須助我！如何，老兄？求子矣！欸？欸，便如此！", -- BillsHouse
    ["_BillsHouseBillThankYouText"] = "正輝：苦哉！多謝，友！吾負子一惠。子是來觀吾所藏㬺獸乎？非乎？可惜。總須謝子……哦，此物或可。", -- BillsHouse
    ["_SSTicketReceivedText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- BillsHouse
    ["_SSTicketNoRoomText"] = "友，子物已太多矣！", -- BillsHouse
    ["_BillsHouseBillWhyDontYouGoInsteadOfMeText"] = "聖亞納號今泊朱邑，乘者皆㬺獸士。彼邀我赴宴，然我不耐盛會。子代我往何如？", -- BillsHouse
    ["_BillsHouseBillCheckOutMyRarePokemonText"] = "正輝：友，且睇吾算器中幾隻珍獸！", -- BillsHouse
    ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "子信有鬼乎？", -- LavenderTown
    ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "果然？原來真有信者……", -- LavenderTown
    ["_LavenderTownLittleGirlHaHaGuessNotText"] = "哈哈，想來不信。子肩上那白手，亦非真也。", -- LavenderTown
    ["_LavenderTownCooltrainerMText"] = "此村以㬺獸塋地聞名；㬺獸塔中修追薦之禮。", -- LavenderTown
    ["_LavenderTownSuperNerdText"] = "㬺獸塔中有鬼現。吾意乃火箭賊所殺㬺獸之魂。", -- LavenderTown
    ["_LavenderTownSignText"] = "紫村\n紫，尊貴之色也。", -- LavenderTown
    ["_LavenderTownSilphScopeSignText"] = "新製氣仙鬼鏡！使不可見者昭然可睹！氣仙公司", -- LavenderTown
    ["_LavenderTownPokemonHouseSignText"] = "紫村志願㬺獸之家", -- LavenderTown
    ["_LavenderTownPokemonTowerSignText"] = "願㬺獸之魂安息 㬺獸塔", -- LavenderTown
    ["_ViridianPokecenterGentlemanText"] = "彼角算器可用，接待員告我。甚厚意！", -- ViridianPokecenter
    ["_ViridianPokecenterCooltrainerMText"] = "前方諸邑皆有㬺獸中心，且不取費！", -- ViridianPokecenter
    ["_PokemonMansion1FScientistBattleText"] = "子何人也？此處本不應有人。", -- PokemonMansion1F
    ["_PokemonMansion1FScientistEndBattleText"] = "痛哉！", -- PokemonMansion1F
    ["_PokemonMansion1FScientistAfterBattleText"] = "管鑰乎？吾不知子所言。", -- PokemonMansion1F
    ["_PokemonMansion1FSwitchText"] = "有隱按機！按之乎？", -- PokemonMansion1F
    ["_PokemonMansion1FSwitchPressedText"] = "孰不按之？", -- PokemonMansion1F
    ["_PokemonMansion1FSwitchNotPressedText"] = "未可也！", -- PokemonMansion1F
    ["_RockTunnel1FHiker1BattleText"] = "童子，此隧綿遠甚矣！", -- RockTunnel1F
    ["_RockTunnel1FHiker1EndBattleText"] = "咄！子勝矣！", -- RockTunnel1F
    ["_RockTunnel1FHiker1AfterBattleText"] = "慎大岩蛇！其身纏絞，可困子獸。", -- RockTunnel1F
    ["_RockTunnel1FHiker2BattleText"] = "唔……吾或迷於此矣。", -- RockTunnel1F
    ["_RockTunnel1FHiker2EndBattleText"] = "且緩！吾在作何？出口安在？", -- RockTunnel1F
    ["_RockTunnel1FHiker2AfterBattleText"] = "第十二道有獸酣眠塞路，迫吾繞行此隧。", -- RockTunnel1F
    ["_RockTunnel1FHiker3BattleText"] = "外來者如子，當知敬我！", -- RockTunnel1F
    ["_RockTunnel1FHiker3EndBattleText"] = "吾服矣！", -- RockTunnel1F
    ["_RockTunnel1FHiker3AfterBattleText"] = "子有登山之才！", -- RockTunnel1F
    ["_RockTunnel1FSuperNerdBattleText"] = "㬺獸相鬥！備乎？始！", -- RockTunnel1F
    ["_RockTunnel1FSuperNerdEndBattleText"] = "戲終矣！", -- RockTunnel1F
    ["_RockTunnel1FSuperNerdAfterBattleText"] = "罷了，吾且行且獲一歃蝙蝠。", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF1BattleText"] = "呀！幽暗中毋作怪事！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF1EndBattleText"] = "太暗矣！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "吾於此隧見過空手徒！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF2BattleText"] = "吾為求㬺獸遠來至此！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF2EndBattleText"] = "吾獸盡矣！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "觀子嬌小無害，故輕之矣！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF3BattleText"] = "子有㬺獸！來戰！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF3EndBattleText"] = "子戰甚猛！", -- RockTunnel1F
    ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "呼！汗流滿身矣！", -- RockTunnel1F
    ["_RockTunnel1FSignText"] = "岩山隧\n縹邑至紫村", -- RockTunnel1F
    ["_SSAnne3FSailorText"] = "吾船長精劍術，亦能授㬺獸以切！", -- SSAnne3F
    ["_VictoryRoad3FCooltrainerM1BattleText"] = "聞有童子奇才，今果來乎！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "傳聞果真！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "子竟勝火箭賊之榊岸邊乎？", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerF1BattleText"] = "吾試子技藝高下！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "怒甚！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "子反使吾自知技藝高下矣！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerM2BattleText"] = "惟被選之士得過此！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "吾不信也！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "此間諸士皆往㬺獸聯會。慎之！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerF2BattleText"] = "㬺獸士生而求更強之敵！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "嗚呼，何強也！", -- VictoryRoad3F
    ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "歷艱戰則益強！", -- VictoryRoad3F
    ["_RocketHideoutB1FRocket5EndBattleText"] = "何故……？", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket1BattleText"] = "子何人？何由至此？", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket1EndBattleText"] = "痛哉！敗矣！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket1AfterBattleText"] = "子敢輕侮火箭賊乎？", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket2BattleText"] = "子竟闖入吾等之事乎？", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket2EndBattleText"] = "又焦矣！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket2AfterBattleText"] = "小兒，此事不得善罷！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket3BattleText"] = "有闖入者！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket3EndBattleText"] = "吾不能矣！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket3AfterBattleText"] = "氣仙鬼鏡乎？吾不知在何處！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket4BattleText"] = "子來此何為？", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket4EndBattleText"] = "此不可也！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket4AfterBattleText"] = "善，吾言之！乘昇降機可見首領！", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket5BattleText"] = "迷路乎，小鼠？", -- RocketHideoutB1F
    ["_RocketHideoutB1FRocket5AfterBattleText"] = "噫！方纔之戰竟啟此門！", -- RocketHideoutB1F
    ["_RocketHideoutB2FRocketBattleText"] = "首領曰，以氣仙鬼鏡可見鬼！", -- RocketHideoutB2F
    ["_RocketHideoutB2FRocketEndBattleText"] = "吾降矣！", -- RocketHideoutB2F
    ["_RocketHideoutB2FRocketAfterBattleText"] = "火箭賊本部地下有四層。子能至首領處乎？", -- RocketHideoutB2F
    ["_RocketHideoutB3FRocket1BattleText"] = "休干火箭賊之事！", -- RocketHideoutB3F
    ["_RocketHideoutB3FRocket1EndBattleText"] = "嗚！為子所倒！", -- RocketHideoutB3F
    ["_RocketHideoutB3FRocket1AfterBattleText"] = "氣仙鬼鏡乎？首領所竊之機也，就在此中某處。", -- RocketHideoutB3F
    ["_RocketHideout3BattleText"] = "樓上已傳言子將來！", -- RocketHideoutB3F
    ["_RocketHideout3EndBattleText3"] = "何？吾敗乎？不可！", -- RocketHideoutB3F
    ["_RocketHide3AfterBattleText3"] = "行，任子去！然欲動昇降機，須昇降機管鑰。", -- RocketHideoutB3F
    ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "善。子能至此，誠可嘉也。", -- RocketHideoutB4F
    ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "何！安有此理！", -- RocketHideoutB4F
    ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "吾見子養獸至為精勤。然子一童子，終不解吾所圖。此次吾且退讓。願後會有期……", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket1BattleText"] = "吾識子！月山之謀，為子所壞！", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket1EndBattleText"] = "又灼矣！", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket1AfterBattleText"] = "子與火箭賊有何仇怨？", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket2BattleText"] = "吾等之惡如此美，子何不見？", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket2EndBattleText"] = "哎呀呀！", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket2AfterBattleText"] = "首領！吾負子矣，罪甚！", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket3BattleText"] = "昇降機不動乎？昇降機管鑰在誰手？", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket3EndBattleText"] = "不！", -- RocketHideoutB4F
    ["_RocketHideoutB4FRocket3AfterBattleText"] = "嗚呼！吾失落昇降機管鑰矣！", -- RocketHideoutB4F
    ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "似須昇降機管鑰。", -- RocketHideoutElevator
    ["_SafariZoneEastRestHouseSignText"] = "憩舍", -- SafariZoneEast
    ["_SafariZoneEastTrainerTipsText"] = "㬺獸士須知\n惟行步時，餘時乃減！", -- SafariZoneEast
    ["_SafariZoneEastSignText"] = "中區\n北：第二區", -- SafariZoneEast
    ["_SafariZoneNorthRestHouseSignText"] = "憩舍", -- SafariZoneNorth
    ["_SafariZoneNorthTrainerTips1Text"] = "㬺獸士須知\n祕屋尚在前方！", -- SafariZoneNorth
    ["_SafariZoneNorthSignText"] = "第二區", -- SafariZoneNorth
    ["_SafariZoneNorthTrainerTips2Text"] = "㬺獸士須知\n㬺獸匿於長草！曲折行草間，可驚而出之。", -- SafariZoneNorth
    ["_SafariZoneNorthTrainerTips3Text"] = "㬺獸士須知\n尋得祕屋，可免費得祕傳機！", -- SafariZoneNorth
    ["_SafariZoneCenterRestHouseSignText"] = "憩舍", -- SafariZoneCenter
    ["_SafariZoneCenterTrainerTipsSignText"] = "㬺獸士須知\n按始鍵可觀所餘時！", -- SafariZoneCenter
    ["_SafariZoneCenterRestHouseGirlText"] = "敦子：明明約弘二同去獲獸……弘二安在？", -- SafariZoneCenterRestHouse
    ["_SafariZoneCenterRestHouseScientistText"] = "吾獲㬺獸，將攜歸贈人！", -- SafariZoneCenterRestHouse
    ["_SafariZoneWestRestHouseScientistText"] = "投石於獸，則較易獲，亦較易遁。", -- SafariZoneWestRestHouse
    ["_SafariZoneWestRestHouseCooltrainerMText"] = "投餌於獸，則較不易遁，然亦較難獲。", -- SafariZoneWestRestHouse
    ["_SafariZoneWestRestHouseSilphWorkerFText"] = "吾行甚遠，竟未見一獸合吾意。", -- SafariZoneWestRestHouse
    ["_SafariZoneEastRestHouseScientistText"] = "子獲幾獸？吾已勞甚！", -- SafariZoneEastRestHouse
    ["_SafariZoneEastRestHouseRockerText"] = "吾獲卵生保矣！此行不虛！", -- SafariZoneEastRestHouse
    ["_SafariZoneEastRestHouseSilphWorkerMText"] = "呼！嬉遊雖樂，亦疲人甚矣！", -- SafariZoneEastRestHouse
    ["_SafariZoneNorthRestHouseScientistText"] = "此地地上所得之物皆可自取。然若欲盡取，恐時先盡！", -- SafariZoneNorthRestHouse
    ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "往獲獸帶最深處，即有賞！", -- SafariZoneNorthRestHouse
    ["_SafariZoneNorthRestHouseGentlemanText"] = "吾易獸易為火獸矣！然吾友之易獸竟易為水獸。何故也？", -- SafariZoneNorthRestHouse
    ["_MewtwoBattleText"] = "咪嗚！", -- CeruleanCaveB1F
    ["_RockTunnelB1FCooltrainerF1BattleText"] = "登山者常折枝置路，以誌所經。", -- RockTunnelB1F
    ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "嗚……吾已盡力矣！", -- RockTunnelB1F
    ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "吾欲歸家！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker1BattleText"] = "哈哈！子能勝吾力乎？", -- RockTunnelB1F
    ["_RockTunnelB1FHiker1EndBattleText"] = "噫！力不及子！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker1AfterBattleText"] = "吾尚力而厭思！", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd1BattleText"] = "子有㬺獸記機乎？吾亦欲得一！", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd1EndBattleText"] = "可惱！妒子甚矣！", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "子錄成之後，可與我乎？", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd2BattleText"] = "知扮獸者乎？", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd2EndBattleText"] = "罷矣。", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "扮獸者衣作㬺獸之形，以為戲樂。", -- RockTunnelB1F
    ["_RockTunnelB1FHiker2BattleText"] = "吾獸之技，必使子泣！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker2EndBattleText"] = "吾服！子之技更精！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker2AfterBattleText"] = "山中多見石屬㬺獸。", -- RockTunnelB1F
    ["_RockTunnelB1FCooltrainerF2BattleText"] = "吾不常來此，然與子一戰！", -- RockTunnelB1F
    ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "嗚！吾敗矣！", -- RockTunnelB1F
    ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "吾愛小獸；大獸太可怖！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker3BattleText"] = "盡子所能擊我！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker3EndBattleText"] = "盡發矣！", -- RockTunnelB1F
    ["_RockTunnelB1FHiker3AfterBattleText"] = "童子，吾當養獸，終使勝子！", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd3BattleText"] = "吾在家常畫㬺獸。", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd3EndBattleText"] = "呼！疲甚矣！", -- RockTunnelB1F
    ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "吾畫者也，非鬥者。", -- RockTunnelB1F
    ["_SeafoamIslandsB4FBouldersSignText"] = "巨石或可改水流之勢！", -- SeafoamIslandsB4F
    ["_SeafoamIslandsB4FDangerSignText"] = "危險 急流！", -- SeafoamIslandsB4F
    ["_Route7UndergroundPathSignText"] = "地隧\n青邑至紫村", -- Route7
    ["_RedsHouse1FMomWakeUpText"] = "母：是矣。男兒終有離家之日，電視亦云然。鄰家大木博士正尋子。", -- RedsHouse1F
    ["_RedsHouse1FMomYouShouldRestText"] = "母：{PLAYER}！少息片時罷。", -- RedsHouse1F
    ["_RedsHouse1FMomLookingGreatText"] = "母：善！子與所攜㬺獸氣色俱佳。善自珍重！", -- RedsHouse1F
    ["_RedsHouse1FTVStandByMeMovieText"] = "電視有影戲。四童子行於鐵道。吾亦當行矣。", -- RedsHouse1F
    ["_RedsHouse1FTVWrongSideText"] = "噫，面反矣。", -- RedsHouse1F
    ["_CeladonMart3FClerkTM18PreReceiveText"] = "哦，幸會！吾終通《㬺獸》矣！子尚未通乎？此物或有用。", -- CeladonMart3F
    ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CeladonMart3F
    ["_CeladonMart3FClerkTM18ExplanationText"] = "技機十八載反擊！受常、鬥二屬之傷，後發倍還。", -- CeladonMart3F
    ["_CeladonMart3FClerkTM18NoRoomText"] = "行囊已滿！", -- CeladonMart3F
    ["_CeladonMart3FGameBoyKid1Text"] = "所獲㬺獸皆錄識別號及其主；主者，初獲其獸之士也。", -- CeladonMart3F
    ["_CeladonMart3FGameBoyKid2Text"] = "善！吾友將以汗袋獸易吾嵩團磊！", -- CeladonMart3F
    ["_CeladonMart3FGameBoyKid3Text"] = "來，嵩團磊！吾最愛嵩團磊，所藏甚多！何？嵩團磊竟易形矣！", -- CeladonMart3F
    ["_CeladonMart3FLittleBoyText"] = "互易所得之獸，可觀其識別號而辨之。", -- CeladonMart3F
    ["_CeladonMart3FSNESText"] = "超任機也！", -- CeladonMart3F
    ["_CeladonMart3FRPGText"] = "角色戲也！無暇玩此！", -- CeladonMart3F
    ["_CeladonMart3FSportsGameText"] = "競技戲也！父必喜之！", -- CeladonMart3F
    ["_CeladonMart3FPuzzleGameText"] = "解謎戲也！似甚使人耽玩！", -- CeladonMart3F
    ["_CeladonMart3FFightingGameText"] = "格鬥戲也！似頗難！", -- CeladonMart3F
    ["_CeladonMart3FCurrentFloorSignText"] = "三層：遊戲機肆", -- CeladonMart3F
    ["_CeladonMart3FPokemonPosterText"] = "赤版、青版，皆㬺獸也！", -- CeladonMart3F
    ["_CeladonMart4FSuperNerdText"] = "吾正欲買明魄偶贈吾女友！", -- CeladonMart4F
    ["_CeladonMart4FYoungsterText"] = "吾聞一妙法：遇野獸時，以明魄偶惑之，即可遁去！", -- CeladonMart4F
    ["_CeladonMart4FCurrentFloorSignText"] = "以禮見心！四層：賢者禮品 易形特賣：水火雷葉石今售！", -- CeladonMart4F
    ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "欲與彼何飲？", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "呀！甘水！多謝！此物贈子！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "{RAM:wStringBuffer}中載凍光！或可凍敵。", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "呀！氣水！多謝！此物贈子！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "{RAM:wStringBuffer}中載岩崩！或使敵畏縮不前。", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "呀！果汁！多謝！此物贈子！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER}得技機卌九！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "技機卌九載三擊！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlNoRoomText"] = "行囊無隙可納！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "不必了！吾忽不渴矣！", -- CeladonMartRoof
    ["_CeladonMartRoofSuperNerdText"] = "信乎？吾姊亦㬺獸士。然稚氣未脫，擾我甚矣！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlImThirstyText"] = "吾渴甚！欲飲物！", -- CeladonMartRoof
    ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "吾渴甚！欲飲物！與彼一飲乎？", -- CeladonMartRoof
    ["_CeladonMartRoofCurrentFloorSignText"] = "頂樓廣場：自售機", -- CeladonMartRoof
    ["_VendingMachineText1"] = "自售機也！目錄如下。", -- CeladonMartRoof
    ["_VendingMachineText4"] = "噫，錢不足！", -- CeladonMartRoof
    ["_VendingMachineText5"] = "{RAM:wStringBuffer}吐出矣！", -- CeladonMartRoof
    ["_VendingMachineText6"] = "再無隙可納物！", -- CeladonMartRoof
    ["_VendingMachineText7"] = "吾不渴！", -- CeladonMartRoof
    ["_CeladonMansion1FMeowthText"] = "五銖貓：喵！", -- CeladonMansion1F
    ["_CeladonMansion1FGrannyText"] = "吾所愛諸獸常伴我；五銖貓甚至攜錢歸家！", -- CeladonMansion1F
    ["_CeladonMansion1FClefairyText"] = "明魄：皮，皮皮皮！", -- CeladonMansion1F
    ["_CeladonMansion1FNidoranFText"] = "雌鍼兔：呀，呀嗷！", -- CeladonMansion1F
    ["_CeladonMansion1FManagersSuiteSignText"] = "青邑館 主事室", -- CeladonMansion1F
    ["_CeladonMansion2FMeetingRoomSignText"] = "株式會社遊戲狂想家\n會議室", -- CeladonMansion2F
    ["_CeladonMansion3FProgrammerText"] = "吾乎？程式皆吾所編！", -- CeladonMansion3F
    ["_CeladonMansion3FGraphicArtistText"] = "吾司圖畫！子亦吾所畫！", -- CeladonMansion3F
    ["_CeladonMansion3FWriterText"] = "故事皆吾所作！麥恵梨香可愛乎？吾亦甚愛霞海花。哦，棗夢亦佳！", -- CeladonMansion3F
    ["_CeladonMansion3FGameDesignerText"] = "是乎？吾掌遊戲設計。盡錄㬺獸記機甚難，毋輟！錄成後來告我。", -- CeladonMansion3F
    ["_CeladonMansion3FGameDesignerCompletedDexText"] = "善哉！子已盡錄㬺獸記機！賀之！……", -- CeladonMansion3F
    ["_CeladonMansion3FGameProgramPCText"] = "此遊戲程式也！妄動之，遊戲或錯亂。", -- CeladonMansion3F
    ["_CeladonMansion3FPlayingGamePCText"] = "有人不事職而戲矣！", -- CeladonMansion3F
    ["_CeladonMansion3FGameScriptPCText"] = "此劇本也！終局不可先窺！", -- CeladonMansion3F
    ["_CeladonMansion3FDevRoomSignText"] = "株式會社遊戲狂想家\n開發室", -- CeladonMansion3F
    ["_CeladonMansionRoofHouseSignText"] = "吾無不知！", -- CeladonMansionRoof
    ["_CeladonPokecenterGentlemanText"] = "㬺獸籥之聲惟㬺獸能聞，聞之則醒。", -- CeladonPokecenter
    ["_CeladonPokecenterBeautyText"] = "吾自縓邑沿自轉車道逆坡而上！", -- CeladonPokecenter
    ["_CeladonGymErikaPreBattleText"] = "麥恵梨香：幸會。今日和煦，可愛甚矣……呀，失禮，吾方小寐。吾名麥恵梨香，青邑書院山長也。吾習插花之藝，所攜皆草屬㬺獸。哦，未知子欲挑戰。既如此，請。然吾不欲敗。", -- CeladonGym
    ["_CeladonGymErikaReceivedRainbowBadgeText"] = "嗚呼，吾服矣。子強甚。當授子虹徽。", -- CeladonGym
    ["_CeladonGymErikaPostBattleAdviceText"] = "子在編錄㬺獸乎？誠可嘉。若獸貌不美，吾決不蓄之。", -- CeladonGym
    ["_CeladonGymRainbowBadgeInfoText"] = "虹徽使五十級以下之獸聽命，亦使獸於戰外能用怪力。並受此物。", -- CeladonGym
    ["_CeladonGymReceivedTM21Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CeladonGym
    ["_TM21ExplanationText"] = "技機廾一載嵩吸。所傷敵之半，反歸以療己獸。", -- CeladonGym
    ["_CeladonGymTM21NoRoomText"] = "須先空行囊一隙。", -- CeladonGym
    ["_CeladonGymBattleText2"] = "咄！此處非子可入！", -- CeladonGym
    ["_CeladonGymEndBattleText2"] = "子太粗猛矣！", -- CeladonGym
    ["_CeladonGymAfterBattleText2"] = "呸！願麥恵梨香盡敗子！", -- CeladonGym
    ["_CeladonGymBattleText3"] = "吾方覺無聊。", -- CeladonGym
    ["_CeladonGymEndBattleText3"] = "吾之妝！", -- CeladonGym
    ["_CeladonGymAfterBattleText3"] = "草屬獸勝水屬；對石、土二屬亦有利。", -- CeladonGym
    ["_CeladonGymBattleText4"] = "子莫非來窺者乎？", -- CeladonGym
    ["_CeladonGymEndBattleText4"] = "驚煞我矣！", -- CeladonGym
    ["_CeladonGymAfterBattleText4"] = "哦，原非來窺。此處來窺者多矣！", -- CeladonGym
    ["_CeladonGymBattleText5"] = "觀吾草屬獸！最易養也！", -- CeladonGym
    ["_CeladonGymEndBattleText5"] = "不！", -- CeladonGym
    ["_CeladonGymAfterBattleText5"] = "吾院惟用草屬㬺獸；插花亦取其助！", -- CeladonGym
    ["_CeladonGymBattleText6"] = "毋攜蟲屬、火屬之獸入此！", -- CeladonGym
    ["_CeladonGymEndBattleText6"] = "哦！子！", -- CeladonGym
    ["_CeladonGymAfterBattleText6"] = "吾山長麥恵梨香雖恬靜，技藝甚精！", -- CeladonGym
    ["_CeladonGymBattleText7"] = "幸會。吾好養㬺獸。", -- CeladonGym
    ["_CeladonGymEndBattleText7"] = "嗚呼，妙哉！", -- CeladonGym
    ["_CeladonGymAfterBattleText7"] = "吾將與素未識者赴約，故須習禮。", -- CeladonGym
    ["_CeladonGymBattleText8"] = "請入青邑書院！毋小女子之力！", -- CeladonGym
    ["_CeladonGymEndBattleText8"] = "嗚呼，敗矣！", -- CeladonGym
    ["_CeladonGymAfterBattleText8"] = "今日未攜吾最強之獸！後日再戰！", -- CeladonGym
    ["_GameCornerBeauty1Text"] = "請入！隔壁可用籌易諸珍賞。", -- GameCorner
    ["_GameCornerClerk1DoYouNeedSomeGameCoinsText"] = "請入火箭博場！欲買籌乎？五十籌價一千円。欲之乎？", -- GameCorner
    ["_GameCornerClerk1ThanksHereAre50CoinsText"] = "多謝！五十籌在此。", -- GameCorner
    ["_GameCornerClerk1PleaseComePlaySometimeText"] = "不欲乎？他日來戲！", -- GameCorner
    ["_GameCornerClerk1CantAffordTheCoinsText"] = "子資不足，無以買籌！", -- GameCorner
    ["_GameCornerClerk1CoinCaseIsFullText"] = "噫！子籌匣已滿。", -- GameCorner
    ["_GameCornerClerk1DontHaveCoinCaseText"] = "子無籌匣！", -- GameCorner
    ["_GameCornerMiddleAgedMan1Text"] = "此事莫外傳。傳聞此場乃火箭賊所營。", -- GameCorner
    ["_GameCornerBeauty2Text"] = "吾意諸博機中彩之率各異。", -- GameCorner
    ["_GameCornerFishingGuruWantToPlayText"] = "童子，欲博乎？", -- GameCorner
    ["_GameCornerFishingGuruReceived10CoinsText"] = "{PLAYER}得十籌！", -- GameCorner
    ["_GameCornerFishingGuruDontNeedMyCoinsText"] = "子已不需吾籌矣！", -- GameCorner
    ["_GameCornerFishingGuruWinsComeAndGoText"] = "勝負無常。", -- GameCorner
    ["_GameCornerMiddleAgedWomanText"] = "吾戲甚樂！", -- GameCorner
    ["_GameCornerGymGuideChampInMakingText"] = "咄，將為魁者！尚有正事可為。青邑書院山長麥恵梨香用草屬獸；貌雖柔靜，毋輕之！", -- GameCorner
    ["_GameCornerGymGuideTheyOfferRarePokemonText"] = "隔壁以籌易珍獸。然吾總不能勝！", -- GameCorner
    ["_GameCornerGamblerText"] = "博戲可畏，最易使人耽溺！", -- GameCorner
    ["_GameCornerClerk2WantSomeCoinsText"] = "何事？欲些籌乎？", -- GameCorner
    ["_GameCornerClerk2Received20CoinsText"] = "{PLAYER}得廾籌！", -- GameCorner
    ["_GameCornerClerk2YouHaveLotsOfCoinsText"] = "子已有多籌矣！", -- GameCorner
    ["_GameCornerClerk2INeedMoreCoinsText"] = "可惱！欲換之獸尚須更多籌！", -- GameCorner
    ["_GameCornerGentlemanThrowingMeOffText"] = "咄，何事？子使吾分心！與子些籌，去去！", -- GameCorner
    ["_GameCornerGentlemanReceived20CoinsText"] = "{PLAYER}得廾籌！", -- GameCorner
    ["_GameCornerGentlemanYouGotYourOwnCoinsText"] = "子自有籌矣！", -- GameCorner
    ["_GameCornerGentlemanCloselyWatchTheReelsText"] = "訣在細觀轉輪！", -- GameCorner
    ["_GameCornerRocketImGuardingThisPosterText"] = "吾守此壁圖！速去，否則有苦頭！", -- GameCorner
    ["_GameCornerRocketBattleEndText"] = "可惱！", -- GameCorner
    ["_GameCornerRocketAfterBattleText"] = "本部恐將暴露！吾當告首領！", -- GameCorner
    ["_GameCornerPosterSwitchBehindPosterText"] = "咄！壁圖後竟有隱按機！按之！", -- GameCorner
    ["_GameCornerOopsForgotCoinCaseText"] = "噫！忘攜籌匣！", -- GameCorner
    ["_CeladonMart5FGentlemanText"] = "增獸諸能之丸，惟此處有售。鈣丸增異能，消炎痛丸增速。", -- CeladonMart5F
    ["_CeladonMart5FSailorText"] = "吾為增能之丸而來。牛磺酸丸增力，鐵丸增守！", -- CeladonMart5F
    ["_CeladonMart5FCurrentFloorSignText"] = "五層：藥肆", -- CeladonMart5F
    ["_GameCornerPrizeRoomBaldingGuyText"] = "吾甚愛三樊獸！奈博機難勝。", -- GameCornerPrizeRoom
    ["_GameCornerPrizeRoomGamblerText"] = "今日大獲矣！", -- GameCornerPrizeRoom
    ["_CeladonDinerCookText"] = "安！吾等方歇息。", -- CeladonDiner
    ["_CeladonDinerMiddleAgedWomanText"] = "吾獸甚弱，故常往五層藥肆。", -- CeladonDiner
    ["_CeladonDinerMiddleAgedManText"] = "噓！火箭博場下有地下室。", -- CeladonDiner
    ["_CeladonDinerFisherText"] = "嚼嚼……彼席之人於博機輸盡矣。", -- CeladonDiner
    ["_CeladonDinerGymGuideImFlatOutBustedText"] = "笑便笑！吾已一文不名！今後不博，從此改過。此物與子，吾不復用。", -- CeladonDiner
    ["_CeladonDinerGymGuideReceivedCoinCaseText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CeladonDiner
    ["_CeladonDinerGymGuideCoinCaseNoRoomText"] = "須空一隙納此！", -- CeladonDiner
    ["_CeladonDinerGymGuideWinItBackText"] = "吾常以為終能贏回所失……", -- CeladonDiner
    ["_CeladonChiefHouseChiefText"] = "嘿嘿！博機聚財，真如山積！", -- CeladonChiefHouse
    ["_CeladonChiefHouseRocketText"] = "主事！已運二千㬺獸充博場之賞！", -- CeladonChiefHouse
    ["_CeladonChiefHouseSailorText"] = "毋觸火箭博場之壁圖！其後絕無隱按機！", -- CeladonChiefHouse
    ["_CeladonHotelGrannyText"] = "㬺獸乎？非也，此乃人之客店。今已客滿。", -- CeladonHotel
    ["_CeladonHotelBeautyText"] = "吾與兄及男友來遊。青邑真美！", -- CeladonHotel
    ["_CeladonHotelSuperNerdText"] = "她何故攜兄同來？", -- CeladonHotel
    ["_MtMoonPokecenterYoungsterText"] = "吾腰懸獸毬六枚。至多亦只可攜獸六隻。", -- MtMoonPokecenter
    ["_MtMoonPokecenterGentlemanText"] = "火箭賊襲縹邑居民……報章常載其事！", -- MtMoonPokecenter
    ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "客官！有一佳貨專與子。龍門鯉一尾，只五百円！如何？", -- MtMoonPokecenter
    ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "不欲乎？吾可是特為子著想！", -- MtMoonPokecenter
    ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "子錢尚不足！", -- MtMoonPokecenter
    ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "既售，概不退錢！", -- MtMoonPokecenter
    ["_RockTunnelPokecenterGentlemanText"] = "㬺獸諸屬相剋，有所勝，亦有所不勝。", -- RockTunnelPokecenter
    ["_RockTunnelPokecenterFisherText"] = "吾以無用金珠售得五千円！", -- RockTunnelPokecenter
    ["_Route11Gate1FGuardText"] = "獲獸既多，別名難思乎？紫村有名師，可評獸名，亦可為之改名。", -- Route11Gate1F
    ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "地上有物，肉眼不可見。覓物機可察近處之物，然不能指其確處，仍須自尋。", -- Route11Gate2F
    ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "以望遠鏡觀之：有大獸臥於路上酣眠！", -- Route11Gate2F
    ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "以望遠鏡觀之：景甚美！", -- Route11Gate2F
    ["_Route11Gate2FRightBinocularsText"] = "以望遠鏡觀之：自縹邑至紫村，惟岩山隧一路可通。", -- Route11Gate2F
    ["_Route12Gate1FGuardText"] = "樓上有望臺。", -- Route12Gate1F
    ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "吾獸之骨灰藏於㬺獸塔。此技機與子，吾已無用……", -- Route12Gate2F
    ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER}得技機卅九！", -- Route12Gate2F
    ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "技機卅九載倏忽星。上窮碧落，下黃泉，無所不中；決戰可恃。", -- Route12Gate2F
    ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "行囊無隙可納。", -- Route12Gate2F
    ["_Route12Gate2FLeftBinocularsText"] = "以望遠鏡觀之：一人正垂釣！", -- Route12Gate2F
    ["_Route12Gate2FRightBinocularsText"] = "以望遠鏡觀之：彼乃㬺獸塔！", -- Route12Gate2F
    ["_Route15Gate1FGuardText"] = "子在編㬺獸記機乎？大木博士之助手方纔來過。", -- Route15Gate1F
    ["_Route15Gate2FOaksAideExpAllText"] = "閱歷機使所攜諸獸皆得閱歷，雖未參戰亦然；但每獸所得因而較少。若不用，可䝻於算器。", -- Route15Gate2F
    ["_Route15Gate2FBinocularsText"] = "以望遠鏡觀之：似有一小州。", -- Route15Gate2F
    ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "自轉車道禁步行者入！", -- Route16Gate1F
    ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "自轉車道傍海而下坡，騎之甚快！", -- Route16Gate1F
    ["_Route16Gate1FGuardWaitUpText"] = "且住！請稍候！", -- Route16Gate1F
    ["_Route16Gate1FGamblerText"] = "子何由入此？頗有本事！", -- Route16Gate1F
    ["_Route16Gate2FLittleBoyText"] = "吾將與女友同騎！", -- Route16Gate2F
    ["_Route16Gate2FLittleGirlText"] = "吾等將同騎而行！", -- Route16Gate2F
    ["_Route16Gate2FLeftBinocularsText"] = "以望遠鏡觀之：青邑百貨肆也！", -- Route16Gate2F
    ["_Route16Gate2FRightBinocularsText"] = "以望遠鏡觀之：水上有一長道！", -- Route16Gate2F
    ["_Route18Gate1FGuardYouNeedABicycleText"] = "欲入自轉車道，須有自轉車！", -- Route18Gate1F
    ["_Route18Gate1FGuardCyclingRoadUphillText"] = "自此入自轉車道，皆為上坡。", -- Route18Gate1F
    ["_Route18Gate1FGuardExcuseMeText"] = "且住！", -- Route18Gate1F
    ["_Route18Gate2FLeftBinocularsText"] = "以望遠鏡觀之：素村在西！", -- Route18Gate2F
    ["_Route18Gate2FRightBinocularsText"] = "以望遠鏡觀之：有人游水！", -- Route18Gate2F
    ["_MtMoon1FHikerBattleText"] = "嚇我一跳！哦，乃童子耳！", -- MtMoon1F
    ["_MtMoon1FHikerEndBattleText"] = "嗚！又驚一回！", -- MtMoon1F
    ["_MtMoon1FHikerAfterBattleText"] = "童子如子，不當來此！", -- MtMoon1F
    ["_MtMoon1FYoungster1BattleText"] = "子亦來探此穴乎？", -- MtMoon1F
    ["_MtMoon1FYoungster1EndBattleText"] = "敗之可惱！", -- MtMoon1F
    ["_MtMoon1FYoungster1AfterBattleText"] = "吾下至此，只為向女子逞能。", -- MtMoon1F
    ["_MtMoon1FCooltrainerF1BattleText"] = "哇！此中遠大於吾所想！", -- MtMoon1F
    ["_MtMoon1FCooltrainerF1EndBattleText"] = "嗚！竟敗矣！", -- MtMoon1F
    ["_MtMoon1FCooltrainerF1AfterBattleText"] = "此穴出口何在？", -- MtMoon1F
    ["_MtMoon1FSuperNerdBattleText"] = "咄！毋悄然近我！", -- MtMoon1F
    ["_MtMoon1FSuperNerdEndBattleText"] = "吾獸不中用矣！", -- MtMoon1F
    ["_MtMoon1FSuperNerdAfterBattleText"] = "須尋更強之獸。", -- MtMoon1F
    ["_MtMoon1FCooltrainerF2BattleText"] = "何？吾正候友人來尋我。", -- MtMoon1F
    ["_MtMoon1FCooltrainerF2EndBattleText"] = "吾敗乎？", -- MtMoon1F
    ["_MtMoon1FCooltrainerF2AfterBattleText"] = "聞此有甚珍稀之僵石。", -- MtMoon1F
    ["_MtMoon1FYoungster2BattleText"] = "穴中有可疑之人。子又如何？", -- MtMoon1F
    ["_MtMoon1FYoungster2EndBattleText"] = "為子所敗！", -- MtMoon1F
    ["_MtMoon1FYoungster2AfterBattleText"] = "吾見彼等矣！必是火箭賊！", -- MtMoon1F
    ["_MtMoon1FYoungster3BattleText"] = "穿此穴便可至縹邑！", -- MtMoon1F
    ["_MtMoon1FYoungster3EndBattleText"] = "吾敗矣。", -- MtMoon1F
    ["_MtMoon1FYoungster3AfterBattleText"] = "歃蝙蝠頗強！獲之一隻，亦甚有用。", -- MtMoon1F
    ["_MtMoon1FBewareZubatSign"] = "慎之！歃蝙蝠吸血！", -- MtMoon1F
    ["_MtMoonB2FDomeFossilYouWantText"] = "子欲兜僵石乎？", -- MtMoonB2F
    ["_MtMoonB2FHelixFossilYouWantText"] = "子欲貝僵石乎？", -- MtMoonB2F
    ["_MtMoonB2FReceivedFossilText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- MtMoonB2F
    ["_MtMoonB2FYouHaveNoRoomText"] = "看，子已無隙可納此。", -- MtMoonB2F
    ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "咄，止！此二僵石皆吾所發見，皆當歸我！", -- MtMoonB2F
    ["_MtMoonB2FSuperNerdOkIllShareText"] = "善！分子一枚！", -- MtMoonB2F
    ["_MtMoonB2fSuperNerdEachTakeOneText"] = "吾與子各取一枚，毋貪！", -- MtMoonB2F
    ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "遠在丹州有丹驗室，專究使僵石復生之法。", -- MtMoonB2F
    ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "善。則此枚歸我！", -- MtMoonB2F
    ["_MtMoonB2FRocket1BattleText"] = "火箭賊將尋僵石，使之復生，再售取錢！", -- MtMoonB2F
    ["_MtMoonB2FRocket1EndBattleText"] = "嗚！怒我甚矣！", -- MtMoonB2F
    ["_MtMoonB2FRocket1AfterBattleText"] = "子使我怒矣！火箭賊必記子之名於黑籍！", -- MtMoonB2F
    ["_MtMoonB2FRocket2BattleText"] = "吾等火箭賊，乃役㬺獸作惡之徒！", -- MtMoonB2F
    ["_MtMoonB2FRocket2EndBattleText"] = "壞事矣！", -- MtMoonB2F
    ["_MtMoonB2FRocket2AfterBattleText"] = "可惱！吾同黨不會置此不問！", -- MtMoonB2F
    ["_MtMoonB2FRocket3BattleText"] = "吾等正辦大事！小兒，速去！", -- MtMoonB2F
    ["_MtMoonB2FRocket3EndBattleText"] = "如此看來，子頗有能。", -- MtMoonB2F
    ["_MtMoonB2FRocket3AfterBattleText"] = "若得僵石，交我便走！", -- MtMoonB2F
    ["_MtMoonB2FRocket4BattleText"] = "小兒休擾大人！", -- MtMoonB2F
    ["_MtMoonB2FRocket4EndBattleText"] = "怒甚矣！", -- MtMoonB2F
    ["_MtMoonB2FRocket4AfterBattleText"] = "人未至此以前，㬺獸早已居之。", -- MtMoonB2F
    ["_SafariZoneWestRestHouseSignText"] = "憩舍", -- SafariZoneWest
    ["_SafariZoneWestFindWardensTeethSignText"] = "求物告示 守人失金齒，疑在此近處。拾得者有賞。請告獲獸帶守人。", -- SafariZoneWest
    ["_SafariZoneWestTrainerTipsText"] = "㬺獸士須知\n獲獸帶探險會：尋祕屋！", -- SafariZoneWest
    ["_SafariZoneWestSignText"] = "第三區\n東：中區", -- SafariZoneWest
    ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "啊！終於有人來！子乃首至祕屋者。吾方憂無人得此會之賞。賀子，子勝矣！", -- SafariZoneSecretHouse
    ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- SafariZoneSecretHouse
    ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "祕傳機三載乘浪。獸習之，可載子渡水；祕傳機又可屢用不廢。得此賞，子幸甚！", -- SafariZoneSecretHouse
    ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "此佳賞無隙可納！", -- SafariZoneSecretHouse
    ["_SaffronCityRocket1Text"] = "欲何為？速去！", -- SaffronCity
    ["_SaffronCityRocket2Text"] = "首領已言，必取此邑！", -- SaffronCity
    ["_SaffronCityRocket3Text"] = "讓路！", -- SaffronCity
    ["_SaffronCityRocket4Text"] = "黃邑今屬火箭賊！", -- SaffronCity
    ["_SaffronCityRocket5Text"] = "作惡使我神氣益旺！", -- SaffronCity
    ["_SaffronCityRocket6Text"] = "痛！行路看前！", -- SaffronCity
    ["_SaffronCityRocket7Text"] = "若制氣仙公司，天下㬺獸皆可供吾等取利！", -- SaffronCity
    ["_SaffronCityScientistText"] = "子獨力逐火箭賊乎？奇甚！", -- SaffronCity
    ["_SaffronCitySilphWorkerMText"] = "善！火箭賊已去，今可安心出門！", -- SaffronCity
    ["_SaffronCitySilphWorkerFText"] = "今人當復紛至黃邑矣。", -- SaffronCity
    ["_SaffronCityGentlemanText"] = "吾讀氣仙公司之報，乃乘泰飍雀飛來。事已畢乎？竟錯過報界之熱鬧。", -- SaffronCity
    ["_SaffronCityPidgeotText"] = "泰飍雀：嗶，嗶嗶！", -- SaffronCity
    ["_SaffronCityRockerText"] = "吾見火箭賊首領自氣仙公司遁出。", -- SaffronCity
    ["_SaffronCityRocket8Text"] = "吾乃守衛。可疑童子，皆不得入！", -- SaffronCity
    ["_SaffronCityRocket9Text"] = "……呼嚕……哈！此人睡著矣！", -- SaffronCity
    ["_SaffronCitySignText"] = "黃邑\n黃金，光輝之色也。", -- SaffronCity
    ["_SaffronCityFightingDojoSignText"] = "鬥道場", -- SaffronCity
    ["_SaffronCityGymSignText"] = "黃邑㬺獸書院\n山長：棗夢 念獸宗師！", -- SaffronCity
    ["_SaffronCityTrainerTips1Text"] = "㬺獸士須知\n萬病丸可除睡、灼等諸患。價稍高，而最便。", -- SaffronCity
    ["_SaffronCityTrainerTips2Text"] = "㬺獸士須知\n新良毬獲獸更易。難獲之獸，可試用之。", -- SaffronCity
    ["_SaffronCitySilphCoSignText"] = "氣仙公司\n辦公大樓", -- SaffronCity
    ["_SaffronCityMrPsychicsHouseSignText"] = "卜辭爺之宅", -- SaffronCity
    ["_SaffronCitySilphCoLatestProductSignText"] = "氣仙公司最新製品！發售之期未定……", -- SaffronCity
    ["_Route20Swimmer1BattleText"] = "此處水淺。", -- Route20
    ["_Route20Swimmer1EndBattleText"] = "潑！", -- Route20
    ["_Route20Swimmer1AfterBattleText"] = "真欲乘吾獸而行。", -- Route20
    ["_Route20Swimmer2BattleText"] = "孿島幽靜，最宜避喧！", -- Route20
    ["_Route20Swimmer2EndBattleText"] = "休矣！", -- Route20
    ["_Route20Swimmer2AfterBattleText"] = "此島下有巨穴。", -- Route20
    ["_Route20Swimmer3BattleText"] = "吾愛與魚共浮！", -- Route20
    ["_Route20Swimmer3EndBattleText"] = "痛哉！", -- Route20
    ["_Route20Swimmer3AfterBattleText"] = "欲與我共浮乎？", -- Route20
    ["_Route20Swimmer4BattleText"] = "子亦來遊乎？", -- Route20
    ["_Route20Swimmer4EndBattleText"] = "毫不留情！", -- Route20
    ["_Route20Swimmer4AfterBattleText"] = "孿島昔本一島！", -- Route20
    ["_Route20Swimmer5BattleText"] = "且觀吾壯體！", -- Route20
    ["_Route20Swimmer5EndBattleText"] = "弱矣！", -- Route20
    ["_Route20Swimmer5AfterBattleText"] = "早知當強吾獸，不當只強己身！", -- Route20
    ["_Route20Swimmer6BattleText"] = "子何故乘獸？不能游乎？", -- Route20
    ["_Route20Swimmer6EndBattleText"] = "痛！如中魚雷！", -- Route20
    ["_Route20Swimmer6AfterBattleText"] = "乘獸而行，似甚樂！", -- Route20
    ["_Route20CooltrainerMBattleText"] = "吾乘飛屬之獸來此！", -- Route20
    ["_Route20CooltrainerMEndBattleText"] = "嗚呼！", -- Route20
    ["_Route20CooltrainerMAfterBattleText"] = "吾鳥獸不能載我飛返！", -- Route20
    ["_Route20Swimmer7BattleText"] = "吾男友贈我大珠！", -- Route20
    ["_Route20Swimmer7EndBattleText"] = "毋觸吾珠！", -- Route20
    ["_Route20Swimmer7AfterBattleText"] = "若置珠於刺甲貝中，可更大乎？", -- Route20
    ["_Route20Swimmer8BattleText"] = "吾自丹州游至此！", -- Route20
    ["_Route20Swimmer8EndBattleText"] = "失望甚矣！", -- Route20
    ["_Route20Swimmer8AfterBattleText"] = "丹州棄置之㬺獸府，今已為群獸所據。", -- Route20
    ["_Route20Swimmer9BattleText"] = "西方丹州有丹驗室，專究㬺獸。", -- Route20
    ["_Route20Swimmer9EndBattleText"] = "且住！", -- Route20
    ["_Route20Swimmer9AfterBattleText"] = "丹州乃火山之州！", -- Route20
    ["_Route20SeafoamIslandsSignText"] = "孿島", -- Route20
    ["_Route22RivalBeforeBattleText1"] = "{RIVAL}：咄，{PLAYER}！子欲往㬺獸聯會乎？罷罷！子徽章恐尚未足，守者不縱子過。且䀩子獸有無長進！", -- Route22
    ["_Route22RivalAfterBattleText1"] = "聞㬺獸聯會多勁敵，吾須思所以越之。子休滯此，速進！", -- Route22
    ["_Route22Rival1DefeatedText"] = "咄！子徒幸耳！", -- Route22
    ["_Route22Rival1VictoryText"] = "{RIVAL}：何？問吾何以有二獸？子亦當多獲些！", -- Route22
    ["_Route22RivalBeforeBattleText2"] = "{RIVAL}：咄，{PLAYER}！竟於此見子！子亦往㬺獸聯會？徽章亦盡得乎？有意思。吾先以子溫戰，{PLAYER}，再往聯會。來，與我展！", -- Route22
    ["_Route22RivalAfterBattleText2"] = "此戰使吾筋骨已舒，正可往聯會！{PLAYER}，子尚欠鍛鍊；自己也知。吾伆矣！", -- Route22
    ["_Route22Rival2DefeatedText"] = "何！吾但一時疏忽！", -- Route22
    ["_Route22Rival2VictoryText"] = "{RIVAL}：哈哈！{PLAYER}，此便子之極乎？去吾遠甚！更去鍛鍊，小敗將！", -- Route22
    ["_Route22PokemonLeagueSignText"] = "㬺獸聯會\n正門", -- Route22
    ["_Route23YouDontHaveTheBadgeYetText"] = "惟有{RAM:wNameBuffer}者得過此關！子尚無{RAM:wNameBuffer}。欲至㬺獸聯會，此徽不可少！", -- Route23
    ["_Route23OhThatIsTheBadgeText"] = "惟有{RAM:wNameBuffer}者得過此關！哦，此乃{RAM:wNameBuffer}！", -- Route23
    ["_Route23GoRightAheadText"] = "既如此，請過！", -- Route23
    ["_Route23VictoryRoadGateSignText"] = "魁路關\n至㬺獸聯會", -- Route23
    ["_Route24CooltrainerM1YouBeatOurContestText"] = "賀子！橋上五名試士，皆為子所勝！", -- Route24
    ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "今得一珍賞！", -- Route24
    ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- Route24
    ["_Route24CooltrainerM1NoRoomText"] = "行囊無隙可納！", -- Route24
    ["_Route24CooltrainerM1JoinTeamRocketText"] = "且問子：願入火箭賊乎？吾等役㬺獸以作惡，專為此業。願入乎？果不願？來，入吾等！吾命子入！然則須以力服子。吾有一議，子必不能辭！", -- Route24
    ["_Route24CooltrainerM1DefeatedText"] = "嗚！子頗有能！", -- Route24
    ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "以子之能，可為火箭賊渠帥！", -- Route24
    ["_Route24CooltrainerM2BattleText"] = "吾自草中見子連勝之事！", -- Route24
    ["_Route24CooltrainerM2EndBattleText"] = "果不出吾所料！", -- Route24
    ["_Route24CooltrainerM2AfterBattleText"] = "吾懼橋上諸人，故匿於草中。", -- Route24
    ["_Route24CooltrainerM3BattleText"] = "善！吾第五，必蹋倒子！", -- Route24
    ["_Route24CooltrainerM3EndBattleText"] = "嗚！太過矣！", -- Route24
    ["_Route24CooltrainerM3AfterBattleText"] = "吾已盡力，故無悔！", -- Route24
    ["_Route24CooltrainerF1BattleText"] = "吾第四！子已疲乎？", -- Route24
    ["_Route24CooltrainerF1EndBattleText"] = "吾亦敗矣！", -- Route24
    ["_Route24CooltrainerF1AfterBattleText"] = "吾已盡力，故無悔！", -- Route24
    ["_Route24Youngster1BattleText"] = "第三來矣！吾可不易勝！", -- Route24
    ["_Route24Youngster1EndBattleText"] = "痛！為子蹋平矣！", -- Route24
    ["_Route24Youngster1AfterBattleText"] = "吾已盡力，故無悔！", -- Route24
    ["_Route24CooltrainerF2BattleText"] = "吾第二！今當認真矣！", -- Route24
    ["_Route24CooltrainerF2EndBattleText"] = "何以竟敗？", -- Route24
    ["_Route24CooltrainerF2AfterBattleText"] = "吾已盡力，故無悔！", -- Route24
    ["_Route24Youngster2BattleText"] = "此乃金珠橋！勝吾等五士，即得珍賞！子有此能乎？", -- Route24
    ["_Route24Youngster2EndBattleText"] = "呼！果然有本事！", -- Route24
    ["_Route24Youngster2AfterBattleText"] = "吾已盡力，故無悔！", -- Route24
    ["_Route25Youngster1BattleText"] = "近處㬺獸士常來此習戰！", -- Route25
    ["_Route25Youngster1EndBattleText"] = "子尚可。", -- Route25
    ["_Route25Youngster1AfterBattleText"] = "㬺獸皆有所弱，宜兼養諸屬。", -- Route25
    ["_Route25Youngster2BattleText"] = "父曾攜我赴朱邑聖亞納號之盛會！", -- Route25
    ["_Route25Youngster2EndBattleText"] = "吾未怒！", -- Route25
    ["_Route25Youngster2AfterBattleText"] = "聖亞納號上，吾見天下各地㬺獸士。", -- Route25
    ["_Route25CooltrainerMBattleText"] = "吾乃俊士，又有女友！", -- Route25
    ["_Route25CooltrainerMEndBattleText"] = "唉，可惱……", -- Route25
    ["_Route25CooltrainerMAfterBattleText"] = "罷了，吾女友自會慰我。", -- Route25
    ["_Route25CooltrainerF1BattleText"] = "幸會！吾男友甚俊！", -- Route25
    ["_Route25CooltrainerF1EndBattleText"] = "吾今日氣力不佳！", -- Route25
    ["_Route25CooltrainerF1AfterBattleText"] = "但願吾男友也如子善戰！", -- Route25
    ["_Route25Youngster3BattleText"] = "吾早知必與子戰！", -- Route25
    ["_Route25Youngster3EndBattleText"] = "吾亦早知必敗！", -- Route25
    ["_Route25Youngster3AfterBattleText"] = "若獸亂心或睡，可易他獸出戰！", -- Route25
    ["_Route25CooltrainerF2BattleText"] = "吾友有一可愛之獸，妒之甚矣！", -- Route25
    ["_Route25CooltrainerF2EndBattleText"] = "今倒不甚妒矣！", -- Route25
    ["_Route25CooltrainerF2AfterBattleText"] = "子自月山來乎？可贈我一明魄乎？", -- Route25
    ["_Route25Hiker1BattleText"] = "吾方自月山下來，然尚可戰！", -- Route25
    ["_Route25Hiker1EndBattleText"] = "子頗費力矣！", -- Route25
    ["_Route25Hiker1AfterBattleText"] = "可惱！方在穴中，有歃蝙蝠咬我。", -- Route25
    ["_Route25Hiker2BattleText"] = "吾將往岬上訪一藏獸者！", -- Route25
    ["_Route25Hiker2EndBattleText"] = "為子所敗。", -- Route25
    ["_Route25Hiker2AfterBattleText"] = "彼藏獸者蓄珍稀諸種甚多。", -- Route25
    ["_Route25Hiker3BattleText"] = "子欲往見正輝乎？先與我一戰！", -- Route25
    ["_Route25Hiker3EndBattleText"] = "子頗不凡。", -- Route25
    ["_Route25Hiker3AfterBattleText"] = "下方小徑乃往縹邑之捷路。", -- Route25
    ["_Route25BillSignText"] = "海廬\n正輝居此", -- Route25
    ["_VictoryRoad2FHikerBattleText"] = "魁路乃㬺獸士最後之試！", -- VictoryRoad2F
    ["_VictoryRoad2FHikerAfterBattleText"] = "若受困，可試移諸巨石。", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd1BattleText"] = "哦，子欲挑戰四天王乎？", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd1EndBattleText"] = "為子所敗！", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "{RIVAL}亦曾過此！", -- VictoryRoad2F
    ["_VictoryRoad2FCooltrainerMBattleText"] = "來！吾必勝子！", -- VictoryRoad2F
    ["_VictoryRoad2FCooltrainerMEndBattleText"] = "反為子所勝！", -- VictoryRoad2F
    ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "子有資格行魁路矣！", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd2BattleText"] = "若能過此，便可見四天王！", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd2EndBattleText"] = "不！豈有此理！", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "論㬺獸之學，吾仍可勝子！", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd3BattleText"] = "魁路太難乎？", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd3EndBattleText"] = "善哉！", -- VictoryRoad2F
    ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "多有㬺獸士至此而棄挑戰。", -- VictoryRoad2F
    ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "哦！子非火箭賊！是來救我等乎？多謝！子既救我，願以此獸贈子。", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "此乃海贔屭，性極慧。吾等本養於驗室，今隨子更善。吾意子必能善養之。其善游，可載人渡水。", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "火箭賊首領往會議室矣！吾總辦可安乎？", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM1SavedText"] = "終得救矣！多謝！", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "火箭賊所圖，乃聖毬也；此毬可獲任一㬺獸！", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "因火箭賊之故，吾等已停聖毬之製。", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "若氣仙公司或吾等㬺獸落入火箭賊手，禍可大矣！", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "子竟獨力逐火箭賊乎？奇哉！", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "子！此地危甚。來救我乎？不可，太險！", -- SilphCo7F
    ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "終於安全！多謝子！", -- SilphCo7F
    ["_SilphCo7FRocket1BattleText"] = "呵呵，聞有小鼠入此！", -- SilphCo7F
    ["_SilphCo7FRocket1EndBattleText"] = "燈滅矣！", -- SilphCo7F
    ["_SilphCo7FRocket1AfterBattleText"] = "徒在此竄走，休想尋得吾首領！", -- SilphCo7F
    ["_SilphCo7FScientistBattleText"] = "嘿嘿！子誤認吾為氣仙公司之人乎？", -- SilphCo7F
    ["_SilphCo7FScientistEndBattleText"] = "吾完矣！", -- SilphCo7F
    ["_SilphCo7FScientistAfterBattleText"] = "子雖年少，竟是善戰之士！", -- SilphCo7F
    ["_SilphCo7FRocket2BattleText"] = "吾火箭四弟之一！", -- SilphCo7F
    ["_SilphCo7FRocket2EndBattleText"] = "嗚呼！諸兄弟，吾敗矣！", -- SilphCo7F
    ["_SilphCo7FRocket2AfterBattleText"] = "無妨！吾兄弟自會為我報之！", -- SilphCo7F
    ["_SilphCo7FRocket3BattleText"] = "童子闖入者乎？必是子！", -- SilphCo7F
    ["_SilphCo7FRocket3EndBattleText"] = "罷！吾敗矣！", -- SilphCo7F
    ["_SilphCo7FRocket3AfterBattleText"] = "趁首領未怒，速歸家去！", -- SilphCo7F
    ["_SilphCo7FRivalText"] = "{RIVAL}：{PLAYER}！何故遲至？", -- SilphCo7F
    ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}：哈哈！吾料子必來，故候於此。火箭賊使子遲矣？吾又不在意。先前於黃邑見子，故欲䀩子是否長進！", -- SilphCo7F
    ["_SilphCo7FRivalDefeatedText"] = "哦！如此看來，子可去對火箭賊首領矣！", -- SilphCo7F
    ["_SilphCo7FRivalVictoryText"] = "{RIVAL}：何以言之？子尚不足與吾等強者戲！", -- SilphCo7F
    ["_SilphCo7FRivalGoodLuckToYouText"] = "{PLAYER}！吾將愈進愈上。䀩㬺獸記機，漸知何獸為強、何法易形。吾將往㬺獸聯會逐四天王，遂為天下最強之㬺獸士！{PLAYER}，子亦自勉。毋憂吾，吾伆矣！", -- SilphCo7F
    ["_PokemonMansion2FSuperNerdBattleText"] = "吾出不得！此舊府處處如謎。", -- PokemonMansion2F
    ["_PokemonMansion2FSuperNerdEndBattleText"] = "嗚呼！吾所拾之物！", -- PokemonMansion2F
    ["_PokemonMansion2FSuperNerdAfterBattleText"] = "諸按機交互啟閉不同之門。", -- PokemonMansion2F
    ["_PokemonMansion2FDiary1Text"] = "日記：七月五日 南美洲圭亞那。於叢林深處新得一種㬺獸。", -- PokemonMansion2F
    ["_PokemonMansion2FDiary2Text"] = "日記：七月十日。新得之㬺獸，命名混沌蟨。", -- PokemonMansion2F
    ["_PokemonMansion2FSwitchText"] = "有隱按機！按之乎？", -- PokemonMansion2F
    ["_PokemonMansion2FSwitchPressedText"] = "孰不按之？", -- PokemonMansion2F
    ["_PokemonMansion2FSwitchNotPressedText"] = "未可也！", -- PokemonMansion2F
    ["_PokemonMansion3FSuperNerdBattleText"] = "此地大得驚人！", -- PokemonMansion3F
    ["_PokemonMansion3FSuperNerdEndBattleText"] = "哎呀！", -- PokemonMansion3F
    ["_PokemonMansion3FSuperNerdAfterBattleText"] = "不知吾伴往何處矣。", -- PokemonMansion3F
    ["_PokemonMansion3FScientistBattleText"] = "吾師嘗居此。", -- PokemonMansion3F
    ["_PokemonMansion3FScientistEndBattleText"] = "呼！壓倒我矣！", -- PokemonMansion3F
    ["_PokemonMansion3FScientistAfterBattleText"] = "子困於此乎？試自彼處躍下！", -- PokemonMansion3F
    ["_PokemonMansion3FDiaryText"] = "日記：二月六日。混沌蟨產子；新生者命名混沌乙。", -- PokemonMansion3F
    ["_PokemonMansionB1FBurglarBattleText"] = "噫！今吾在何處？", -- PokemonMansionB1F
    ["_PokemonMansionB1FBurglarEndBattleText"] = "嗚呼！", -- PokemonMansionB1F
    ["_PokemonMansionB1FBurglarAfterBattleText"] = "地上常有遺物可拾。", -- PokemonMansionB1F
    ["_PokemonMansionB1FScientistBattleText"] = "此處最宜設驗室。", -- PokemonMansionB1F
    ["_PokemonMansionB1FScientistEndBattleText"] = "咄！何故為此？", -- PokemonMansionB1F
    ["_PokemonMansionB1FScientistAfterBattleText"] = "吾愛此處，最便吾研究！", -- PokemonMansionB1F
    ["_PokemonMansionB1FDiaryText"] = "日記：九月一日。混沌乙之力過甚，兇性終不可制……", -- PokemonMansionB1F
    ["_Route2SignText"] = "第二道\n自碧邑至灰邑", -- Route2
    ["_Route2DiglettsCaveSignText"] = "小潛鼴穴", -- Route2
    ["_Route3Text1"] = "呼……且少息……唉。自縹邑來之隧，真困人甚矣！", -- Route3
    ["_Route3Youngster1BattleText"] = "嗟！碧林遇爾！", -- Route3
    ["_Route3Youngster1EndBattleText"] = "再勝我矣！", -- Route3
    ["_Route3Youngster1AfterBattleText"] = "林中之外，尚有別種㬺獸！", -- Route3
    ["_Route3Youngster2BattleText"] = "幸會！吾愛短袴，便體而易著！", -- Route3
    ["_Route3Youngster2EndBattleText"] = "吾不信也！", -- Route3
    ["_Route3Youngster2AfterBattleText"] = "子以算器藏獸乎？每一獸匣可藏廾獸！", -- Route3
    ["_Route3CooltrainerF1BattleText"] = "方纔是子視我，然乎？", -- Route3
    ["_Route3CooltrainerF1EndBattleText"] = "子真惡！", -- Route3
    ["_Route3CooltrainerF1AfterBattleText"] = "若不欲戰，便休凝視人！", -- Route3
    ["_Route3Youngster3BattleText"] = "子是㬺獸士乎？來戰！", -- Route3
    ["_Route3Youngster3EndBattleText"] = "若吾有新獸，必不敗！", -- Route3
    ["_Route3Youngster3AfterBattleText"] = "算器中獸匣若滿，改用他匣便可！", -- Route3
    ["_Route3CooltrainerF2BattleText"] = "子方纔那一視，甚使人在意！", -- Route3
    ["_Route3CooltrainerF2EndBattleText"] = "善待我些！", -- Route3
    ["_Route3CooltrainerF2AfterBattleText"] = "不欲交戰，莫使人見子！", -- Route3
    ["_Route3Youngster4BattleText"] = "咄！子竟不著短袴！", -- Route3
    ["_Route3Youngster4EndBattleText"] = "敗矣！敗矣！又敗矣！", -- Route3
    ["_Route3Youngster4AfterBattleText"] = "吾冬亦常著短袴！", -- Route3
    ["_Route3Youngster5BattleText"] = "來與吾新獸戰！", -- Route3
    ["_Route3Youngster5EndBattleText"] = "完矣！", -- Route3
    ["_Route3Youngster5AfterBattleText"] = "已馴之獸，常強於野獸！", -- Route3
    ["_Route3CooltrainerF3BattleText"] = "呀！子觸我乎？", -- Route3
    ["_Route3CooltrainerF3EndBattleText"] = "僅此而已乎？", -- Route3
    ["_Route3CooltrainerF3AfterBattleText"] = "第四道在月山麓。", -- Route3
    ["_Route3SignText"] = "第三道\n前為月山", -- Route3
    ["_Route4CooltrainerF1Text"] = "痛！吾為石獸小拳石所絆！", -- Route4
    ["_Route4CooltrainerF2BattleText"] = "吾來尋菌獸！", -- Route4
    ["_Route4CooltrainerF2EndBattleText"] = "嗚呼！吾可愛之菌獸！", -- Route4
    ["_Route4CooltrainerF2AfterBattleText"] = "此處或已無菌矣；想來皆為吾取盡。", -- Route4
    ["_Route4MtMoonSignText"] = "月山\n隧口", -- Route4
    ["_Route4SignText"] = "第四道\n月山至縹邑", -- Route4
    ["_Route5UndergroundPathSignText"] = "地隧\n縹邑至朱邑", -- Route5
    ["_Route9CooltrainerF1BattleText"] = "子攜㬺獸！今歸我戰！", -- Route9
    ["_Route9CooltrainerF1EndBattleText"] = "子欺我！", -- Route9
    ["_Route9CooltrainerF1AfterBattleText"] = "前方隧道幽暗，須有光方可過。", -- Route9
    ["_Route9CooltrainerM1BattleText"] = "彼攜佳獸而行者誰也？", -- Route9
    ["_Route9CooltrainerM1EndBattleText"] = "燈滅矣！", -- Route9
    ["_Route9CooltrainerM1AfterBattleText"] = "繼續走罷！", -- Route9
    ["_Route9CooltrainerM2BattleText"] = "吾欲經岩山隧往紫村……", -- Route9
    ["_Route9CooltrainerM2EndBattleText"] = "吾不能及子！", -- Route9
    ["_Route9CooltrainerM2AfterBattleText"] = "子亦往岩山隧乎？", -- Route9
    ["_Route9CooltrainerF2BattleText"] = "毋敢小我！", -- Route9
    ["_Route9CooltrainerF2EndBattleText"] = "不！子太強矣！", -- Route9
    ["_Route9CooltrainerF2AfterBattleText"] = "子明有才。願子順利！", -- Route9
    ["_Route9Hiker1BattleText"] = "哇哈哈！妙！吾正無聊！", -- Route9
    ["_Route9Hiker1EndBattleText"] = "再來，再來！……哦，吾獸盡矣！", -- Route9
    ["_Route9Hiker1AfterBattleText"] = "子敢與我相抗，膽氣不小！", -- Route9
    ["_Route9Hiker2BattleText"] = "哈哈！小兒亦頗強乎！", -- Route9
    ["_Route9Hiker2EndBattleText"] = "何事？", -- Route9
    ["_Route9Hiker2AfterBattleText"] = "哈哈！童子本當強健！", -- Route9
    ["_Route9Youngster1BattleText"] = "吾日日早起，自繭始養吾㬺獸！", -- Route9
    ["_Route9Youngster1EndBattleText"] = "何！此番工夫盡付流水！", -- Route9
    ["_Route9Youngster1AfterBattleText"] = "欲更強，不能只聚蟲獸……", -- Route9
    ["_Route9Hiker3BattleText"] = "哈哈哈！來，友！", -- Route9
    ["_Route9Hiker3EndBattleText"] = "哈哈哈！子勝得正當！", -- Route9
    ["_Route9Hiker3AfterBattleText"] = "哈哈哈！吾等健漢，常當大笑！", -- Route9
    ["_Route9Youngster2BattleText"] = "去，吾之強蟲獸！", -- Route9
    ["_Route9Youngster2EndBattleText"] = "吾之蟲獸……", -- Route9
    ["_Route9Youngster2AfterBattleText"] = "若厭蟲獸，莫來惱我！", -- Route9
    ["_Route9SignText"] = "第九道\n縹邑至岩山隧", -- Route9
    ["_Route13CooltrainerM1BattleText"] = "吾鳥獸欲戰！", -- Route13
    ["_Route13CooltrainerM1EndBattleText"] = "吾鳥獸之陣竟敗乎？", -- Route13
    ["_Route13CooltrainerM1AfterBattleText"] = "雖敗，吾獸似仍欣然。", -- Route13
    ["_Route13CooltrainerF1BattleText"] = "人皆言吾雖年少而善戰！", -- Route13
    ["_Route13CooltrainerF1EndBattleText"] = "嗚……吾敗矣！", -- Route13
    ["_Route13CooltrainerF1AfterBattleText"] = "吾欲成良㬺獸士，當益勤習。", -- Route13
    ["_Route13CooltrainerF2BattleText"] = "哇！子諸徽章甚美！", -- Route13
    ["_Route13CooltrainerF2EndBattleText"] = "尚不足！", -- Route13
    ["_Route13CooltrainerF2AfterBattleText"] = "吾知此諸徽皆書院山長所授！", -- Route13
    ["_Route13CooltrainerF3BattleText"] = "吾可愛諸獸願與子相識。", -- Route13
    ["_Route13CooltrainerF3EndBattleText"] = "哇！全為子勝矣！", -- Route13
    ["_Route13CooltrainerF3AfterBattleText"] = "欲使獸益強，須使之多戰！", -- Route13
    ["_Route13CooltrainerF4BattleText"] = "吾昔於穴中得消炎痛丸。", -- Route13
    ["_Route13CooltrainerF4EndBattleText"] = "失手矣！", -- Route13
    ["_Route13CooltrainerF4AfterBattleText"] = "消炎痛丸增吾獸之速。", -- Route13
    ["_Route13CooltrainerM2BattleText"] = "風方助我！", -- Route13
    ["_Route13CooltrainerM2EndBattleText"] = "風勢反矣！", -- Route13
    ["_Route13CooltrainerM2AfterBattleText"] = "吾敗矣，且飛歸家。", -- Route13
    ["_Route13Beauty1BattleText"] = "善，與子一戲！", -- Route13
    ["_Route13Beauty1EndBattleText"] = "嗚！小蠻子！", -- Route13
    ["_Route13Beauty1AfterBattleText"] = "雄獸與雌獸，孰較強乎？", -- Route13
    ["_Route13Beauty2BattleText"] = "欲與我鬥獸乎？", -- Route13
    ["_Route13Beauty2EndBattleText"] = "如此便終乎？", -- Route13
    ["_Route13Beauty2AfterBattleText"] = "吾不甚知㬺獸，只愛俊美者！", -- Route13
    ["_Route13BikerBattleText"] = "看甚麼？", -- Route13
    ["_Route13BikerEndBattleText"] = "可惱！齒輪脫矣！", -- Route13
    ["_Route13BikerAfterBattleText"] = "滾開！", -- Route13
    ["_Route13CooltrainerM3BattleText"] = "吾常選鳥獸！", -- Route13
    ["_Route13CooltrainerM3EndBattleText"] = "力盡矣！", -- Route13
    ["_Route13CooltrainerM3AfterBattleText"] = "真欲如蒙雀、颯颯雀般飛翔……", -- Route13
    ["_Route13TrainerTips1Text"] = "㬺獸士須知\n觀彼柱之左！", -- Route13
    ["_Route13TrainerTips2Text"] = "㬺獸士須知\n在物品窗按選鍵，可互易物品次序！", -- Route13
    ["_Route13SignText"] = "第十三道\n北至寂橋", -- Route13
    ["_Route14CooltrainerM1BattleText"] = "欲授獸善技，須用技機！", -- Route14
    ["_Route14CooltrainerM1EndBattleText"] = "尚未足！", -- Route14
    ["_Route14CooltrainerM1AfterBattleText"] = "子有祕傳機乎？其所授之技，獸終不能忘。", -- Route14
    ["_Route14CooltrainerM2BattleText"] = "吾鳥獸應已可戰。", -- Route14
    ["_Route14CooltrainerM2EndBattleText"] = "尚未備好！", -- Route14
    ["_Route14CooltrainerM2AfterBattleText"] = "彼等須習更善之技。", -- Route14
    ["_Route14CooltrainerM3BattleText"] = "技機青邑有售，然祕傳機僅少數人有之！", -- Route14
    ["_Route14CooltrainerM3EndBattleText"] = "唉，可惱！", -- Route14
    ["_Route14CooltrainerM3AfterBattleText"] = "使獸習與己同屬之技，威力更增。", -- Route14
    ["_Route14CooltrainerM4BattleText"] = "子已教鳥獸以飛乎？", -- Route14
    ["_Route14CooltrainerM4EndBattleText"] = "墜火而下！", -- Route14
    ["_Route14CooltrainerM4AfterBattleText"] = "吾所真愛，惟鳥獸耳！", -- Route14
    ["_Route14CooltrainerM5BattleText"] = "聞過傳說中之㬺獸乎？", -- Route14
    ["_Route14CooltrainerM5EndBattleText"] = "何故？何故吾敗？", -- Route14
    ["_Route14CooltrainerM5AfterBattleText"] = "三傳說㬺獸皆猛禽也。", -- Route14
    ["_Route14CooltrainerM6BattleText"] = "吾本無意，然來罷！", -- Route14
    ["_Route14CooltrainerM6EndBattleText"] = "吾早知如此！", -- Route14
    ["_Route14CooltrainerM6AfterBattleText"] = "勝也敗也，久而觀之皆不足道！", -- Route14
    ["_Route14Biker1BattleText"] = "來來！戰戰戰！", -- Route14
    ["_Route14Biker1EndBattleText"] = "嗚！敗矣！滾開！", -- Route14
    ["_Route14Biker1AfterBattleText"] = "何何何？子欲何事？", -- Route14
    ["_Route14Biker2BattleText"] = "妙！吾正欲消磨些時辰！", -- Route14
    ["_Route14Biker2EndBattleText"] = "何？是子！？", -- Route14
    ["_Route14Biker2AfterBattleText"] = "養㬺獸真麻煩。", -- Route14
    ["_Route14Biker3BattleText"] = "吾等來此騎車，只因地方寬！", -- Route14
    ["_Route14Biker3EndBattleText"] = "倒矣！", -- Route14
    ["_Route14Biker3AfterBattleText"] = "子能使獸如此強，頗妙！強者為是，子亦知之！", -- Route14
    ["_Route14Biker4BattleText"] = "鬥獸乎？妙！來亂戰！", -- Route14
    ["_Route14Biker4EndBattleText"] = "為子吹倒矣！", -- Route14
    ["_Route14Biker4AfterBattleText"] = "若只子我二人相鬥，孰勝自明！", -- Route14
    ["_Route14SignText"] = "第十四道\n西至縓邑", -- Route14
    ["_Route17Biker1BattleText"] = "鬥童子無錢可圖！", -- Route17
    ["_Route17Biker1EndBattleText"] = "燒盡矣！", -- Route17
    ["_Route17Biker1AfterBattleText"] = "自轉車道上常有好物遺落！", -- Route17
    ["_Route17Biker2BattleText"] = "小兒，欲何為？", -- Route17
    ["_Route17Biker2EndBattleText"] = "呼！", -- Route17
    ["_Route17Biker2AfterBattleText"] = "吾以腹一撞，便可逐子出去！", -- Route17
    ["_Route17Biker3BattleText"] = "子往縓邑乎？", -- Route17
    ["_Route17Biker3EndBattleText"] = "撞毀而焚！", -- Route17
    ["_Route17Biker3AfterBattleText"] = "吾最愛下坡疾騎！", -- Route17
    ["_Route17Biker4BattleText"] = "吾等騎士，公路之星也！", -- Route17
    ["_Route17Biker4EndBattleText"] = "焦矣！", -- Route17
    ["_Route17Biker4AfterBattleText"] = "子在尋冒險乎？", -- Route17
    ["_Route17Biker5BattleText"] = "使霆毬電子！", -- Route17
    ["_Route17Biker5EndBattleText"] = "接地矣！", -- Route17
    ["_Route17Biker5AfterBattleText"] = "吾之霆毬得自廢電廠。", -- Route17
    ["_Route17Biker6BattleText"] = "吾獸何故不易形？", -- Route17
    ["_Route17Biker6EndBattleText"] = "咄，子！", -- Route17
    ["_Route17Biker6AfterBattleText"] = "或有㬺獸須用屬石乃能易形。", -- Route17
    ["_Route17Biker7BattleText"] = "吾須稍作運動！", -- Route17
    ["_Route17Biker7EndBattleText"] = "呼！此運動甚佳！", -- Route17
    ["_Route17Biker7AfterBattleText"] = "吾必瘦了些！", -- Route17
    ["_Route17Biker8BattleText"] = "當為叛者！", -- Route17
    ["_Route17Biker8EndBattleText"] = "啊——！", -- Route17
    ["_Route17Biker8AfterBattleText"] = "為己所信，須敢戰！", -- Route17
    ["_Route17Biker9BattleText"] = "子車甚佳！操之如何？", -- Route17
    ["_Route17Biker9EndBattleText"] = "可惱！", -- Route17
    ["_Route17Biker9AfterBattleText"] = "此坡使車難御！", -- Route17
    ["_Route17Biker10BattleText"] = "小兒滾開！吾疲甚！", -- Route17
    ["_Route17Biker10EndBattleText"] = "子滿意乎？", -- Route17
    ["_Route17Biker10AfterBattleText"] = "吾須稍眠一覺！", -- Route17
    ["_Route17NoticeSign1Text"] = "告示\n慎遺棄之物！", -- Route17
    ["_Route17TrainerTips1Text"] = "㬺獸士須知\n諸獸各有差異；雖同屬同級，成長亦有遲速。", -- Route17
    ["_Route17TrainerTips2Text"] = "㬺獸士須知\n在坡上按甲鍵或乙鍵，可止車不動。", -- Route17
    ["_Route17SignText"] = "第十七道\n青邑至縓邑", -- Route17
    ["_Route17NoticeSign2Text"] = "告示\n莫棄博局，當擲獸毬！", -- Route17
    ["_Route17CyclingRoadEndsSignText"] = "自轉車道\n坡盡於此！", -- Route17
    ["_Route19CooltrainerM1BattleText"] = "游水前，先暖身！", -- Route19
    ["_Route19CooltrainerM1EndBattleText"] = "身已暖矣！", -- Route19
    ["_Route19CooltrainerM1AfterBattleText"] = "多謝，小友！今可游矣！", -- Route19
    ["_Route19CooltrainerM2BattleText"] = "且住！當心心疾！", -- Route19
    ["_Route19CooltrainerM2EndBattleText"] = "嗚！冷甚！", -- Route19
    ["_Route19CooltrainerM2AfterBattleText"] = "慎光水母！", -- Route19
    ["_Route19Swimmer1BattleText"] = "吾愛游水！子亦然乎？", -- Route19
    ["_Route19Swimmer1EndBattleText"] = "腹先著水矣！", -- Route19
    ["_Route19Swimmer1AfterBattleText"] = "論游水，吾可勝㬺獸！", -- Route19
    ["_Route19Swimmer2BattleText"] = "海天之外有何物？", -- Route19
    ["_Route19Swimmer2EndBattleText"] = "咕嚕！", -- Route19
    ["_Route19Swimmer2AfterBattleText"] = "吾見兩三小島！", -- Route19
    ["_Route19Swimmer3BattleText"] = "吾嘗潛水尋獸，終不可得！", -- Route19
    ["_Route19Swimmer3EndBattleText"] = "救我！", -- Route19
    ["_Route19Swimmer3AfterBattleText"] = "海獸須以釣得之！", -- Route19
    ["_Route19Swimmer4BattleText"] = "吾觀海以忘憂！", -- Route19
    ["_Route19Swimmer4EndBattleText"] = "嗚！更添創矣！", -- Route19
    ["_Route19Swimmer4AfterBattleText"] = "吾還是觀海忘憂罷！", -- Route19
    ["_Route19Swimmer5BattleText"] = "呀！吾甚愛子所乘之獸。若吾勝，可與我乎？", -- Route19
    ["_Route19Swimmer5EndBattleText"] = "嗚！吾敗矣！", -- Route19
    ["_Route19Swimmer5AfterBattleText"] = "至孿島尚遠甚！", -- Route19
    ["_Route19Swimmer6BattleText"] = "游水甚樂，日灼則不然！", -- Route19
    ["_Route19Swimmer6EndBattleText"] = "可驚！", -- Route19
    ["_Route19Swimmer6AfterBattleText"] = "吾男友欲游至孿島。", -- Route19
    ["_Route19Swimmer7BattleText"] = "此水險甚！", -- Route19
    ["_Route19Swimmer7EndBattleText"] = "嗚！果然危險！", -- Route19
    ["_Route19Swimmer7AfterBattleText"] = "吾抽筋矣！咕嚕咕嚕……", -- Route19
    ["_Route19Swimmer8BattleText"] = "吾游至此，已疲矣。", -- Route19
    ["_Route19Swimmer8EndBattleText"] = "力竭矣……", -- Route19
    ["_Route19Swimmer8AfterBattleText"] = "海贔屭如此巨大，乘之渡水必不濕身。", -- Route19
    ["_Route19SignText"] = "第十九水道\n縓邑至孿島", -- Route19
    ["_Route21Fisher1BattleText"] = "欲知魚可上鉤乎？", -- Route21
    ["_Route21Fisher1EndBattleText"] = "可惱！", -- Route21
    ["_Route21Fisher1AfterBattleText"] = "吾總釣不到佳魚！", -- Route21
    ["_Route21Fisher2BattleText"] = "今日大獲！欲試我乎？", -- Route21
    ["_Route21Fisher2EndBattleText"] = "可惱龍門鯉！", -- Route21
    ["_Route21Fisher2AfterBattleText"] = "吾似只釣得龍門鯉！", -- Route21
    ["_Route21Swimmer1BattleText"] = "海水滌我身心！", -- Route21
    ["_Route21Swimmer1EndBattleText"] = "哎呀！", -- Route21
    ["_Route21Swimmer1AfterBattleText"] = "吾亦愛山！", -- Route21
    ["_Route21Swimmer2BattleText"] = "吾游水有何不可？", -- Route21
    ["_Route21Swimmer2EndBattleText"] = "暗算我！", -- Route21
    ["_Route21Swimmer2AfterBattleText"] = "子說吾像何物？有釘之浮輪乎？滾開！", -- Route21
    ["_Route21Swimmer3BattleText"] = "吾諸獸皆於海中所獲！", -- Route21
    ["_Route21Swimmer3EndBattleText"] = "潛者……沉矣！", -- Route21
    ["_Route21Swimmer3AfterBattleText"] = "子之獸於何處所獲？", -- Route21
    ["_Route21Swimmer4BattleText"] = "吾今正參三項競技！", -- Route21
    ["_Route21Swimmer4EndBattleText"] = "呼……呼……呼……", -- Route21
    ["_Route21Swimmer4AfterBattleText"] = "吾已疲甚！然尚有自轉車賽與長跑未畢！", -- Route21
    ["_Route21Swimmer5BattleText"] = "啊！且受日與風！", -- Route21
    ["_Route21Swimmer5EndBattleText"] = "痛！吾敗矣！", -- Route21
    ["_Route21Swimmer5AfterBattleText"] = "吾已曬灼如焦！", -- Route21
    ["_Route21Fisher3BattleText"] = "咄，毋驚吾魚！", -- Route21
    ["_Route21Fisher3EndBattleText"] = "抱歉！非吾本意！", -- Route21
    ["_Route21Fisher3AfterBattleText"] = "吾只是釣無所得，故怒耳。", -- Route21
    ["_Route21Fisher4BattleText"] = "且陪我至有魚上鉤！", -- Route21
    ["_Route21Fisher4EndBattleText"] = "此戰消磨些時辰。", -- Route21
    ["_Route21Fisher4AfterBattleText"] = "且住！有魚咬鉤！善哉！", -- Route21
    ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "吾乃釣魚師！酷愛垂釣。子亦愛釣乎？", -- VermilionOldRodHouse
    ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "妙！吾喜子之性。少年，持此而釣！\f{PLAYER}得{RAM:wStringBuffer}！", -- VermilionOldRodHouse
    ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "垂釣乃人生之道！自海至河，皆可下竿，少年，務得大魚！", -- VermilionOldRodHouse
    ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "嗚……真令人失望……", -- VermilionOldRodHouse
    ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "安，{PLAYER}！近日魚可上鉤乎？", -- VermilionOldRodHouse
    ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "嗚呼！子行囊無隙納吾所贈。", -- VermilionOldRodHouse
    ["_CeladonMart2FMiddleAgedManText"] = "銀驅獸劑可拒弱獸……嗯，比驅獸劑更強。", -- CeladonMart2F
    ["_CeladonMart2FGirlText"] = "遠行宜備元氣片。", -- CeladonMart2F
    ["_CeladonMart2FCurrentFloorSignText"] = "㬺獸士上品 二層：㬺獸士市肆", -- CeladonMart2F
    ["_FuchsiaGoodRodHouseFishingGuruText"] = "吾乃釣魚師之兄！酷愛垂釣。子亦愛釣乎？", -- FuchsiaGoodRodHouse
    ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "妙！吾喜子之性。少年，持此而釣！\f{PLAYER}得{RAM:wStringBuffer}！", -- FuchsiaGoodRodHouse
    ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "嗚……真令人失望……", -- FuchsiaGoodRodHouse
    ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "安，{PLAYER}！近日魚可上鉤乎？", -- FuchsiaGoodRodHouse
    ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "嗚呼！子無隙納吾所贈。", -- FuchsiaGoodRodHouse
    ["_DaycareGentlemanIntroText"] = "吾營養獸舍。欲使吾代養子一獸乎？", -- Daycare
    ["_DaycareGentlemanWhichMonText"] = "欲養何獸？", -- Daycare
    ["_DaycareGentlemanWillLookAfterMonText"] = "善，吾暫為子養{RAM:wNameBuffer}。", -- Daycare
    ["_DaycareGentlemanComeSeeMeInAWhileText"] = "過些時日再來。", -- Daycare
    ["_DaycareGentlemanMonHasGrownText"] = "子之{RAM:wNameBuffer}長進甚多！級數增{NUM:wDayCareNumLevelsGrown, 1, 3}。吾養得善乎？", -- Daycare
    ["_DaycareGentlemanOweMoneyText"] = "欲取回此獸，當付吾円{NUM:wDayCareTotalCost, 2 | LEADING_ZEROES | LEFT_ALIGN}。", -- Daycare
    ["_DaycareGentlemanGotMonBackText"] = "{PLAYER}取回{RAM:wDayCareMonName}！", -- Daycare
    ["_DaycareGentlemanMonNeedsMoreTimeText"] = "已來乎？{RAM:wNameBuffer}尚須再養些時。", -- Daycare
    ["_DaycareGentlemanAllRightThenText"] = "既如此，", -- Daycare
    ["_DaycareGentlemanComeAgainText"] = "他日再來。", -- Daycare
    ["_DaycareGentlemanNoRoomForMonText"] = "子攜獸已滿，無隙納此獸！", -- Daycare
    ["_DaycareGentlemanOnlyHaveOneMonText"] = "子所攜惟一獸。", -- Daycare
    ["_DaycareGentlemanCantAcceptMonWithHMText"] = "知祕傳技之獸，吾不能收養。", -- Daycare
    ["_DaycareGentlemanHeresYourMonText"] = "多謝！此為子之獸！", -- Daycare
    ["_DaycareGentlemanNotEnoughMoneyText"] = "咄，子錢不足！", -- Daycare
    ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "吾乃釣魚師之弟！酷愛垂釣。子亦愛釣乎？", -- Route12SuperRodHouse
    ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "妙！吾喜子之性。持此而釣！\f{PLAYER}得{RAM:wStringBuffer}！", -- Route12SuperRodHouse
    ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "垂釣乃人生之道！自海至河，皆可下竿，務得大魚！", -- Route12SuperRodHouse
    ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "嗚……真令人失望……", -- Route12SuperRodHouse
    ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "安，{PLAYER}！善竿可用於一切水域，可釣得各種㬺獸。凡有水處皆試之！", -- Route12SuperRodHouse
    ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "嗚呼！本有物欲贈子，奈行囊無隙。", -- Route12SuperRodHouse
    ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "不知氣仙公司是否完矣……", -- SilphCo8F
    ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "多謝子救吾等！", -- SilphCo8F
    ["_SilphCo8FRocket1BattleText"] = "子止於此矣！", -- SilphCo8F
    ["_SilphCo8FRocket1EndBattleText"] = "氣力不足！", -- SilphCo8F
    ["_SilphCo8FRocket1AfterBattleText"] = "若不回頭，吾便召援！", -- SilphCo8F
    ["_SilphCo8FScientistBattleText"] = "子使吾等甚為難！", -- SilphCo8F
    ["_SilphCo8FScientistEndBattleText"] = "何？吾敗乎？", -- SilphCo8F
    ["_SilphCo8FScientistAfterBattleText"] = "子以氣仙大樓之迷路為何如？", -- SilphCo8F
    ["_SilphCo8FRocket2BattleText"] = "吾乃火箭四兄弟之一！", -- SilphCo8F
    ["_SilphCo8FRocket2EndBattleText"] = "呼！諸兄弟啊！", -- SilphCo8F
    ["_SilphCo8FRocket2AfterBattleText"] = "其後交吾諸兄弟處置！", -- SilphCo8F
    ["_Route6CooltrainerM1BattleText"] = "誰在彼？休偷聽吾等！", -- Route6
    ["_Route6CooltrainerM1EndBattleText"] = "吾總不能勝！", -- Route6
    ["_Route6CooltrainerAfterBattleText"] = "竊竊……竊竊……", -- Route6
    ["_Route6CooltrainerF1BattleText"] = "失禮！此乃私語，不容外人聽！", -- Route6
    ["_Route6CooltrainerF1EndBattleText"] = "唉！吾最厭敗！", -- Route6
    ["_Route6Youngster1BattleText"] = "此地蟲獸不多。", -- Route6
    ["_Route6Youngster1EndBattleText"] = "不！子戲我乎！", -- Route6
    ["_Route6Youngster1AfterBattleText"] = "吾愛蟲獸，故將返碧林。", -- Route6
    ["_Route6CooltrainerM2BattleText"] = "何？子欲與我語乎？", -- Route6
    ["_Route6CooltrainerM2EndBattleText"] = "非吾先動手！", -- Route6
    ["_Route6CooltrainerM2AfterBattleText"] = "為自保，吾當多攜幾獸。", -- Route6
    ["_Route6CooltrainerF2BattleText"] = "我乎？可。與子一戲！", -- Route6
    ["_Route6CooltrainerF2EndBattleText"] = "終不成矣！", -- Route6
    ["_Route6CooltrainerF2AfterBattleText"] = "吾欲更強！子有何祕訣？", -- Route6
    ["_Route6Youngster2BattleText"] = "吾未曾見子！子善戰乎？", -- Route6
    ["_Route6Youngster2EndBattleText"] = "子太善戰矣！", -- Route6
    ["_Route6Youngster2AfterBattleText"] = "是吾獸弱乎？抑吾不善乎？", -- Route6
    ["_Route6UndergroundPathSignText"] = "地隧\n縹邑至朱邑", -- Route6
    ["_Route8SuperNerd1BattleText"] = "子似善鬥獸，然格致之學如何？", -- Route8
    ["_Route8SuperNerd1EndBattleText"] = "痛！熔毀矣！", -- Route8
    ["_Route8SuperNerd1AfterBattleText"] = "此事吾不如學業！", -- Route8
    ["_Route8Gambler1BattleText"] = "善！且擲骰決勝！", -- Route8
    ["_Route8Gambler1EndBattleText"] = "可惱！差些而已！", -- Route8
    ["_Route8Gambler1AfterBattleText"] = "今日幸神不助我！", -- Route8
    ["_Route8SuperNerd2BattleText"] = "此戰須有謀略方勝！", -- Route8
    ["_Route8SuperNerd2EndBattleText"] = "此不合於理！", -- Route8
    ["_Route8SuperNerd2AfterBattleText"] = "先出汶汶濁……再……再……", -- Route8
    ["_Route8CooltrainerF1BattleText"] = "吾愛雌雄鍼兔，故多聚之！", -- Route8
    ["_Route8CooltrainerF1EndBattleText"] = "何故？何故？", -- Route8
    ["_Route8CooltrainerF1AfterBattleText"] = "㬺獸長大易形後便醜矣！不易最好！", -- Route8
    ["_Route8SuperNerd3BattleText"] = "讀書甚樂，㬺獸亦然。", -- Route8
    ["_Route8SuperNerd3EndBattleText"] = "吾還是專心讀書罷。", -- Route8
    ["_Route8SuperNerd3AfterBattleText"] = "黃邑諸關閉塞，吾等困於此。", -- Route8
    ["_Route8CooltrainerF2BattleText"] = "五銖貓真可愛，喵喵喵！", -- Route8
    ["_Route8CooltrainerF2EndBattleText"] = "喵！", -- Route8
    ["_Route8CooltrainerF2AfterBattleText"] = "吾亦以蒙雀、幼鼠為可愛！", -- Route8
    ["_Route8CooltrainerF3BattleText"] = "吾等如此立著，想必甚可笑！", -- Route8
    ["_Route8CooltrainerF3EndBattleText"] = "看子所為！", -- Route8
    ["_Route8CooltrainerF3AfterBattleText"] = "黃邑守關者不許吾等過，真可惡！", -- Route8
    ["_Route8Gambler2BattleText"] = "吾乃漫遊之博徒！", -- Route8
    ["_Route8Gambler2EndBattleText"] = "大彩未中！", -- Route8
    ["_Route8Gambler2AfterBattleText"] = "博戲與㬺獸如食花生，開了便停不得！", -- Route8
    ["_Route8CooltrainerF4BattleText"] = "何獸可愛、圓而毛茸茸？", -- Route8
    ["_Route8CooltrainerF4EndBattleText"] = "止！毋如此欺吾明魄！", -- Route8
    ["_Route8CooltrainerF4AfterBattleText"] = "聞明魄受月石便可易形。", -- Route8
    ["_Route8UndergroundSignText"] = "地隧\n青邑至紫村", -- Route8
    ["_Route10SuperNerd1BattleText"] = "哇，子亦是怪獸癡乎？欲觀吾所藏乎？", -- Route10
    ["_Route10SuperNerd1EndBattleText"] = "哼！吾未怒！", -- Route10
    ["_Route10SuperNerd1AfterBattleText"] = "吾家尚有更多珍獸！", -- Route10
    ["_Route10Hiker1BattleText"] = "哈、哈哈、啊哈！", -- Route10
    ["_Route10Hiker1EndBattleText"] = "哈哈！今笑不出……花粉病！哈……嚏！", -- Route10
    ["_Route10Hiker1AfterBattleText"] = "哈嚏！哈嚏！哼……涕……", -- Route10
    ["_Route10SuperNerd2BattleText"] = "童子，欲觀吾獸乎？", -- Route10
    ["_Route10SuperNerd2EndBattleText"] = "嗚呼！吾之獸！", -- Route10
    ["_Route10SuperNerd2AfterBattleText"] = "子勝我，吾不喜子！", -- Route10
    ["_Route10CooltrainerF1BattleText"] = "吾曾數往㬺獸書院，然每戰皆敗。", -- Route10
    ["_Route10CooltrainerF1EndBattleText"] = "嗚！又失手矣！", -- Route10
    ["_Route10CooltrainerF1AfterBattleText"] = "吾見數怪獸癡在此徘徊。", -- Route10
    ["_Route10Hiker2BattleText"] = "啊！山氣甘美！", -- Route10
    ["_Route10Hiker2EndBattleText"] = "此戰使吾神清！", -- Route10
    ["_Route10Hiker2AfterBattleText"] = "山氣飲得太多，吾腹似脹矣！", -- Route10
    ["_Route10CooltrainerF2BattleText"] = "此山行太苦，吾有些暈矣。", -- Route10
    ["_Route10CooltrainerF2EndBattleText"] = "吾力不任！", -- Route10
    ["_Route10CooltrainerF2AfterBattleText"] = "此地之獸皆肥厚！當有一粉色而具花紋者！", -- Route10
    ["_Route10RockTunnelSignText"] = "岩山隧", -- Route10
    ["_Route10PowerPlantSignText"] = "電廠", -- Route10
    ["_Route11Gambler1BattleText"] = "勝、負、和，皆可！", -- Route11
    ["_Route11Gambler1EndBattleText"] = "啊！此番不順我意！", -- Route11
    ["_Route11Gambler1AfterBattleText"] = "㬺獸即人生；人生即博！", -- Route11
    ["_Route11Gambler2BattleText"] = "競爭！吾總不厭！", -- Route11
    ["_Route11Gambler2EndBattleText"] = "本有勝機！", -- Route11
    ["_Route11Gambler2AfterBattleText"] = "㬺獸之世，怯者不能立！", -- Route11
    ["_Route11Youngster1BattleText"] = "來戰，毋作弊！", -- Route11
    ["_Route11Youngster1EndBattleText"] = "何？不應如此！", -- Route11
    ["_Route11Youngster1AfterBattleText"] = "吾已盡力，故無悔！", -- Route11
    ["_Route11SuperNerd1BattleText"] = "慎之！吾正鋪電線！", -- Route11
    ["_Route11SuperNerd1EndBattleText"] = "此戰有電！", -- Route11
    ["_Route11SuperNerd1AfterBattleText"] = "告諸人，務節電！", -- Route11
    ["_Route11Youngster2BattleText"] = "吾方為㬺獸士，然自信可勝！", -- Route11
    ["_Route11Youngster2EndBattleText"] = "吾獸不能勝！", -- Route11
    ["_Route11Youngster2AfterBattleText5"] = "子欲何事？休擾我！", -- Route11
    ["_Route11Gambler3BattleText"] = "哇哈哈！吾未嘗一敗！", -- Route11
    ["_Route11Gambler3EndBattleText"] = "吾初敗矣！", -- Route11
    ["_Route11Gambler3AfterBattleText"] = "抽籤之幸耳，皆運也！", -- Route11
    ["_Route11Gambler4BattleText"] = "吾從未勝過……", -- Route11
    ["_Route11Gambler4EndBattleText"] = "果如吾所料……", -- Route11
    ["_Route11Gambler4AfterBattleText"] = "皆運耳，抽籤之幸。", -- Route11
    ["_Route11Youngster3BattleText"] = "吾乃學中第一！", -- Route11
    ["_Route11Youngster3EndBattleText"] = "可惱！須使吾獸更強！", -- Route11
    ["_Route11Youngster3AfterBattleText"] = "有一肥獸自山中下來。若能獲之，甚強。", -- Route11
    ["_Route11SuperNerd2BattleText"] = "慎活電線！", -- Route11
    ["_Route11SuperNerd2EndBattleText"] = "哇！子真如火星塞！", -- Route11
    ["_Route11SuperNerd2AfterBattleText"] = "罷，吾當復工。", -- Route11
    ["_Route11Youngster4BattleText"] = "吾獸今應已備好！", -- Route11
    ["_Route11Youngster4EndBattleText"] = "太強，吾尚太幼！", -- Route11
    ["_Route11Youngster4AfterBattleText"] = "吾當尋更強之獸！", -- Route11
    ["_Route11DiglettsCaveSignText"] = "小潛鼴穴", -- Route11
    ["_Route12SnorlaxText"] = "有獸酣眠塞路！", -- Route12
    ["_Route12SnorlaxWokeUpText"] = "西俯熊醒矣！怒而來襲！", -- Route12
    ["_Route12SnorlaxCalmedDownText"] = "西俯熊息怒矣！大呵欠後，復歸山中。", -- Route12
    ["_Route12Fisher1BattleText"] = "善！此處有魚咬鉤！", -- Route12
    ["_Route12Fisher1EndBattleText"] = "嘖！只是小魚！", -- Route12
    ["_Route12Fisher1AfterBattleText"] = "且住！吾線纏住矣！", -- Route12
    ["_Route12Fisher2BattleText"] = "須耐心！垂釣本是候魚之事。", -- Route12
    ["_Route12Fisher2EndBattleText"] = "此魚遁矣！", -- Route12
    ["_Route12Fisher2AfterBattleText"] = "若有更善之竿，當可釣更佳之獸！", -- Route12
    ["_Route12CooltrainerMBattleText"] = "子得過月石乎？", -- Route12
    ["_Route12CooltrainerMEndBattleText"] = "痛！", -- Route12
    ["_Route12CooltrainerMAfterBattleText"] = "若有月石，本可使吾獸易形！", -- Route12
    ["_Route12SuperNerdBattleText"] = "吾專長在電！", -- Route12
    ["_Route12SuperNerdEndBattleText"] = "拔線矣！", -- Route12
    ["_Route12SuperNerdAfterBattleText"] = "水能導電，故海獸宜以雷擊之！", -- Route12
    ["_Route12Fisher3BattleText"] = "釣魚狂徒對㬺獸童子！", -- Route12
    ["_Route12Fisher3EndBattleText"] = "太強矣！", -- Route12
    ["_Route12Fisher3AfterBattleText"] = "鬥獸子勝我，論垂釣吾則勝子！", -- Route12
    ["_Route12Fisher4BattleText"] = "吾寧願在作工！", -- Route12
    ["_Route12Fisher4EndBattleText"] = "此事不易……", -- Route12
    ["_Route12Fisher4AfterBattleText"] = "無妨，今敗亦不惱我。", -- Route12
    ["_Route12Fisher5BattleText"] = "誰知會釣得何物！", -- Route12
    ["_Route12Fisher5EndBattleText"] = "失之矣！", -- Route12
    ["_Route12Fisher5AfterBattleText"] = "吾常釣得龍門鯉，奈其太弱！", -- Route12
    ["_Route12SignText"] = "第十二道\n北至紫村", -- Route12
    ["_Route12SportFishingSignText"] = "垂釣競技區", -- Route12
    ["_Route15CooltrainerF1BattleText"] = "且試吾新互易得之獸！", -- Route15
    ["_Route15CooltrainerF1EndBattleText"] = "尚不足！", -- Route15
    ["_Route15CooltrainerF1AfterBattleText"] = "互易所得之獸，其別名不可更；惟初獲其獸之士得改。", -- Route15
    ["_Route15CooltrainerF2BattleText"] = "子貌溫柔，吾想可勝！", -- Route15
    ["_Route15CooltrainerF2EndBattleText"] = "不，吾料錯矣！", -- Route15
    ["_Route15CooltrainerF2AfterBattleText"] = "吾怕騎士，貌醜而兇！", -- Route15
    ["_Route15CooltrainerM1BattleText"] = "吾一吹哨，鳥獸便來！", -- Route15
    ["_Route15CooltrainerM1EndBattleText"] = "痛！悲哉！", -- Route15
    ["_Route15CooltrainerM1AfterBattleText"] = "或許吾不宜鬥戰。", -- Route15
    ["_Route15CooltrainerM2BattleText"] = "嗯？吾鳥皆戰慄！子善戰乎？", -- Route15
    ["_Route15CooltrainerM2EndBattleText"] = "果如所料！", -- Route15
    ["_Route15CooltrainerM2AfterBattleText"] = "知乎？地震之類，對鳥獸全無效。", -- Route15
    ["_Route15Beauty1BattleText"] = "哦，小可愛！", -- Route15
    ["_Route15Beauty1EndBattleText"] = "子本來也甚可愛！", -- Route15
    ["_Route15Beauty1AfterBattleText"] = "吾恕子！此敗吾受得！", -- Route15
    ["_Route15Beauty2BattleText"] = "吾獨居，故養㬺獸為伴。", -- Route15
    ["_Route15Beauty2EndBattleText"] = "吾可沒求此戰！", -- Route15
    ["_Route15Beauty2AfterBattleText"] = "吾只愛歸家與獸相伴！", -- Route15
    ["_Route15Biker1BattleText"] = "小兒，來！吾新得此等獸！", -- Route15
    ["_Route15Biker1EndBattleText"] = "何故不成？", -- Route15
    ["_Route15Biker1AfterBattleText"] = "人生一度，故吾寧為不法之徒！火箭賊萬歲！", -- Route15
    ["_Route15Biker2BattleText"] = "小兒，若敗便盡交錢來！", -- Route15
    ["_Route15Biker2EndBattleText"] = "此事豈真！", -- Route15
    ["_Route15Biker2AfterBattleText"] = "方纔索錢，只是戲言！", -- Route15
    ["_Route15CooltrainerF3BattleText"] = "何事最妙？互易㬺獸也！", -- Route15
    ["_Route15CooltrainerF3EndBattleText"] = "吾說互易！", -- Route15
    ["_Route15CooltrainerF3AfterBattleText"] = "吾常與友互易㬺獸！", -- Route15
    ["_Route15CooltrainerF4BattleText"] = "欲與吾獸戲乎？", -- Route15
    ["_Route15CooltrainerF4EndBattleText"] = "吾太躁進矣！", -- Route15
    ["_Route15CooltrainerF4AfterBattleText"] = "吾去與弱些之人鍛鍊。", -- Route15
    ["_Route15SignText"] = "第十五道\n西至縓邑", -- Route15
    ["_Route16Biker1BattleText"] = "欲何為？", -- Route16
    ["_Route16Biker1EndBattleText"] = "毋敢笑我！", -- Route16
    ["_Route16Biker1AfterBattleText"] = "吾等只愛聚此，干子何事？", -- Route16
    ["_Route16Biker2BattleText"] = "車不錯！交出來！", -- Route16
    ["_Route16Biker2EndBattleText"] = "倒下矣！", -- Route16
    ["_Route16Biker2AfterBattleText"] = "罷了，誰稀罕子車！", -- Route16
    ["_Route16Biker3BattleText"] = "小鼠，出來玩！", -- Route16
    ["_Route16Biker3EndBattleText"] = "小鼠輩！", -- Route16
    ["_Route16Biker3AfterBattleText"] = "吾最恨敗！滾遠些！", -- Route16
    ["_Route16biker4BattleText"] = "咄，子方撞我！", -- Route16
    ["_Route16Biker4EndBattleText"] = "轟！", -- Route16
    ["_Route16Biker4AfterBattleText"] = "自朱邑沿海路，亦可至縓邑。", -- Route16
    ["_Route16Biker5BattleText"] = "吾又餓又怒！", -- Route16
    ["_Route16Biker5EndBattleText"] = "惡！惡！惡！", -- Route16
    ["_Route16Biker5AfterBattleText"] = "吾愛兇猛之獸，能撕敵為碎！", -- Route16
    ["_Route16Biker6BattleText"] = "善，吾來！", -- Route16
    ["_Route16Biker6EndBattleText"] = "毋使吾怒！", -- Route16
    ["_Route16Biker6AfterBattleText"] = "吾愛使兇獸侵擾行人！", -- Route16
    ["_Route16Text7"] = "有獸酣眠塞路！", -- Route16
    ["_Route16SnorlaxWokeUpText"] = "西俯熊醒矣！怒而來襲！", -- Route16
    ["_Route16SnorlaxReturnedToMountainsText"] = "西俯熊大呵欠後，復歸山中。", -- Route16
    ["_Route16CyclingRoadSignText"] = "樂此下坡！自轉車道", -- Route16
    ["_Route16SignText"] = "第十六道\n青邑至縓邑", -- Route16
    ["_Route18CooltrainerM1BattleText"] = "吾總查遍每片草地，以尋新獸。", -- Route18
    ["_Route18CooltrainerM1EndBattleText"] = "嘖！", -- Route18
    ["_Route18CooltrainerM1AfterBattleText"] = "真願有一自轉車！", -- Route18
    ["_Route18CooltrainerM2BattleText"] = "咕嚕咕！吾學鳥鳴如何？", -- Route18
    ["_Route18CooltrainerM2EndBattleText"] = "只得惱子一回！", -- Route18
    ["_Route18CooltrainerM2AfterBattleText"] = "週末吾亦收海獸！", -- Route18
    ["_Route18CooltrainerM3BattleText"] = "此乃吾地盤！速去！", -- Route18
    ["_Route18CooltrainerM3EndBattleText"] = "可惱！", -- Route18
    ["_Route18CooltrainerM3AfterBattleText"] = "此處是吾最愛尋獸之地！", -- Route18
    ["_Route18SignText"] = "第十八道\n青邑至縓邑", -- Route18
    ["_Route18CyclingRoadSignText"] = "自轉車道\n禁步行者！", -- Route18
    ["_PokemonFanClubPikachuFanNormalText"] = "不觀吾小電蟨可愛之尾乎？", -- PokemonFanClub
    ["_PokemonFanClubPikachuFanBetterText"] = "哼！吾小電蟨比彼隻可愛一倍！", -- PokemonFanClub
    ["_PokemonFanClubSeelFanNormalText"] = "吾最愛歡海驢！抱之便吱吱叫！", -- PokemonFanClub
    ["_PokemonFanClubSeelFanBetterText"] = "哎呀！吾歡海驢明明更美！", -- PokemonFanClub
    ["_PokemonFanClubPikachuText"] = "小電蟨：啾！皮卡！", -- PokemonFanClub
    ["_PokemonFanClubSeelText"] = "歡海驢：啾嗚！", -- PokemonFanClub
    ["_PokemonFanClubChairmanIntroText"] = "吾為㬺獸好者會會長！所藏㬺獸已逾百種。論獸，吾挑剔甚矣！所以……子來聽吾談所愛之獸乎？", -- PokemonFanClub
    ["_PokemonFanClubChairmanStoryText"] = "善！且聽。吾最愛午馳駿……可愛……美麗……聰慧……又……奇妙……是乎？當然……姿容絕佳……性又溫良……吾愛甚！抱之而眠……暖且柔……妙極……艷極……呀！時候不早，竟留子太久！多謝聽吾絮語。此物贈子！", -- PokemonFanClub
    ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- PokemonFanClub
    ["_PokemonFanClubExplainBikeVoucherText"] = "以此可換自轉車！毋憂，吾有鑽鷲，可載吾飛往各處，故不需自轉車。願子樂騎！", -- PokemonFanClub
    ["_PokemonFanClubNoStoryText"] = "哦。待子欲聽吾故事時再來！", -- PokemonFanClub
    ["_PokemonFanClubChairFinalText"] = "安，{PLAYER}！又來問吾獸乎？非乎？可惜！", -- PokemonFanClub
    ["_PokemonFanClubBagFullText"] = "須先空行囊一隙！", -- PokemonFanClub
    ["_PokemonFanClubReceptionistText"] = "吾會長論㬺獸，最是多言。", -- PokemonFanClub
    ["_PokemonFanClubSign1Text"] = "皆當有禮聽他㬺獸士之言！", -- PokemonFanClub
    ["_PokemonFanClubSign2Text"] = "若有人自誇，便以自誇報之！", -- PokemonFanClub
    ["SilphCo2FSilphWorkerFPleaseTakeThisText"] = "啊！不！止！救我！……哦，子非火箭賊。吾方纔誤會了，抱歉。此物請收！", -- SilphCo2F
    ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- SilphCo2F
    ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "技機卅六載自爆。威力極大，然施者亦仆倒，慎用！", -- SilphCo2F
    ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "行囊無隙可納此物。", -- SilphCo2F
    ["_SilphCo2FScientist1BattleText"] = "救我！吾是氣仙公司雇員！", -- SilphCo2F
    ["_SilphCo2FScientist1EndBattleText"] = "子何以知吾是火箭賊？", -- SilphCo2F
    ["_SilphCo2FScientist1AfterBattleText"] = "吾兼為氣仙公司與火箭賊做事！", -- SilphCo2F
    ["_SilphCo2FScientist2BattleText"] = "此處禁入！歸家去！", -- SilphCo2F
    ["_SilphCo2FScientist2EndBattleText"] = "子頗強。", -- SilphCo2F
    ["_SilphCo2FScientist2AfterBattleText"] = "子能解此樓迷陣乎？", -- SilphCo2F
    ["_SilphCo2FRocket1BattleText"] = "此處不許童子入！", -- SilphCo2F
    ["_SilphCo2FRocket1EndBattleText"] = "強哉！", -- SilphCo2F
    ["_SilphCo2FRocket1AfterBattleText"] = "菱形地磚乃瞬移格，可遽送人他處，皆新式之機也！", -- SilphCo2F
    ["_SilphCo2FRocket2BattleText"] = "小兒，子來此何為？", -- SilphCo2F
    ["_SilphCo2FRocket2EndBattleText"] = "吾失策矣！", -- SilphCo2F
    ["_SilphCo2FRocket2AfterBattleText"] = "氣仙公司將與火箭賊合併！", -- SilphCo2F
    ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "吾為氣仙公司做事，今當如何？", -- SilphCo3F
    ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}！子與獸救了吾等！", -- SilphCo3F
    ["_SilphCo3FRocketBattleText"] = "小兒，休來搗亂！", -- SilphCo3F
    ["_SilphCo3FRocketEndBattleText"] = "吾服矣！", -- SilphCo3F
    ["_SilphCo3FRocketAfterBattleText"] = "提示乎？管鑰票可啟諸門！", -- SilphCo3F
    ["_SilphCo3FScientistBattleText"] = "吾助火箭賊，更勝助氣仙公司！", -- SilphCo3F
    ["_SilphCo3FScientistEndBattleText"] = "真為子所敗！", -- SilphCo3F
    ["_SilphCo3FScientistAfterBattleText"] = "哼……火箭賊言，若吾助彼，便許吾研究㬺獸！", -- SilphCo3F
    ["_SilphCo10FSilphWorkerFImScaredText"] = "哇——！吾怕甚！", -- SilphCo10F
    ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "請莫傳吾哭泣之事！", -- SilphCo10F
    ["_SilphCo10FRocketBattleText"] = "歡迎至十層！子能來陪我，甚善！", -- SilphCo10F
    ["_SilphCo10FRocketEndBattleText"] = "吾驚倒矣！", -- SilphCo10F
    ["_SilphCo10FRocketAfterBattleText"] = "試得不錯，然會議室尚在上一層！", -- SilphCo10F
    ["_SilphCo10FScientistBattleText"] = "休再作此無聊之戲！", -- SilphCo10F
    ["_SilphCo10FScientistEndBattleText"] = "再無續局矣！", -- SilphCo10F
    ["_SilphCo10FScientistAfterBattleText"] = "勝我便足乎？足則歸家！", -- SilphCo10F
    ["_LancesRoomLanceBeforeBattleText"] = "阿渡：啊，聞子名久矣，{PLAYER}！吾領四天王，名阿渡，專馭龍獸。龍乃神異之獸，難獲難養，而其力最上，幾不可摧。子已備敗乎？{PLAYER}，子之聯會挑戰，至吾而止！", -- LancesRoom
    ["_LancesRoomLanceEndBattleText"] = "至此而已！吾雖不欲認，子已可稱㬺獸大師！", -- LancesRoom
    ["_LancesRoomLanceAfterBattleText"] = "吾至今仍難信龍獸竟敗於子，{PLAYER}！子今本當為㬺獸聯會之魁……然尚有一戰。另有一士，名{RIVAL}，先子一步勝四天王。彼方是真正聯會之魁！", -- LancesRoom
    ["_HallOfFameOakText"] = "大木：咳！賀子，{PLAYER}！此層乃凌煙閣。凡㬺獸聯會之魁，其功皆圖於此，其所攜之獸亦同錄焉。{PLAYER}！子勤勉至此，終成新魁。賀哉，{PLAYER}！子與諸獸今皆圖形凌煙閣！", -- HallOfFame
    ["_Museum1FScientist1ComeAgainText"] = "後當復來！", -- Museum1F
    ["_Museum1FScientist1WouldYouLikeToComeInText"] = "童券五十円，欲入乎？", -- Museum1F
    ["_Museum1FScientist1ThankYouText"] = "然，五十円。多謝！", -- Museum1F
    ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "錢不足。", -- Museum1F
    ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "後門不可偷入！罷了。子知琥珀乎？", -- Museum1F
    ["_Museum1FScientist1TheresALabSomewhereText"] = "有驗室正試由琥珀復生古㬺獸。", -- Museum1F
    ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "琥珀者，樹脂久化而成也。", -- Museum1F
    ["_Museum1FScientist1GoToOtherSideText"] = "請往彼側！", -- Museum1F
    ["_Museum1FScientist1TakePlentyOfTimeText"] = "徐徐觀之！", -- Museum1F
    ["_Museum1FGamblerText"] = "何其巨麗之僵石！", -- Museum1F
    ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "噓！吾疑此琥珀內存㬺獸遺傳質。若由此可復生㬺獸，豈不妙哉！然同僚皆不理吾。故有一請：持此至㬺獸驗室，使之檢驗！", -- Museum1F
    ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER}得古琥珀！", -- Museum1F
    ["_Museum1FScientist2GetTheOldAmberCheckText"] = "噓！須將古琥珀驗之！", -- Museum1F
    ["_Museum1FScientist2YouDontHaveSpaceText"] = "行囊無隙。", -- Museum1F
    ["_Museum1FScientist3Text"] = "館藏二僵石，皆上古極罕㬺獸，吾等以此為榮！", -- Museum1F
    ["_Museum1FOldAmberText"] = "此琥珀澄澈金黃。", -- Museum1F
    ["_Museum2FYoungsterText"] = "月石？有何異乎？", -- Museum2F
    ["_Museum2FGrampsText"] = "一九六九年七月廾日！人類初登月！吾特買彩色電視觀之。", -- Museum2F
    ["_Museum2FScientistText"] = "今有宇宙展。", -- Museum2F
    ["_Museum2FBrunetteGirlText"] = "吾欲小電蟨！甚可愛！已請父為我獲一。", -- Museum2F
    ["_Museum2FHikerText"] = "然，不久即給子小電蟨，吾許之。", -- Museum2F
    ["_Museum2FSpaceShuttleSignText"] = "航天梭 哥倫比亞號", -- Museum2F
    ["_Museum2FMoonStoneSignText"] = "墜於月山之隕石（月石？）", -- Museum2F
    ["_PewterGymBrockPreBattleText"] = "吾岳右夫，灰邑書院山長也！吾信守堅如岩，志不可奪。故所使皆石屬㬺獸。子猶欲挑戰乎？善！盡其技來！", -- PewterGym
    ["_PewterGymBrockPostBattleAdviceText"] = "天下㬺獸士其術各異。觀子於此道頗有才。往縹邑書院試技去！", -- PewterGym
    ["_PewterGymBrockWaitTakeThisText"] = "且住！攜此去！", -- PewterGym
    ["_PewterGymReceivedTM34Text"] = "{PLAYER}得技機卅四！", -- PewterGym
    ["_TM34ExplanationText"] = "技機中載可授㬺獸之技。技機一用即盡，故授新技時，須慎擇其獸。技機卅四載忍耐。此技受敵傷而蓄之，後倍返之。", -- PewterGym
    ["_PewterGymTM34NoRoomText"] = "行囊無隙。", -- PewterGym
    ["_PewterGymBrockReceivedBoulderBadgeText"] = "吾先前輕子矣。以勝之證，授子灰徽！\f{PLAYER}得灰徽！", -- PewterGym
    ["_PewterGymBrockBoulderBadgeInfoText"] = "此㬺獸聯會所認之徽也！持者所攜之獸力益強。今閃光之技可隨時用。", -- PewterGym
    ["_PewterGymCooltrainerMBattleText"] = "小子，止！距見岳右夫尚有光年之遙！", -- PewterGym
    ["_PewterGymCooltrainerMEndBattleText"] = "可惱！光年非時，乃量遠近也！", -- PewterGym
    ["_PewterGymCooltrainerMAfterBattleText"] = "子頗有本事，然未及岳右夫！", -- PewterGym
    ["_PewterGymGuidePreAdviceText"] = "啊！一見便知子有成魁之材！吾雖非㬺獸士，卻知取勝之法。吾引子登頂！", -- PewterGym
    ["_PewterGymGuideBeginAdviceText"] = "善！即始！", -- PewterGym
    ["_PewterGymGuideAdviceText"] = "戰時首出者，即攜獸列首者。易其先後，可使戰事較易。", -- PewterGym
    ["_PewterGymGuideFreeServiceText"] = "此教不取金！即始！", -- PewterGym
    ["_PewterGymGuidePostBattleText"] = "果如吾料！子真有成魁之材！", -- PewterGym
    ["_PewterPokecenterGentlemanText"] = "何！？火箭賊在月山？咦？吾正與人通話！去去！", -- PewterPokecenter
    ["_PewterPokecenterJigglypuffText"] = "謳毬毚：噗噗噗！", -- PewterPokecenter
    ["_CeruleanPokecenterSuperNerdText"] = "正輝那人！聞為求珍獸，無所不用其極！", -- CeruleanPokecenter
    ["_CeruleanPokecenterGentlemanText"] = "聞過正輝乎？人人稱之怪獸癡！吾看只是妒他耳。誰不願誇己之獸？", -- CeruleanPokecenter
    ["_CeruleanGymMistyPreBattleText"] = "霞海花：幸會，新面孔！欲成專門㬺獸士，須先有馭獸之方。子獲獸時持何道？吾之方，乃以水屬獸猛攻到底！", -- CeruleanGym
    ["_CeruleanGymMistyTM11ExplanationText"] = "技機十一載泡光！宜授水棲之獸。", -- CeruleanGym
    ["_CeruleanGymMistyCascadeBadgeInfoText"] = "青徽使三十級以下諸獸皆聽命，外來獸亦然。又可隨時用切，斷小灌木以開新路。並受吾最愛之技機！", -- CeruleanGym
    ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER}得技機十一！", -- CeruleanGym
    ["_CeruleanGymMistyTM11NoRoomText"] = "先空行囊一隙！", -- CeruleanGym
    ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "哇！子太強矣！善，青徽與子，以誌勝吾！", -- CeruleanGym
    ["_CeruleanGymBattleText1"] = "吾之技已足勝子！霞海花且後再說！", -- CeruleanGym
    ["_CeruleanGymEndBattleText1"] = "為子壓倒矣！", -- CeruleanGym
    ["_CeruleanGymAfterBattleText1"] = "須多與諸士交戰，乃知己技之高下。", -- CeruleanGym
    ["_CeruleanGymBattleText2"] = "潑！吾先來！戰罷！", -- CeruleanGym
    ["_CeruleanGymEndBattleText2"] = "豈有此理！", -- CeruleanGym
    ["_CeruleanGymAfterBattleText2"] = "霞海花尚會益進！不會敗於子這等人！", -- CeruleanGym
    ["_CeruleanGymGymGuideChampInMakingText"] = "咄，將為魁者！聽我一言。山長霞海花善用水屬獸。以草屬吸其水，或以雷電擊之！", -- CeruleanGym
    ["_CeruleanGymGymGuideBeatMistyText"] = "子勝霞海花矣！吾言如何？子我二人配合得妙！", -- CeruleanGym
    ["_CeruleanMartCooltrainerMText"] = "用驅獸劑可拒蟲與弱獸。欲效最佳，將最強之獸置攜獸之首。", -- CeruleanMart
    ["_CeruleanMartCooltrainerFText"] = "見過奇飴乎？聞可使獸升一級！", -- CeruleanMart
    ["_LavenderPokecenterGentlemanText"] = "火箭賊為金錢，無所不為！", -- LavenderPokecenter
    ["_LavenderPokecenterLittleGirlText"] = "吾親見髑髏螭之母逃火箭賊時被殺！", -- LavenderPokecenter
    ["_LavenderMartBaldingGuyText"] = "吾正尋戰中暫增獸能之丸。增力丸、增守丸、增速丸、增異能丸，皆吾所求。子知何處有售乎？", -- LavenderMart
    ["_LavenderMartCooltrainerMReviveText"] = "知乎元氣片？仆倒之獸可由之復起！", -- LavenderMart
    ["_LavenderMartCooltrainerMNuggetText"] = "吾於山中得金珠，原以為無用，竟售得五千円！", -- LavenderMart
    ["_VermilionPokecenterFishingGuruText"] = "雖同級，獸之諸能亦可相差甚遠。經人養者，常強於野獸。", -- VermilionPokecenter
    ["_VermilionPokecenterSailorText"] = "吾獸中毒，行路間竟仆倒矣！", -- VermilionPokecenter
    ["_VermilionMartCooltrainerMText"] = "有惡人役㬺獸作罪。火箭賊販賣珍獸，又棄其以為不受歡迎或無用者。", -- VermilionMart
    ["_VermilionMartCooltrainerFText"] = "吾意㬺獸本無善惡，視養者而定。", -- VermilionMart
    ["_VermilionGymLTSurgePreBattleText"] = "馬志士：咄，小兒！來此何為？戰場上子活不久，此事吾最知！昔戰爭時，雷獸救吾性命，電麻敵軍。今吾亦將如此制子！", -- VermilionGym
    ["_VermilionGymLTSurgePostBattleAdviceText"] = "小兒，再教子一事：雷電雖強，對土屬獸全無用！", -- VermilionGym
    ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "橙徽可增獸之速，又使獸隨時能飛。小兒，子殊異，並取此物！", -- VermilionGym
    ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- VermilionGym
    ["_TM24ExplanationText"] = "技機廾四載十萬伏特！宜授雷屬獸。", -- VermilionGym
    ["_VermilionGymLTSurgeTM24NoRoomText"] = "小兒，行囊先空一隙！", -- VermilionGym
    ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "哇！小兒，子真有本事！善，橙徽取去！", -- VermilionGym
    ["_VermilionGymGentlemanBattleText"] = "吾從軍時，馬志士是吾嚴厲之長官！", -- VermilionGym
    ["_VermilionGymGentlemanEndBattleText"] = "止！子甚善戰！", -- VermilionGym
    ["_VermilionGymGentlemanAfterBattleText"] = "門不開乎？馬志士向來謹慎！", -- VermilionGym
    ["_VermilionGymSuperNerdBattleText"] = "吾身輕弱，然善弄電！", -- VermilionGym
    ["_VermilionGymSuperNerdEndBattleText"] = "焦矣！", -- VermilionGym
    ["_VermilionGymSuperNerdAfterBattleText"] = "善，吾說！馬志士言將門之按機藏於某物中。", -- VermilionGym
    ["_VermilionGymSailorBattleText"] = "此處非童子之地！", -- VermilionGym
    ["_VermilionGymSailorEndBattleText"] = "哇！嚇我一跳！", -- VermilionGym
    ["_VermilionGymSailorAfterBattleText"] = "馬志士設雙重之鎖。提示：第一鎖既啟，第二鎖就在其旁！", -- VermilionGym
    ["_VermilionGymGymGuideChampInMakingText"] = "咄，將為魁者！馬志士有號，世稱「雷霆美利堅人」。彼精雷屬獸；飛、水二屬皆危，亦慎麻痺。彼極謹慎，欲見之須先破鎖謎！", -- VermilionGym
    ["_VermilionGymGymGuideBeatLTSurgeText"] = "呼！此戰真有電！", -- VermilionGym
    ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}：安！子好㬺獸乎？\f{PLAYER}：呃，不，是吾先問。\f{PLAYER}：何？子真怪！\f仿娘：嗯？毋仿子乎？然此乃吾最愛之戲！", -- CopycatsHouse2F
    ["_CopycatsHouse2FCopycatTM31PreReceiveText"] = "哇！明魄偶！贈我乎？多謝！則此物與子！", -- CopycatsHouse2F
    ["_CopycatsHouse2FCopycatReceivedTM31Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CopycatsHouse2F
    ["_CopycatsHouse2FCopycatTM31Explanation1Text"] = "技機卅一載吾最愛之仿！宜授佳獸。", -- CopycatsHouse2F
    ["_CopycatsHouse2FCopycatTM31Explanation2Text"] = "{PLAYER}：安！多謝技機卅一！\f{PLAYER}：何？\f{PLAYER}：仿吾一舉一動如此有趣乎？\f仿娘：當然！樂極矣！", -- CopycatsHouse2F
    ["_CopycatsHouse2FCopycatTM31NoRoomText"] = "子不要此物乎？", -- CopycatsHouse2F
    ["_CopycatsHouse2FDoduoText"] = "雙首鳩：咿——！鏡兮鏡兮，壁上之鏡，天下孰最美？", -- CopycatsHouse2F
    ["_CopycatsHouse2FRareDollText"] = "此乃珍稀㬺獸！咦？只是偶人。", -- CopycatsHouse2F
    ["_CopycatsHouse2FSNESText"] = "一遊戲，馬里奧戴桶於首！", -- CopycatsHouse2F
    ["_CopycatsHouse2FPCMySecretsText"] = "……吾之祕密！技：仿人！好：收偶！最愛㬺獸：明魄！", -- CopycatsHouse2F
    ["_CopycatsHouse2FPCCantSeeText"] = "何？看不見！", -- CopycatsHouse2F
    ["_FightingDojoKarateMasterText"] = "武德：喝！吾乃空手之師，為此道場之主！子欲挑戰吾等？休望留情！哈啊！", -- FightingDojo
    ["_FightingDojoKarateMasterDefeatedText"] = "哈！嗚！吾敗矣！", -- FightingDojo
    ["_FightingDojoKarateMasterIWillGiveYouAPokemonText"] = "誠然，吾已敗！但求子毋取吾院徽記為戰利。吾願以珍藏鬥獸一隻相贈，任子擇之！", -- FightingDojo
    ["_FightingDojoKarateMasterStayAndTrainWithUsText"] = "喝！留此與吾等習空手之術！", -- FightingDojo
    ["_FightingDojoBlackbelt1BattleText"] = "喝啊！脫履再戰！", -- FightingDojo
    ["_FightingDojoBlackbelt1EndBattleText"] = "吾服矣！", -- FightingDojo
    ["_FightingDojoBlackbelt1AfterBattleText"] = "且待子見吾師！較之，吾只是小卒。", -- FightingDojo
    ["_FightingDojoBlackbelt2BattleText"] = "聞子善戰！示我！", -- FightingDojo
    ["_FightingDojoBlackbelt2EndBattleText"] = "裁者！一分！", -- FightingDojo
    ["_FightingDojoBlackbelt2AfterBattleText"] = "吾師乃鬥技宗匠！", -- FightingDojo
    ["_FightingDojoBlackbelt3BattleText"] = "再強之物亦不能嚇我！吾以碎巨石為鍛鍊！", -- FightingDojo
    ["_FightingDojoBlackbelt3EndBattleText"] = "痛！指傷矣！", -- FightingDojo
    ["_FightingDojoBlackbelt3AfterBattleText"] = "吾等惟懼念力！", -- FightingDojo
    ["_FightingDojoBlackbelt4BattleText"] = "喝哈！子擅入吾鬥道場！", -- FightingDojo
    ["_FightingDojoBlackbelt4EndBattleText"] = "嗚！吾服！", -- FightingDojo
    ["_FightingDojoBlackbelt4AfterBattleText"] = "天下精於鬥者皆來此修習。", -- FightingDojo
    ["_FightingDojoHitmonleePokeBallText"] = "子欲善蹴之蹴踏拳乎？", -- FightingDojo
    ["_FightingDojoHitmonchanPokeBallText"] = "子欲連拳如機之連打拳乎？", -- FightingDojo
    ["_FightingDojoBetterNotGetGreedyText"] = "毋太貪……", -- FightingDojo
    ["_SaffronGymSabrinaText"] = "棗夢：吾先見子來之兆。自幼即有念力；初能以心屈匙。吾不喜鬥，然子既求之，便示吾力。", -- SaffronGym
    ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "吾驚矣！然敗即敗。吾承認修習不足。金徽歸子！", -- SaffronGym
    ["_SaffronGymSabrinaPostBattleAdviceText"] = "人人皆有念力，只是不自知耳。", -- SaffronGym
    ["_SaffronGymSabrinaMarshBadgeInfoText"] = "金徽使七十級以下之獸聽命。過強之獸或狂而不受令，故毋養過甚。且受此技機。", -- SaffronGym
    ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER}得技機卌六！", -- SaffronGym
    ["_TM46ExplanationText"] = "技機卌六載念波，以強念之浪傷敵！", -- SaffronGym
    ["_SaffronGymSabrinaTM46NoRoomText"] = "子行囊已滿！", -- SaffronGym
    ["_SaffronGymGuideChampInMakingText"] = "咄，將為魁者！棗夢之獸用念力，不恃膂力。鬥屬最畏念屬，拳未及發便可敗。", -- SaffronGym
    ["_SaffronGymGuideBeatSabrinaText"] = "念力乎？若吾有之，博場必可大獲！", -- SaffronGym
    ["_SaffronGymChanneler1BattleText"] = "棗夢雖少於吾，吾甚敬之！", -- SaffronGym
    ["_SaffronGymChanneler1EndBattleText"] = "尚不足！", -- SaffronGym
    ["_SaffronGymChanneler1AfterBattleText"] = "兩力相當者相鬥，志更強者勝。欲勝棗夢，專心求勝！", -- SaffronGym
    ["_SaffronGymYoungster1BattleText"] = "吾等無形之力，使子怕乎？", -- SaffronGym
    ["_SaffronGymYoungster1EndBattleText"] = "此事吾從未預見！", -- SaffronGym
    ["_SaffronGymYoungster1AfterBattleText"] = "念屬獸惟畏鬼與蟲！", -- SaffronGym
    ["_SaffronGymChanneler2BattleText"] = "獸貌常類其養者。如此看來，子獸必甚強！", -- SaffronGym
    ["_SaffronGymChanneler2EndBattleText"] = "吾早知如此！", -- SaffronGym
    ["_SaffronGymChanneler2AfterBattleText"] = "吾須授獸更善之技！", -- SaffronGym
    ["_SaffronGymYoungster2BattleText"] = "子知徒有力不足乎？", -- SaffronGym
    ["_SaffronGymYoungster2EndBattleText"] = "吾不信此事！", -- SaffronGym
    ["_SaffronGymYoungster2AfterBattleText"] = "棗夢方纔將隔壁武德擊得大敗！", -- SaffronGym
    ["_SaffronGymChanneler3BattleText"] = "子我之獸，當一戰！", -- SaffronGym
    ["_SaffronGymChanneler3EndBattleText"] = "終究吾敗矣！", -- SaffronGym
    ["_SaffronGymChanneler3AfterBattleText"] = "吾早知此事必然發生。", -- SaffronGym
    ["_SaffronGymYoungster3BattleText"] = "棗夢雖少，亦吾院山長。子不易到彼處！", -- SaffronGym
    ["_SaffronGymYoungster3EndBattleText"] = "吾失其定心矣！", -- SaffronGym
    ["_SaffronGymYoungster3AfterBattleText"] = "昔黃邑有兩㬺獸書院。隔壁鬥道場被吾等大敗後，遂失書院之名。", -- SaffronGym
    ["_SaffronGymYoungster4BattleText"] = "黃邑書院以念士聞名！子欲見棗夢，吾已知之！", -- SaffronGym
    ["_SaffronGymYoungster4EndBattleText"] = "啊——！", -- SaffronGym
    ["_SaffronGymYoungster4AfterBattleText"] = "正是！吾以傳心之術讀子心矣！", -- SaffronGym
    ["_SaffronMartSuperNerdText"] = "金驅獸劑拒弱獸之效，比銀驅獸劑更久！", -- SaffronMart
    ["_SaffronMartCooltrainerFText"] = "元氣片雖貴，能使仆倒之獸復起！", -- SaffronMart
    ["_SilphCo1FLinkReceptionistText"] = "歡迎！總辦在十一層會議室！", -- SilphCo1F
    ["_SaffronPokecenterBeautyText"] = "㬺獸成長之速，各種不同。", -- SaffronPokecenter
    ["_SaffronPokecenterGentlemanText"] = "氣仙公司名聞甚廣，故招火箭賊而來！", -- SaffronPokecenter
    ["_ViridianForestNorthGateSuperNerdText"] = "多有㬺獸惟生林穴。欲得異種，須遍求諸處。", -- ViridianForestNorthGate
    ["_ViridianForestNorthGateGrampsText"] = "見道旁灌木乎？有一特技可斫除之。", -- ViridianForestNorthGate
    ["_Route2GateOaksAideFlashExplanationText"] = "祕傳機閃光，雖幽穴亦能照之。", -- Route2Gate
    ["_Route2GateYoungsterText"] = "㬺獸既習閃光，即可通岩山隧。", -- Route2Gate
    ["_ViridianForestSouthGateGirlText"] = "欲入碧林乎？慎之，其天然如迷宮。", -- ViridianForestSouthGate
    ["_ViridianForestSouthGateLittleGirlText"] = "幼鼠雖小，齧甚厲！子得一乎？", -- ViridianForestSouthGate
    ["_UndergroundPathRoute6GirlText"] = "地隧中常有人失物。", -- UndergroundPathRoute6
    ["_UndergroundPathRoute7MiddleAgedManText"] = "聞青邑附近出現一酣眠之獸。", -- UndergroundPathRoute7
    ["_UndergroundPathRoute7CopyUnusedGirlText"] = "吾欲往青邑百貨肆買物，然彼處粗悍之人太多……", -- UndergroundPathRoute7Copy
    ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "火箭賊在青邑曾有祕巢乎？", -- UndergroundPathRoute7Copy
    ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "子來青邑買物乎？出門向西便是！", -- UndergroundPathRoute7Copy
    ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "地隧行黃邑之下，可通紫村。若往縹邑，至路對面之舍。", -- UndergroundPathRoute7Copy
    ["_SilphCo9FRocket1BattleText"] = "小兒，子獸似甚愛子！", -- SilphCo9F
    ["_SilphCo9FRocket1EndBattleText"] = "啊——！", -- SilphCo9F
    ["_SilphCo9FRocket1AfterBattleText"] = "若吾也自子這年紀始為㬺獸士……", -- SilphCo9F
    ["_SilphCo9FScientistBattleText"] = "子獸皆有弱處，吾可直擊之！", -- SilphCo9F
    ["_SilphCo9FScientistEndBattleText"] = "為子重擊矣！", -- SilphCo9F
    ["_SilphCo9FScientistAfterBattleText"] = "攻其弱處確有效！多思諸屬相剋。", -- SilphCo9F
    ["_SilphCo9FRocket2BattleText"] = "吾乃火箭四兄弟之一！", -- SilphCo9F
    ["_SilphCo9FRocket2EndBattleText"] = "嗚！兄弟們，吾敗矣！", -- SilphCo9F
    ["_SilphCo9FRocket2AfterBattleText"] = "吾兄弟必為我報仇！", -- SilphCo9F
    ["_VictoryRoad1FCooltrainerFBattleText"] = "不知子是否足與我戰！", -- VictoryRoad1F
    ["_VictoryRoad1FCooltrainerFEndBattleText"] = "吾敗矣！", -- VictoryRoad1F
    ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "吾從不願敗於任何人！", -- VictoryRoad1F
    ["_VictoryRoad1FCooltrainerMBattleText"] = "一望便知子善戰。且讓我細觀究竟多善！", -- VictoryRoad1F
    ["_VictoryRoad1FCooltrainerMEndBattleText"] = "本有勝機……", -- VictoryRoad1F
    ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "吾服，子勝我一籌！", -- VictoryRoad1F
    ["_PokemonTower1FReceptionistText"] = "㬺獸塔為追念已死㬺獸而建。", -- PokemonTower1F
    ["_PokemonTower1FMiddleAgedWomanText"] = "子來弔祭乎？善哉！", -- PokemonTower1F
    ["_PokemonTower1FBaldingGuyText"] = "吾來為明魄祈禱。嗚……淚不能止。", -- PokemonTower1F
    ["_PokemonTower1FGirlText"] = "吾之火保犬……何故死矣？", -- PokemonTower1F
    ["_PokemonTower1FChannelerText"] = "吾乃巫祝。此上有邪靈作祟！", -- PokemonTower1F
    ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}：咄，{PLAYER}！何故來此？子獸看來未死。至少吾可使之仆倒！來，與我展！", -- PokemonTower2F
    ["_PokemonTower2FRivalDefeatedText"] = "何！子這惡物！吾還特意留手！", -- PokemonTower2F
    ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}：䀩子諸弱獸！再養強些罷！", -- PokemonTower2F
    ["_PokemonTower2FRivalHowsYourDexText"] = "子㬺獸記機如何？吾方獲一髑髏螭！成年之荷髓螭卻尋不得，恐已絕矣。吾尚有大事要辦，先伆！", -- PokemonTower2F
    ["_PokemonTower2FChannelerText"] = "連吾等亦不能辨諸遊鬼真形。氣仙鬼鏡或可使其現形。", -- PokemonTower2F
    ["_PokemonTower3FChanneler1BattleText"] = "呃……啊……呼呼……嘎……", -- PokemonTower3F
    ["_PokemonTower3FChanneler1EndBattleText"] = "哈！吾得救矣！", -- PokemonTower3F
    ["_PokemonTower3FChanneler1AfterBattleText"] = "用氣仙鬼鏡可辨諸鬼。", -- PokemonTower3F
    ["_PokemonTower3FChanneler2BattleText"] = "咯咯咯……嘎啊！", -- PokemonTower3F
    ["_PokemonTower3FChanneler2EndBattleText"] = "嗯？吾在作何？", -- PokemonTower3F
    ["_PokemonTower3FChanneler2AfterBattleText"] = "抱歉！吾方為鬼所憑！", -- PokemonTower3F
    ["_PokemonTower3FChanneler3BattleText"] = "退去！邪靈！", -- PokemonTower3F
    ["_PokemonTower3FChanneler3EndBattleText"] = "呼！邪靈去矣！", -- PokemonTower3F
    ["_PokemonTower3FChanneler3AfterBattleText"] = "吾友亦皆為鬼所憑！", -- PokemonTower3F
    ["_PokemonTower4FChanneler1BattleText"] = "鬼！不！嘎啊！", -- PokemonTower4F
    ["_PokemonTower4FChanneler1EndBattleText"] = "鬼在何處？", -- PokemonTower4F
    ["_PokemonTower4FChanneler1AfterBattleText"] = "吾必是夢中……", -- PokemonTower4F
    ["_PokemonTower4FChanneler2BattleText"] = "與我同受此咒！嘎啊！", -- PokemonTower4F
    ["_PokemonTower4FChanneler2EndBattleText"] = "何！", -- PokemonTower4F
    ["_PokemonTower4FChanneler2AfterBattleText"] = "吾等仍不能辨鬼之真形。", -- PokemonTower4F
    ["_PokemonTower4FChanneler3BattleText"] = "呼呼呼……毋勝我！", -- PokemonTower4F
    ["_PokemonTower4FChanneler3EndBattleText"] = "何？誰？何事？", -- PokemonTower4F
    ["_PokemonTower4FChanneler3AfterBattleText"] = "願亡獸之魂安息……", -- PokemonTower4F
    ["_PokemonTower5FChanneler1Text"] = "來，童子！吾以淨法封此地，可於此休息。", -- PokemonTower5F
    ["_PokemonTower5FChanneler2BattleText"] = "給……我……子之魂……", -- PokemonTower5F
    ["_PokemonTower5FChanneler2EndBattleText"] = "啊！", -- PokemonTower5F
    ["_PokemonTower5FChanneler2AfterBattleText"] = "吾方為鬼所憑。", -- PokemonTower5F
    ["_PokemonTower5FChanneler3BattleText"] = "子……當……入吾等……", -- PokemonTower5F
    ["_PokemonTower5FChanneler3EndBattleText"] = "何等惡夢！", -- PokemonTower5F
    ["_PokemonTower5FChanneler3AfterBattleText"] = "吾為鬼所憑！", -- PokemonTower5F
    ["_PokemonTower5FChanneler4BattleText"] = "活屍！", -- PokemonTower5F
    ["_PokemonTower5FChanneler4EndBattleText"] = "何？", -- PokemonTower5F
    ["_PokemonTower5FChanneler4AfterBattleText"] = "吾神識復矣！", -- PokemonTower5F
    ["_PokemonTower5FChanneler5BattleText"] = "呃啊……呃……", -- PokemonTower5F
    ["_PokemonTower5FChanneler5EndBattleText"] = "呼！", -- PokemonTower5F
    ["_PokemonTower5FChanneler5AfterBattleText"] = "吾雖修習，仍為邪靈所乘！", -- PokemonTower5F
    ["_PokemonTower5FPurifiedZoneText"] = "入清淨護持之地！\f{PLAYER}諸獸盡復！", -- PokemonTower5F
    ["_PokemonTower6FGhostWasCubonesMotherText"] = "此鬼乃髑髏螭之母不安之魂！", -- PokemonTower6F
    ["_PokemonTower6FSoulWasCalmedText"] = "母魂已安，遂往後世。", -- PokemonTower6F
    ["_PokemonTower6FChanneler1BattleText"] = "給……我……血……", -- PokemonTower6F
    ["_PokemonTower6FChanneler1EndBattleText"] = "呻吟……", -- PokemonTower6F
    ["_PokemonTower6FChanneler1AfterBattleText"] = "吾似血虛而弱……", -- PokemonTower6F
    ["_PokemonTower6FChanneler2BattleText"] = "呃……嘎啊！", -- PokemonTower6F
    ["_PokemonTower6FChanneler2EndBattleText"] = "似有物落出！", -- PokemonTower6F
    ["_PokemonTower6FChanneler2AfterBattleText"] = "非髮落也，乃邪靈出矣！", -- PokemonTower6F
    ["_PokemonTower6FChanneler3BattleText"] = "咯……咯……咯……咯咯咯！", -- PokemonTower6F
    ["_PokemonTower6FChanneler3EndBattleText"] = "咿——！", -- PokemonTower6F
    ["_PokemonTower6FChanneler3AfterBattleText"] = "此處究竟何事？", -- PokemonTower6F
    ["_PokemonTower6FBeGoneText"] = "退去……闖入者……", -- PokemonTower6F
    ["_PokemonTower7FMrFujiRescueText"] = "富士老人：咦？子來救老身乎？多謝。然老身自願來此，為安髑髏螭之母魂。吾想荷髓螭之魂已往後世。子之厚意，老身當謝。隨老身至塔下㬺獸之家。", -- PokemonTower7F
    ["_PokemonTower7FRocket1BattleText"] = "欲何為？來此作甚？", -- PokemonTower7F
    ["_PokemonTower7FRocket1EndBattleText"] = "吾服！", -- PokemonTower7F
    ["_PokemonTower7FRocket1AfterBattleText"] = "此事吾不會忘！", -- PokemonTower7F
    ["_PokemonTower7FRocket2BattleText"] = "此老頭來責吾等傷害無用之獸！吾等只是大人間談談罷了！", -- PokemonTower7F
    ["_PokemonTower7FRocket2EndBattleText"] = "求你！不要再來！", -- PokemonTower7F
    ["_PokemonTower7FRocket2AfterBattleText"] = "㬺獸只可用來賺錢！休管吾等之事！", -- PokemonTower7F
    ["_PokemonTower7FRocket3BattleText"] = "小兒，子救不了任何人！", -- PokemonTower7F
    ["_PokemonTower7FRocket3EndBattleText"] = "休與火箭賊鬥！", -- PokemonTower7F
    ["_PokemonTower7FRocket3AfterBattleText"] = "子休想如此脫身！", -- PokemonTower7F
    ["_CeladonMart1FReceptionistText"] = "歡迎至青邑百貨肆。右側榜書列諸層所售。", -- CeladonMart1F
    ["_CeladonMart1FDirectorySignText"] = "一層：服務櫃 二層：㬺獸士市肆 三層：遊戲機肆 四層：賢者禮品 五層：藥肆 頂樓：自售機", -- CeladonMart1F
    ["_CeladonMart1FCurrentFloorSignText"] = "一層：服務櫃", -- CeladonMart1F
    ["_ViridianForestYoungster1Text"] = "吾與友偕來。彼輩方求鬭獸！", -- ViridianForest
    ["_ViridianForestYoungster2BattleText"] = "咄！子有㬺獸！來，與我鬭！", -- ViridianForest
    ["_ViridianForestYoungster2EndBattleText"] = "不！羶鳳蠋不堪戰！", -- ViridianForest
    ["_ViridianForestYoungster2AfterBattleText"] = "噓！將驚散群蟲！", -- ViridianForest
    ["_ViridianForestYoungster3BattleText"] = "咄！既為㬺獸士，安得避戰！", -- ViridianForest
    ["_ViridianForestYoungster3EndBattleText"] = "咦？吾獸盡矣！", -- ViridianForest
    ["_ViridianForestYoungster3AfterBattleText"] = "可惱！吾將更獲強獸！", -- ViridianForest
    ["_ViridianForestYoungster4BattleText"] = "且住！何急之甚？", -- ViridianForest
    ["_ViridianForestYoungster4EndBattleText"] = "服矣！子善鬭也。", -- ViridianForest
    ["_ViridianForestYoungster4AfterBattleText"] = "地或有遺物。吾方索所失。", -- ViridianForest
    ["_ViridianForestYoungster5Text"] = "獸毬盡矣，無以獲獸！子宜多備。", -- ViridianForest
    ["_ViridianForestTrainerTips1Text"] = "㬺獸士須知\n欲避戰，遠草叢。", -- ViridianForest
    ["_ViridianForestUseAntidoteSignText"] = "中毒，服解毒丸。雜貨肆有售。", -- ViridianForest
    ["_ViridianForestTrainerTips2Text"] = "㬺獸士須知\n以算器通大木博士，可請評㬺獸記機之錄。", -- ViridianForest
    ["_ViridianForestTrainerTips3Text"] = "㬺獸士須知\n不得竊他士之獸；惟野獸可獲。", -- ViridianForest
    ["_ViridianForestTrainerTips4Text"] = "㬺獸士須知\n欲獲獸，先困之；健則或逸。", -- ViridianForest
    ["_ViridianForestLeavingSignText"] = "出碧林 前至灰邑", -- ViridianForest
    ["_SSAnne1FWaiterText"] = "龐茹爾！吾乃此船侍者。客所欲者，吾皆樂為奉上！啊，原來是沉默之強者！", -- SSAnne1F
    ["_SSAnne1FSailorText"] = "乘客皆躁動不安；其中無聊者或來挑戰子！", -- SSAnne1F
    ["_SSAnne2FWaiterText"] = "此船乃供㬺獸士遊宴之華舶。每至一港，皆邀諸士設宴！", -- SSAnne2F
    ["_SSAnne2FRivalText"] = "{RIVAL}：龐茹爾，{PLAYER}！竟於此見子。{PLAYER}，子真受邀乎？㬺獸記機如何？吾已獲卌種。天下處處有異種，草野皆當細䀩！", -- SSAnne2F
    ["_SSAnne2FRivalDefeatedText"] = "哼！至少子還在養獸。", -- SSAnne2F
    ["_SSAnne2FRivalVictoryText"] = "{PLAYER}！子暈船乎？振作些，友！", -- SSAnne2F
    ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}：聞船上有切術名家，原來只是暈船老人！但切本身甚有用。子去見之罷。吾伆矣！", -- SSAnne2F
    ["_SSAnneBowSuperNerdText"] = "宴已罷，船將發矣。", -- SSAnneBow
    ["_SSAnneBowSailor1Text"] = "洗甲板真苦工也！", -- SSAnneBow
    ["_SSAnneBowCooltrainerMText"] = "呃……吾不適，出來受些風。", -- SSAnneBow
    ["_SSAnneBowSailor2BattleText"] = "咄，水手友！且舞一曲般戰！", -- SSAnneBow
    ["_SSAnneBowSailor2EndBattleText"] = "子頗可觀！", -- SSAnneBow
    ["_SSAnneBowSailor2AfterBattleText"] = "子意世間共有幾種㬺獸？", -- SSAnneBow
    ["_SSAnneBowSailor3BattleText"] = "嗬！子暈船乎？", -- SSAnneBow
    ["_SSAnneBowSailor3EndBattleText"] = "吾只是一時疏忽！", -- SSAnneBow
    ["_SSAnneBowSailor3AfterBattleText"] = "吾父言㬺獸有百種；吾看還更多。", -- SSAnneBow
    ["_SSAnneKitchenCook1Text"] = "小客，吾等忙甚！莫擋路！", -- SSAnneKitchen
    ["_SSAnneKitchenCook2Text"] = "吾在垃圾中見一怪毬。", -- SSAnneKitchen
    ["_SSAnneKitchenCook3Text"] = "忙得吾頭暈矣！", -- SSAnneKitchen
    ["_SSAnneKitchenCook4Text"] = "哼哼呵……吾日日削薯！哼哼……", -- SSAnneKitchen
    ["_SSAnneKitchenCook5Text"] = "聞過西俯熊乎？除食與睡外，無所為！", -- SSAnneKitchen
    ["_SSAnneKitchenCook6Text"] = "嗚……吸鼻……吾只得剝葱……嗚……", -- SSAnneKitchen
    ["_SSAnneKitchenCook7MainCourseIsText"] = "咳！誠吾主廚也。\f今之主饌——", -- SSAnneKitchen
    ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "船長：呃啊……難受甚……噦！暈船……\f{PLAYER}為船長摩背。\f摩摩……摩摩……", -- SSAnneCaptainsRoom
    ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "船長：呼！多謝，今好多矣。子欲觀吾切術乎？若非病中，本可示子。這樣罷，此物與子！授獸之後，隨時可見其切！", -- SSAnneCaptainsRoom
    ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- SSAnneCaptainsRoom
    ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "船長：呼！今病已愈，也該啟程矣。", -- SSAnneCaptainsRoom
    ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "嗚呼！子無隙納此！", -- SSAnneCaptainsRoom
    ["_SSAnneCaptainsRoomTrashText"] = "噫！不該看！", -- SSAnneCaptainsRoom
    ["_SSAnneCaptainsRoomSeasickBookText"] = "《克服暈船之法》……船長正在讀此書！", -- SSAnneCaptainsRoom
    ["_SSAnne1FRoomsWigglytuffText"] = "便便兔：噗噗噗！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman1BattleText"] = "吾常獨行天下，㬺獸便是吾唯一之友！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman1EndBattleText"] = "吾之友啊……", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "對友當善！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman2BattleText"] = "小犬！安敢闖入！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman2EndBattleText"] = "哼！無禮童子！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "吾欲獨處！出去！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsYoungsterBattleText"] = "吾愛㬺獸！子亦愛乎？", -- SSAnne1FRooms
    ["_SSAnne1FRoomsYoungsterEndBattleText"] = "哇！子真強！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "與我為友可乎？如此便可互易㬺獸！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsCooltrainerFBattleText"] = "此諸獸皆吾自天下各地收得！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "嗚呼！吾繞天下才得此等！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "子傷吾可憐之天下珍獸！須帶牠們去㬺獸中心療治！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGirl1Text"] = "侍者，請來櫻桃餅一份！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsMiddleAgedManText"] = "乘遊舶既雅又安適！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsLittleGirlText"] = "吾常與便便兔同遊！", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGirl2Text"] = "吾等正在周遊天下。", -- SSAnne1FRooms
    ["_SSAnne1FRoomsGentleman3Text"] = "噓！吾乃全球巡捕之探員，正追查火箭賊！", -- SSAnne1FRooms
    ["_SSAnne2FRoomsGentleman3Text"] = "吾周遊甚廣，從未見獸睡得如此！大約像這般！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman4Text"] = "啊，是的，吾見過有獸載人渡水！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGrampsText"] = "㬺獸能切斷小灌木。", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman5Text"] = "子去過縓邑獲獸帶乎？彼處珍獸甚多！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsLittleBoyText"] = "吾與父皆覺獲獸帶妙極！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsBrunetteGirlText"] = "船長看來病甚，面色蒼白！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsBeautyText"] = "聞海上多有人暈船！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman1BattleText"] = "與少年相競，使吾常保少壯。", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman1EndBattleText"] = "善戰！啊，吾又覺年少矣！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "十五年前，吾必能勝！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsFisherBattleText"] = "且觀吾所釣之物！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsFisherEndBattleText"] = "吾獸盡矣！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsFisherAfterBattleText"] = "宴會乎？此船之宴想必已罷。", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman2BattleText"] = "子喜強獸，抑珍獸？", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman2EndBattleText"] = "吾當敬子！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "吾最愛又強又珍之獸。", -- SSAnne2FRooms
    ["_SSAnne2FRoomsCooltrainerFBattleText"] = "宴中未曾見子。", -- SSAnne2FRooms
    ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "手下留情！", -- SSAnne2FRooms
    ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "啊，吾甚愛子之強獸！", -- SSAnne2FRooms
    ["_SSAnneB1FRoomsMachokeText"] = "功夫力：嗚喔！咕咕！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor1BattleText"] = "水手與鬥架，子當聞過其說！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor1EndBattleText"] = "善！好戰，友！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "哈哈！友，欲作水手乎？", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor2BattleText"] = "吾水手之名，繫於此戰！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor2EndBattleText"] = "子之氣勢沉我矣！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "見過朱邑釣魚師乎？", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor3BattleText"] = "吾等水手亦有㬺獸！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor3EndBattleText"] = "善，子尚不差。", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "吾等之獸皆出海時所獲！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor4BattleText"] = "吾喜子這等有氣之童子！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor4EndBattleText"] = "啊！失手矣！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "海獸居深水，須用釣竿方得。", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor5BattleText"] = "友，若敗便走板落海！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor5EndBattleText"] = "啊！竟敗於童子！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "水母有時會漂入船中。", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsFisherBattleText"] = "客從何來？且住談談！吾諸獸皆出於海！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsFisherEndBattleText"] = "可惱！又使一條溜走！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsFisherAfterBattleText"] = "吾本還想收子作助手！", -- SSAnneB1FRooms
    ["_SSAnneB1FRoomsSuperNerdText"] = "吾友功夫力強甚！其怪力足以移巨石！", -- SSAnneB1FRooms
    ["_SilphCo11FSilphPresidentText"] = "總辦：多謝子救氣仙公司！危急之時子救吾等，吾永不忘。吾須有所報。吾有財，可贈子幾乎任何物。此物或合適！", -- SilphCo11F
    ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- SilphCo11F
    ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "總辦：此物市上無售，乃吾司祕製試作聖毬！任何㬺獸皆可必中獲之。只是使用時宜低調些。", -- SilphCo11F
    ["_SilphCo11FSilphPresidentNoRoomText"] = "子無隙納此。", -- SilphCo11F
    ["_SilphCo11FBeautyText"] = "祕書：多謝子救吾等！吾等甚敬子之勇。", -- SilphCo11F
    ["_SilphCo11FGiovanniText"] = "榊岸邊：啊，{PLAYER}！又相見矣。吾與總辦正議一重大商事。大人之事，小兒休管……否則當知痛苦之世！", -- SilphCo11F
    ["_SilphCo10FGiovanniILostAgainText"] = "啊！又敗乎！", -- SilphCo11F
    ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "可惱！子壞吾等取氣仙公司之計！然火箭賊永不亡。{PLAYER}，須知天下㬺獸皆為火箭賊而有！吾今且去，終當復來！", -- SilphCo11F
    ["_SilphCo11FRocket1BattleText"] = "止！一步也毋動！", -- SilphCo11F
    ["_SilphCo11FRocket1EndBattleText"] = "不要……求你！", -- SilphCo11F
    ["_SilphCo11FRocket1AfterBattleText"] = "如此看來，子欲見吾首領？", -- SilphCo11F
    ["_SilphCo11FRocket2BattleText"] = "止！子與首領有約乎？", -- SilphCo11F
    ["_SilphCo11FRocket2EndBattleText"] = "嗚呼！崩矣！", -- SilphCo11F
    ["_SilphCo11FRocket2AfterBattleText"] = "步步小心，吾首領最愛強獸！", -- SilphCo11F
    ["_SilphCo10FPorygonText"] = "畫面上有㬺獸！", -- SilphCo11F
    ["_ViridianGymGiovanniPreBattleText"] = "榊岸邊：哇哈哈！此乃吾之祕巢。本欲在此復興火箭賊，竟又為子撞見。也罷！此次吾不留力。再與最強㬺獸士榊岸邊一戰！", -- ViridianGym
    ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "哈！此戰真烈。子勝矣！以此綠徽為證！", -- ViridianGym
    ["_ViridianGymGiovanniPostBattleAdviceText"] = "既敗於子，吾無顏見部下。火箭賊自此永絕！吾將餘生專究㬺獸。他日或再相見。別矣！", -- ViridianGym
    ["_ViridianGymGiovanniEarthBadgeInfoText"] = "綠徽使一切級數之獸皆聽命，是子馭獸之能已成之證。有此乃可入㬺獸聯會。以贈子作聯會挑戰之餞！", -- ViridianGym
    ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER}得技機廾七！", -- ViridianGym
    ["_ViridianGymGiovanniTM27ExplanationText"] = "技機廾七載地裂，一擊即可倒敵。此技乃吾昔掌此書院時所作，已久矣……", -- ViridianGym
    ["_ViridianGymGiovanniTM27NoRoomText"] = "子無隙納此。", -- ViridianGym
    ["_ViridianGymCooltrainerM1BattleText"] = "嘿！子氣力也該快盡了！", -- ViridianGym
    ["_ViridianGymCooltrainerM1EndBattleText"] = "吾先力盡矣！", -- ViridianGym
    ["_ViridianGymCooltrainerM1AfterBattleText"] = "欲追隨吾山長，須有足夠之力！", -- ViridianGym
    ["_ViridianGymHiker1BattleText"] = "吼！吾正激己成怒！", -- ViridianGym
    ["_ViridianGymHiker1EndBattleText"] = "哇啊！", -- ViridianGym
    ["_ViridianGymHiker1AfterBattleText"] = "吾仍不配！", -- ViridianGym
    ["_ViridianGymRocker1BattleText"] = "吾與獸合奏，妙不可言！", -- ViridianGym
    ["_ViridianGymRocker1EndBattleText"] = "子我之聲竟和諧至此！", -- ViridianGym
    ["_ViridianGymRocker1AfterBattleText"] = "子知吾山長真身乎？", -- ViridianGym
    ["_ViridianGymHiker2BattleText"] = "空手之道，乃武藝之極！", -- ViridianGym
    ["_ViridianGymHiker2EndBattleText"] = "嚔！", -- ViridianGym
    ["_ViridianGymHiker2AfterBattleText"] = "若吾獸空手之技亦如我……", -- ViridianGym
    ["_ViridianGymCooltrainerM2BattleText"] = "真正有才者，勝亦有風！", -- ViridianGym
    ["_ViridianGymCooltrainerM2EndBattleText"] = "吾失其掌握矣！", -- ViridianGym
    ["_ViridianGymCooltrainerM2AfterBattleText"] = "山長必責我！", -- ViridianGym
    ["_ViridianGymHiker3BattleText"] = "吾乃空手王！子命繫於吾手！", -- ViridianGym
    ["_ViridianGymHiker3EndBattleText"] = "哎呀！", -- ViridianGym
    ["_ViridianGymHiker3AfterBattleText"] = "㬺獸聯會？就憑子？休驕！", -- ViridianGym
    ["_ViridianGymRocker2BattleText"] = "吾鞭一響，子獸必伏地戰慄！", -- ViridianGym
    ["_ViridianGymRocker2EndBattleText"] = "痛！鞭反傷我！", -- ViridianGym
    ["_ViridianGymRocker2AfterBattleText"] = "且住！吾只是疏忽！", -- ViridianGym
    ["_ViridianGymCooltrainerM3BattleText"] = "碧邑書院閉門甚久，今山長終於復來！", -- ViridianGym
    ["_ViridianGymCooltrainerM3EndBattleText"] = "敗矣乎？", -- ViridianGym
    ["_ViridianGymCooltrainerM3AfterBattleText"] = "欲往㬺獸聯會，須先勝吾山長！", -- ViridianGym
    ["_ViridianGymGuidePreBattleText"] = "咄，將為魁者！連吾也不知碧邑山長真身。此必是八院中最難一戰。聞此中諸士多用土屬獸！", -- ViridianGym
    ["_ViridianGymGuidePostBattleText"] = "嚇煞我！榊岸邊竟是此院山長？", -- ViridianGym
    ["_PewterMartYoungsterText"] = "一可疑老翁哄吾買此怪魚獸！弱甚，竟費五百円！", -- PewterMart
    ["_PewterMartSuperNerdText"] = "縱弱獸，勤養之亦或有佳報。", -- PewterMart
    ["_CeruleanBadgeHouseMiddleAgedManText"] = "㬺獸徽章惟善戰之士得有。吾見子至少已有一枚。諸徽皆藏妙用！", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "那麼……八徽中，欲聽吾說何徽？", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "欲來便來。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseBoulderBadgeText"] = "灰徽使諸獸之力略增，亦使子隨時可用閃光。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseCascadeBadgeText"] = "青徽使三十級以下之獸聽命，過此則或不馴；亦可在戰外用切。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseThunderBadgeText"] = "橙徽使諸獸之速略增，亦可在戰外用飛。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseRainbowBadgeText"] = "虹徽使五十級以下之獸聽命，過此則或不馴；亦可在戰外用怪力。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseSoulBadgeText"] = "縓徽使諸獸之守略增，亦可在戰外用乘浪。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseMarshBadgeText"] = "金徽使七十級以下之獸聽命，過此則或不馴。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseVolcanoBadgeText"] = "絳徽使獸之異能略增。", -- CeruleanBadgeHouse
    ["_CeruleanBadgeHouseEarthBadgeText"] = "綠徽使一切㬺獸皆聽命！", -- CeruleanBadgeHouse
    ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "獲獸帶守人雖老，仍甚健旺；但滿口皆是假齒。", -- FuchsiaBillsGrandpasHouse
    ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "咦？子見過正輝乎？彼乃吾孫！自幼便愛收集萬物。", -- FuchsiaBillsGrandpasHouse
    ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "正輝把自己之㬺獸資料存於算器。彼曾示子乎？", -- FuchsiaBillsGrandpasHouse
    ["_FuchsiaPokecenterRockerText"] = "只靠一隻強獸不能勝，雖苦，仍須使諸獸均養。", -- FuchsiaPokecenter
    ["_FuchsiaPokecenterCooltrainerFText"] = "碧邑西有一狹路，可通㬺獸聯會本部；本部統攝諸㬺獸士。", -- FuchsiaPokecenter
    ["_WardensHouseWardenGibberish1Text"] = "守人：嘰咕嘿呼！哈嚕哈呼咿哈……嘿呼呼！", -- WardensHouse
    ["_WardensHouseWardenGibberish2Text"] = "啊嚯嘿呼呼！咿咿哈呼！", -- WardensHouse
    ["_WardensHouseWardenGibberish3Text"] = "哈？嘿哦呀嘿哈呼咿哈嘿！", -- WardensHouse
    ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER}把金齒交與守人！", -- WardensHouse
    ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "守人把金齒裝入口中！", -- WardensHouse
    ["_WardensHouseWardenThanksText"] = "守人：多謝，小友！方纔無人聽得懂吾說什麼，這樣怎能做事？此物權當謝禮。", -- WardensHouse
    ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- WardensHouse
    ["_WardensHouseWardenHM04ExplanationText"] = "守人：祕傳機四載怪力，可使獸在戰外移巨石。對了，子找到獲獸帶之祕屋乎？到彼處可得一祕傳機，聞乃罕見之乘浪。", -- WardensHouse
    ["_WardensHouseWardenHM04NoRoomText"] = "行囊已塞滿！", -- WardensHouse
    ["_WardensHouseDisplayPhotosAndFossilsText"] = "㬺獸照片及僵石。", -- WardensHouse
    ["_WardensHouseDisplayMerchandiseText"] = "舊㬺獸商品。", -- WardensHouse
    ["_SafariZoneGateSafariZoneWorker1Text"] = "歡迎至獲獸帶！", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "只需五百円，園中㬺獸任子獲取。欲入獲獸之戲乎？", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "請付五百円。\f此處只用特製獸毬。\f{PLAYER}得卅枚獲獸毬！", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "時辰或獲獸毬盡時，吾等會以擴音器召子。", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "善！他日再來！", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "噫！錢不足。", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "欲提早離開乎？", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "請交還所餘獲獸毬。", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "祝子得獸！", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "收穫如何？他日再來！", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "安！初來此乎？", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "獲獸帶分四區，各有不同㬺獸。以獲獸毬獲之。時辰或毬盡，即戲終。入園前宜先啟一未用獸匣，以容新獸。", -- SafariZoneGate
    ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "哦，原來是常客！", -- SafariZoneGate
    ["_FuchsiaGymKogaBeforeBattleText"] = "桔杏：哇哈哈！區區童子也敢挑戰吾？也罷，讓子見忍師真正可怖之處！毒與睡之術，必使子知絕望！", -- FuchsiaGym
    ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "哼！子已證明其能。縓徽取去！", -- FuchsiaGym
    ["_FuchsiaGymKogaPostBattleAdviceText"] = "中劇毒者，戰愈久其苦愈增，必令敵懼！", -- FuchsiaGym
    ["_FuchsiaGymKogaSoulBadgeInfoText"] = "有縓徽後，獸之守更強，且可在戰外乘浪。啊，此物亦取去！", -- FuchsiaGym
    ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- FuchsiaGym
    ["_FuchsiaGymKogaTM06ExplanationText"] = "技機六載劇毒，乃傳四百餘年之祕術！", -- FuchsiaGym
    ["_FuchsiaGymKogaTM06NoRoomText"] = "童子，先空行囊！", -- FuchsiaGym
    ["_FuchsiaGymRocker1BattleText"] = "勝獸不專恃力，關鍵在謀！吾示子以謀勝蠻力。", -- FuchsiaGym
    ["_FuchsiaGymRocker1EndBattleText"] = "何！奇哉！", -- FuchsiaGym
    ["_FuchsiaGymRocker1AfterBattleText"] = "原來子力與智並用。好謀也！", -- FuchsiaGym
    ["_FuchsiaGymRocker2BattleText"] = "吾欲為忍者，故入此院！", -- FuchsiaGym
    ["_FuchsiaGymRocker2EndBattleText"] = "吾完矣！", -- FuchsiaGym
    ["_FuchsiaGymRocker2AfterBattleText"] = "吾當繼續從忍師桔杏修習！", -- FuchsiaGym
    ["_FuchsiaGymRocker3BattleText"] = "且看子能否破吾祕術！", -- FuchsiaGym
    ["_FuchsiaGymRocker3EndBattleText"] = "竟為子所欺！", -- FuchsiaGym
    ["_FuchsiaGymRocker3AfterBattleText"] = "吾愛毒與睡之術，戰後其患猶可留！", -- FuchsiaGym
    ["_FuchsiaGymRocker4BattleText"] = "止！此院無形之壁，使子煩乎？", -- FuchsiaGym
    ["_FuchsiaGymRocker4EndBattleText"] = "哇！彼看破矣！", -- FuchsiaGym
    ["_FuchsiaGymRocker4AfterBattleText"] = "子使吾佩服。提示：仔細看無形壁間之隙！", -- FuchsiaGym
    ["_FuchsiaGymRocker5BattleText"] = "吾亦從桔杏師習忍道。忍者用獸之史久矣！", -- FuchsiaGym
    ["_FuchsiaGymRocker5EndBattleText"] = "嗚——！", -- FuchsiaGym
    ["_FuchsiaGymRocker5AfterBattleText"] = "吾尚有多學！", -- FuchsiaGym
    ["_FuchsiaGymRocker6BattleText"] = "桔杏師出忍者世家。子又出何門？", -- FuchsiaGym
    ["_FuchsiaGymRocker6EndBattleText"] = "吾之毬落矣！", -- FuchsiaGym
    ["_FuchsiaGymRocker6AfterBattleText"] = "有光必有影。光與影，子擇何者？", -- FuchsiaGym
    ["_FuchsiaGymGymGuideChampInMakingText"] = "咄，將為魁者！縓邑書院遍布無形壁。桔杏似近，其實隔斷；須尋壁隙方能到彼！", -- FuchsiaGym
    ["_FuchsiaGymGymGuideBeatKogaText"] = "忍者至今仍能令人畏，真奇也！", -- FuchsiaGym
    ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "吾等號守人為「鈍饕餮」，彼與鈍饕餮同樣神情空空！", -- FuchsiaMeetingRoom
    ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "「鈍饕餮」其實極知㬺獸，甚至藏有珍稀絕種獸之僵石！", -- FuchsiaMeetingRoom
    ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "鈍饕餮方纔來過，然吾完全聽不懂。想必言語有病！", -- FuchsiaMeetingRoom
    ["_CinnabarGymBlainePreBattleText"] = "桂夏：哈！吾乃桂夏，丹州書院山長！吾火獸必焚盡來挑戰者。哈！子最好備獨聖散！", -- CinnabarGym
    ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "吾火已熄！絳徽歸子！", -- CinnabarGym
    ["_CinnabarGymBlainePostBattleAdviceText"] = "炎大文乃火技之極！毋浪費於水屬獸！", -- CinnabarGym
    ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "哈！絳徽增獸之異能。此物亦與子！", -- CinnabarGym
    ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CinnabarGym
    ["_CinnabarGymBlaineTM38ExplanationText"] = "技機卅八載炎大文！宜授火屬獸；炎角螭或火速駒皆佳！", -- CinnabarGym
    ["_CinnabarGymBlaineTM38NoRoomText"] = "先空行囊納吾所贈！", -- CinnabarGym
    ["_CinnabarGymSuperNerd1BattleText"] = "知乎㬺獸吐火可熱至何度？", -- CinnabarGym
    ["_CinnabarGymSuperNerd1EndBattleText"] = "痛！熱熱熱！", -- CinnabarGym
    ["_CinnabarGymSuperNerd1AfterBattleText"] = "火，精確言之即燃燒……云云云云……", -- CinnabarGym
    ["_CinnabarGymSuperNerd2BattleText"] = "吾昔為盜，後改過而作㬺獸士！", -- CinnabarGym
    ["_CinnabarGymSuperNerd2EndBattleText"] = "吾降矣！", -- CinnabarGym
    ["_CinnabarGymSuperNerd2AfterBattleText"] = "然而吾仍忍不住偷他人㬺獸！", -- CinnabarGym
    ["_CinnabarGymSuperNerd3BattleText"] = "子不能勝！吾已把㬺獸研究透徹！", -- CinnabarGym
    ["_CinnabarGymSuperNerd3EndBattleText"] = "哇！吾之學問！", -- CinnabarGym
    ["_CinnabarGymSuperNerd3AfterBattleText"] = "吾之理論太繁，子不能懂！", -- CinnabarGym
    ["_CinnabarGymSuperNerd4BattleText"] = "吾就是愛用火獸！", -- CinnabarGym
    ["_CinnabarGymSuperNerd4EndBattleText"] = "熱得難當！", -- CinnabarGym
    ["_CinnabarGymSuperNerd4AfterBattleText"] = "若有專偷竊之㬺獸便好，吾必用之！", -- CinnabarGym
    ["_CinnabarGymSuperNerd5BattleText"] = "吾知桂夏何以成㬺獸士！", -- CinnabarGym
    ["_CinnabarGymSuperNerd5EndBattleText"] = "痛！", -- CinnabarGym
    ["_CinnabarGymSuperNerd5AfterBattleText"] = "桂夏昔迷於山中，有一火鳥現；其光照路，使桂夏得以下山。", -- CinnabarGym
    ["_CinnabarGymSuperNerd6BattleText"] = "吾去過許多書院，此院最合吾意！", -- CinnabarGym
    ["_CinnabarGymSuperNerd6EndBattleText"] = "呀！太熱！", -- CinnabarGym
    ["_CinnabarGymSuperNerd6AfterBattleText"] = "吾等火獸好者皆愛火速駒與九呪狐！", -- CinnabarGym
    ["_CinnabarGymSuperNerd7BattleText"] = "火畏水！", -- CinnabarGym
    ["_CinnabarGymSuperNerd7EndBattleText"] = "啊！熄矣！", -- CinnabarGym
    ["_CinnabarGymSuperNerd7AfterBattleText"] = "水勝火，然火能融冰屬獸！", -- CinnabarGym
    ["_CinnabarGymGymGuideChampInMakingText"] = "咄，將為魁者！性烈之桂夏精於火獸。以水滅其氣焰，並多備獨聖散！", -- CinnabarGym
    ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}！子勝此火性之人矣！", -- CinnabarGym
    ["_CinnabarLabFishingGuruText"] = "吾等於此廣究㬺獸。人常攜珍獸來供檢驗。", -- CinnabarLab
    ["_CinnabarLabPhotoText"] = "丹驗室創辦者富士博士之像。", -- CinnabarLab
    ["_CinnabarLabMeetingRoomSignText"] = "丹驗室\n會議室", -- CinnabarLab
    ["_CinnabarLabRAndDSignText"] = "丹驗室\n研究開發室", -- CinnabarLab
    ["_CinnabarLabTestingRoomSignText"] = "丹驗室\n試驗室", -- CinnabarLab
    ["_CinnabarLabTradeRoomSuperNerdText"] = "吾於月山得一甚怪僵石，似為珍稀上古㬺獸！", -- CinnabarLabTradeRoom
    ["_CinnabarLabMetronomeRoomScientist1Text"] = "嘖嘖嘖！吾造一妙技機，能生百般樂事！", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER}得{RAM:wStringBuffer}！", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "嘖嘖嘖！此乃節拍器之聲。技機可使獸腦受動，施出本不知之技！", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "行囊塞滿矣！", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabMetronomeRoomScientist2Text"] = "易獸可易為三種㬺獸之一。", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabMetronomeRoomPCText"] = "有一電郵！\f……\f三傳說鳥獸為深雱鸞、轟鸑鷟、兵燹鳳。\f所在不明。吾等將探縹邑附近之大穴。\f㬺獸研究隊寄……", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabMetronomeRoomAmberPipeText"] = "琥珀煙管一支！", -- CinnabarLabMetronomeRoom
    ["_CinnabarLabFossilRoomScientist1Text"] = "嘿！吾是重要博士！專究珍稀㬺獸僵石。子有僵石給吾乎？", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "無乎？太可惜！", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "須少許時。子先出去走走！", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "子去了何處？僵石已復生！果然是{RAM:wStringBuffer}，正如吾所想！", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "哦！此乃{RAM:wNameBuffer}！是已絕種㬺獸{RAM:wStringBuffer}之僵石。吾復生機可使此獸再活！", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "善！速把它給吾！\f{PLAYER}交出{RAM:wNameBuffer}！", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "須少許時。子先出去走走！", -- CinnabarLabFossilRoom
    ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "哎呀！子又來矣！", -- CinnabarLabFossilRoom
    ["_CinnabarPokecenterCooltrainerFText"] = "㬺獸易形可以中止；方易時即可使之停下，保持原形。", -- CinnabarPokecenter
    ["_CinnabarPokecenterGentlemanText"] = "子有友乎？互易所得之獸成長甚快，值得一試！", -- CinnabarPokecenter
    ["_CinnabarMartSilphWorkerFText"] = "此處不售增力丸乎？戰中甚好用！", -- CinnabarMart
    ["_CinnabarMartScientistText"] = "多備些物品總無害！", -- CinnabarMart
    ["_CopycatsHouse1FMiddleAgedWomanText"] = "吾女太以己為中心，友人寥寥。", -- CopycatsHouse1F
    ["_CopycatsHouse1FMiddleAgedManText"] = "吾女好仿人；因仿得太像，附近皆號之「仿娘」。", -- CopycatsHouse1F
    ["_CopycatsHouse1FChanseyText"] = "卵生保：鏘——！嘶！", -- CopycatsHouse1F
    ["_ChampionsRoomRivalIntroText"] = "{RIVAL}：咄，{PLAYER}！吾正候子。吾之敵手須強，方能磨我。編錄㬺獸記機之時，吾遍地尋強獸，且組成可勝諸屬之隊。如今吾已為㬺獸聯會之魁！{PLAYER}，知其義乎？吾告子：吾乃天下最強㬺獸士！", -- ChampionsRoom
    ["_RivalDefeatedText"] = "不！豈有此理！子竟勝吾最強之隊！吾辛苦成魁，竟頃刻失位？不公！", -- ChampionsRoom
    ["_RivalVictoryText"] = "哈哈哈！吾勝矣！{PLAYER}，子豈及我！能到此見㬺獸奇才{RIVAL}，已算不錯。敗將，勉之！哈哈！", -- ChampionsRoom
    ["_ChampionsRoomRivalAfterBattleText"] = "何故？吾何以敗？養獸之事，吾從未失誤……可惱！子今是新聯會之魁。雖吾不願認。", -- ChampionsRoom
    ["_ChampionsRoomOakText"] = "大木：{PLAYER}！", -- ChampionsRoom
    ["_ChampionsRoomOakCongratulatesPlayerText"] = "大木：子勝矣！賀子成為新㬺獸聯會之魁！自初攜{RAM:wNameBuffer}離家以來，子長進甚多。{PLAYER}，今真成人矣！", -- ChampionsRoom
    ["_ChampionsRoomOakDisappointedWithRivalText"] = "大木：{RIVAL}！吾甚失望。聞子勝四天王，吾便趕來；及至，子已敗。{RIVAL}，知何以敗乎？子忘了以信與愛待㬺獸。無此二者，終不能復為魁！", -- ChampionsRoom
    ["_ChampionsRoomOakComeWithMeText"] = "大木：{PLAYER}！子須知此勝非獨己力。子與㬺獸相結之情，誠可嘉。{PLAYER}，隨吾來！", -- ChampionsRoom
    ["_LoreleisRoomLoreleiBeforeBattleText"] = "蕉美雪：歡迎至㬺獸聯會！吾乃四天王蕉美雪。論冰獸，無人勝吾！凍技威甚；獸一旦冰封，便任吾處置。哈哈！備好了乎？", -- LoreleisRoom
    ["_LoreleisRoomLoreleiEndBattleText"] = "安敢如此！", -- LoreleisRoom
    ["_LoreleisRoomLoreleiAfterBattleText"] = "子比吾所料更強！往前罷。子方纔只嚐到聯會之力一角！", -- LoreleisRoom
    ["_LoreleisRoomLoreleiDontRunAwayText"] = "有聲曰：毋逃！", -- LoreleisRoom
    ["_BrunoBeforeBattleText"] = "岩崎芝：吾乃四天王岩崎芝！人與獸經苦練皆可益強。吾與獸一同鍛體。{PLAYER}！吾等將以勝力碾子！喝哈！", -- BrunosRoom
    ["_BrunoEndBattleText"] = "何故？吾何以敗？", -- BrunosRoom
    ["_BrunoAfterBattleText"] = "吾事已畢。往迎下一戰！", -- BrunosRoom
    ["_BrunosRoomBrunoDontRunAwayText"] = "有聲曰：毋逃！", -- BrunosRoom
    ["_AgathaBeforeBattleText"] = "菊子：吾乃四天王菊子！大木那老頭很留意子。彼昔日也強而俊，然那是數十年前！如今只知玩弄㬺獸記機。彼錯矣，㬺獸本為鬥戰！{PLAYER}，且看真正㬺獸士如何戰！", -- AgathasRoom
    ["_AgathaEndBattleText"] = "哦呵！童子，子果非凡！", -- AgathasRoom
    ["_AgathaAfterBattleText"] = "子勝矣！如今吾也知那老頭為何看重子。再無話說，童子，去罷！", -- AgathasRoom
    ["_AgathasRoomAgathaDontRunAwayText"] = "有聲曰：毋逃！", -- AgathasRoom
    ["_CardKeySuccessText1"] = "中矣！", -- Draft
    ["_CardKeySuccessText2"] = "管鑰票啟門矣！", -- Draft
    ["_CardKeyFailText"] = "可惱！須管鑰票！", -- Draft
    ["_TrainerNameText"] = "{RAM:wNameBuffer}：", -- Draft
    ["_NoNibbleText"] = "無一咬鉤！", -- Draft
    ["_NothingHereText"] = "此處似無物。", -- Draft
    ["_ItsABiteText"] = "噫！咬鉤矣！", -- Draft
    ["_ExclamationText"] = "！", -- Draft
    ["_GroundRoseText"] = "某處地升矣！", -- Draft
    ["_BoulderText"] = "此石須用怪力乃可移！", -- Draft
    ["_MartSignText"] = "百物俱備\n雜貨肆", -- Draft
    ["_PokeCenterSignText"] = "療㬺獸\n㬺獸中心", -- Draft
    ["_FoundItemText"] = "{PLAYER}得{RAM:wStringBuffer}！", -- Draft
    ["_NoMoreRoomForItemText"] = "行囊已滿，無所容物！", -- Draft
    ["_OaksAideHiText"] = "嗟！尚識我否？吾大木博士之佐也。若所獲㬺獸滿{NUM:hOaksAideRequirement, 1, 3}種，博士命我授子{RAM:wOaksAideRewardItemName}。{PLAYER}，今已滿{NUM:hOaksAideRequirement, 1, 3}種乎？", -- Draft
    ["_OaksAideUhOhText"] = "且驗之……噫！所獲僅{NUM:hOaksAideNumMonsOwned, 1, 3}種。欲得{RAM:wOaksAideRewardItemName}，須滿{NUM:hOaksAideRequirement, 1, 3}種。", -- Draft
    ["_OaksAideComeBackText"] = "然。俟獲滿{NUM:hOaksAideRequirement, 1, 3}種，復來取{RAM:wOaksAideRewardItemName}。", -- Draft
    ["_OaksAideHereYouGoText"] = "善！已獲{NUM:hOaksAideNumMonsOwned, 1, 3}種矣。賀哉！持此。", -- Draft
    ["_OaksAideGotItemText"] = "{PLAYER}得{RAM:wOaksAideRewardItemName}！", -- Draft
    ["_OaksAideNoRoomText"] = "噫，行囊無地可容{RAM:wOaksAideRewardItemName}。", -- Draft
    ["_AIBattleWithdrawText"] = "{RAM:wTrainerName}收回{RAM:wEnemyMonNick}！", -- Draft
    ["_TradeWentToText"] = "{RAM:wStringBuffer}往{RAM:wLinkEnemyTrainerName}所。", -- Draft
    ["_TradeForText"] = "以{PLAYER}之{RAM:wStringBuffer}，", -- Draft
    ["_TradeSendsText"] = "{RAM:wLinkEnemyTrainerName}送{RAM:wNameBuffer}來。", -- Draft
    ["_TradeWavesFarewellText"] = "{RAM:wLinkEnemyTrainerName}揮手送別，", -- Draft
    ["_TradeTransferredText"] = "{RAM:wNameBuffer}乃傳送來。", -- Draft
    ["_TradeTakeCareText"] = "善養{RAM:wNameBuffer}。", -- Draft
    ["_TradeWillTradeText"] = "{RAM:wLinkEnemyTrainerName}欲以{RAM:wNameBuffer}", -- Draft
    ["_TradeforText"] = "易{PLAYER}之{RAM:wStringBuffer}。", -- Draft
    ["_PlaySlotMachineText"] = "博機也。欲一試乎？", -- Draft
    ["_OutOfCoinsSlotMachineText"] = "可惱！籌盡矣！", -- Draft
    ["_BetHowManySlotMachineText"] = "下注幾籌？", -- Draft
    ["_StartSlotMachineText"] = "始！", -- Draft
    ["_NotEnoughCoinsSlotMachineText"] = "籌不足！", -- Draft
    ["_OneMoreGoSlotMachineText"] = "更一局乎？", -- Draft
    ["_LinedUpText"] = "成列！得{RAM:wStringBuffer}籌！", -- Draft
    ["_NotThisTimeText"] = "此番未中！", -- Draft
    ["_YeahText"] = "善！", -- Draft
    ["_DexSeenOwnedText"] = "㬺獸記機 見：{NUM:wDexRatingNumMonsSeen, 1, 3} 獲：{NUM:wDexRatingNumMonsOwned, 1, 3}", -- Draft
    ["_DexRatingText"] = "㬺獸記機評{COLON}", -- Draft
    ["_GymStatueText1"] = "{RAM:wGymCityName}㬺獸書院 山長：{RAM:wGymLeaderName} 勝者：{RIVAL}", -- Draft
    ["_GymStatueText2"] = "{RAM:wGymCityName}㬺獸書院 山長：{RAM:wGymLeaderName} 勝者：{RIVAL} {PLAYER}", -- Draft
    ["_ViridianCityPokecenterGuyText"] = "㬺獸中心可療疲、傷、仆倒之獸！", -- Draft
    ["_PewterCityPokecenterGuyText"] = "呵欠……謳毬毚一謳，㬺獸即昏昏欲寐……我亦然……呼……", -- Draft
    ["_CeruleanPokecenterGuyText"] = "正輝畜獸甚多，亦聚珍稀者！", -- Draft
    ["_LavenderPokecenterGuyText"] = "髑髏螭皆戴髑髏，然乎？此可鬻重價！", -- Draft
    ["_MtMoonPokecenterBenchGuyText"] = "獸多則宜藏於算器。", -- Draft
    ["_RockTunnelPokecenterGuyText"] = "聞紫村有鬼為祟！", -- Draft
    ["_UnusedBenchGuyText1"] = "願我亦能獲獸。", -- Draft
    ["_UnusedBenchGuyText2"] = "遊樂既久，倦矣……", -- Draft
    ["_UnusedBenchGuyText3"] = "氣仙公司主事匿於獲獸帶。", -- Draft
    ["_VermilionPokecenterGuyText"] = "獸級愈高，力固愈強；然各屬互有勝負。故無一獸能遍勝諸屬。", -- Draft
    ["_CeladonCityPokecenterGuyText"] = "吾若有自轉車，必往自轉車道！", -- Draft
    ["_FuchsiaCityPokecenterGuyText"] = "研究㬺獸者，宜往獲獸帶；其中珍稀之獸甚眾。", -- Draft
    ["_CinnabarPokecenterGuyText"] = "止其易，猶可學新技；待技成而後易可也。", -- Draft
    ["_SaffronCityPokecenterGuyText1"] = "若四天王來盡破火箭賊，豈不快哉！", -- Draft
    ["_SaffronCityPokecenterGuyText2"] = "火箭賊遁矣！今可安然出行，善哉！", -- Draft
    ["_CeladonCityHotelText"] = "姊攜我來遊。", -- Draft
    ["_BookcaseText"] = "架上㬺獸書充牣。", -- Draft
    ["_NewBicycleText"] = "新製自轉車也！", -- Draft
    ["_PushStartText"] = "按始鍵以啟目錄！", -- Draft
    ["_SaveOptionText"] = "記項在目錄中。", -- Draft
    ["_StrengthsAndWeaknessesText"] = "諸屬相制，各有強弱。", -- Draft
    ["_TimesUpText"] = "傳聲：鐺鐺！時盡矣！", -- Draft
    ["_GameOverText"] = "傳聲：獲獸戲畢矣！", -- Draft
    ["_CinnabarGymQuizIntroText"] = "㬺獸問答！答是則門啟，得入次室；答非則與士戰。欲留獸力以當山長，務答是。問矣！", -- Draft
    ["_CinnabarQuizQuestionsText1"] = "羶鳳蠋易為蠱翱蝶乎？", -- Draft
    ["_CinnabarQuizQuestionsText2"] = "㬺獸聯會所認徽章有九乎？", -- Draft
    ["_CinnabarQuizQuestionsText3"] = "蚊香蝌蚪凡易三次乎？", -- Draft
    ["_CinnabarQuizQuestionsText4"] = "雷技攻地屬獸，有效乎？", -- Draft
    ["_CinnabarQuizQuestionsText5"] = "同種同級之獸，皆一乎？", -- Draft
    ["_CinnabarQuizQuestionsText6"] = "技機廾八載墓碑擊乎？", -- Draft
    ["_CinnabarGymQuizCorrectText"] = "全然是也！可進！", -- Draft
    ["_CinnabarGymQuizIncorrectText"] = "惜哉！答非矣！", -- Draft
    ["_MagazinesText"] = "㬺獸雜誌！㬺獸筆記！㬺獸圖表！", -- Draft
    ["_BillsHouseMonitorText"] = "算器屏上示瞬移機。", -- Draft
    ["_BillsHouseInitiatedText"] = "{PLAYER}啟瞬移機之細胞分離器！", -- Draft
    ["_BillsHousePokemonListText1"] = "正輝所愛㬺獸之錄！", -- Draft
    ["_BillsHousePokemonListText2"] = "欲觀何獸？", -- Draft
    ["_OakLabEmailText"] = "算器中有電郵一封！\f……\f告諸㬺獸士：㬺獸聯會精銳已候諸君來戰。攜最強之獸，試觀技藝高下！\f㬺獸聯會本部\n石英原\f附：大木博士，請來一訪。……", -- Draft
    ["_GameCornerCoinCaseText"] = "須籌匣！", -- Draft
    ["_GameCornerNoCoinsText"] = "子無籌！", -- Draft
    ["_GameCornerOutOfOrderText"] = "故障 此機不可用。", -- Draft
    ["_GameCornerOutToLunchText"] = "暫離 此機已有主。", -- Draft
    ["_GameCornerSomeonesKeysText"] = "他人之鑰在此，當復來。", -- Draft
    ["_JustAMomentText"] = "少待。", -- Draft
    ["_TurnPageText"] = "翻頁乎？", -- Draft
    ["_ViridianSchoolNotebookText5"] = "女：咄！勿窺吾筆記！", -- Draft
    ["_ViridianSchoolNotebookText1"] = "閱其筆記。第一頁……獸毬所以獲㬺獸。至多可攜六獸。畜獸而使之鬭者，謂之㬺獸士。", -- Draft
    ["_ViridianSchoolNotebookText2"] = "第二頁……健獸難獲，宜先困之。中毒、燒傷諸患皆有助。", -- Draft
    ["_ViridianSchoolNotebookText3"] = "第三頁……㬺獸士常訪同道而鬭獸。諸書院亦常有戰。", -- Draft
    ["_ViridianSchoolNotebookText4"] = "第四頁……㬺獸士之志，在勝八書院山長，乃得進而挑戰㬺獸聯會四天王。", -- Draft
    ["_EnemiesOnEverySideText"] = "四面皆敵！", -- Draft
